    modLifecycleSweep(): Promise<unknown>;
    /** Creator warnings about game versions the mod no longer fits. */
    modCompatWatchSweep(): Promise<unknown>;
    /** Advance in-flight AI mod builds from the build service. */
    syncModBuilds(): Promise<unknown>;
  };
  /** Accounts, by id. Billing identity is the host's; Cyrus only reads the basics and stores the payment customer id it creates. */
  users: {
    get(id: string): Promise<{ id: string; email: string } | null>;
    emails(ids: string[]): Promise<{ id: string; email: string }[]>;
    /** By email (case-insensitive) when `query` contains "@", otherwise by id. */
    find(query: string): Promise<{ id: string; email: string } | null>;
    setBillingCustomerId(userId: string, customerId: string): Promise<void>;
  };
  /** Background jobs the host queues (read side only). */
  jobs: {
    /** The newest finished job of one of `types` on a server, or null. */
    lastDone(serverId: string, types: string[]): Promise<{ updatedAt: Date; payload: unknown } | null>;
  };
  /** The host's game servers. */
  servers: {
    get(serverId: string): Promise<HostServerRow | null>;
    /** The user's servers that are not being deleted, oldest first. */
    listForUser(userId: string): Promise<HostServerRow[]>;
    /** Which game a server row is (e.g. "minecraft"), or null when it cannot be told. */
    familyOf(server: HostServerRow): string | null;
    /** The game family of the plan a server was bought on, or null. */
    planFamily(serverId: string): Promise<string | null>;
    /** How many paid (not free) game servers the user has. */
    paidCount(userId: string): Promise<number>;
    /** The newest "health" mod-update run on a server (log-read verdicts), or null. */
    lastHealthRun(serverId: string): Promise<{ startedAt: Date; plan: unknown } | null>;
    /** File access to ONE of this user's servers (null when it is not theirs, gone, or being deleted); `base` is the game folder on it. */
    openFiles(userId: string, serverId: string): Promise<{ fs: HostGuestFs; base: string; close?: () => void } | null>;
    /** The game version pinned in a server's config, when it names a real one. */
    pinnedVersion(config: unknown): string | null;
  };
  /** What the host has recorded as installed (its ServerMod/GameMod records). */
  records: {
    /** Installs on one server whose catalogue source is `source`. */
    onServer(serverId: string, source: string): Promise<HostInstallRow[]>;
    /** Which of `serverIds` have at least one install from `source` (each id once). */
    serversWithSource(serverIds: string[], source: string): Promise<string[]>;
    /** The catalogue entry id for a source's item, or null. */
    catalogId(source: string, sourceId: string): Promise<string | null>;
    /** Installs of one catalogue entry on any of `serverIds`. */
    ofMod(modId: string, serverIds: string[]): Promise<Omit<HostInstallRow, "mod">[]>;
    /** Everything the host recorded on one server, any source (names for prefills and the pre-install conflict report;
     *  "mods-tab" = the user's own Mods tab). Optional: absent = Cyrus reads the server's files instead. */
    allOnServer?(serverId: string): Promise<{ name: string; version: string | null; source: string; fileName: string | null; status: string; via: "mods-tab" | "cyrus" | "managed" | "other" }[]>;
  };
  /** Putting Cyrus' files on a server through the host's install engine (which keeps the host's own record of what it placed). */
  installs: {
    /** The engine's state file on the server; a pack install snapshots it so a failed install also undoes the bookkeeping. */
    readonly statePath: string;
    /** Place the prefetched package(s) of `resolution` for `mod`. Never downloads: a download attempt fails with `noDownloadMessage`. */
    install(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; resolution: HostResolution; mode: "install" | "update"; noDownloadMessage: string }): Promise<HostInstallResult>;
    /** Remove what the engine recorded for `mod` (and dependencies nothing else needs). */
    uninstall(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; noDownloadMessage: string }): Promise<HostInstallResult>;
  };
  /** Cyrus' build engine (lib/modbuilder: build rows, the build-service sync, the access rule). It is Cyrus' own code that
   *  still sits beside the platform; inside Nxeon these delegate to it unchanged. A standalone Cyrus passes its own. */
  builds: {
    /** Pull the build service's view of one build into its row (settles token holds when it finished). Never throws for an unreachable service. */
    sync(row: ModBuild): Promise<ModBuild>;
    /** Start a build or a change for `user` (plan, token and rate gates included). `body` is the build API's JSON. */
    create(user: User, body: Record<string, unknown>): Promise<CreateBuildResult>;
    /** The signed-in account allowed to use the Mod Builder (preview/public rule), or null. */
    accessUser(): Promise<User | null>;
    /** The same access rule for one account by id, without a session (API subjects), or null. */
    accountFor(userId: string): Promise<User | null>;
    /** Merge one key into a build's Cyrus metadata. */
    mergeCyrusKey(id: string, key: "engineRelease" | "testFlight" | "matrix", value: unknown): Promise<void>;
  };
  /** The host's published-mod pages and catalogue ids for Cyrus mods (Nxeon: lib/cyrus-mods). */
  mods: {
    /** The build-service id for a build (follows the version chain), as the platform recorded it. */
    serviceBuildId(buildId: string): Promise<string>;
    /** A build reached a final state: refresh its public mod page and catalogue entry. */
    onBuildSettled(row: Pick<ModBuild, "id" | "rootBuildId" | "status">): Promise<void>;
  };
  /** Money. DEFAULT (not an owner decision): the host is the payment provider, so Stripe is the host's account and the
   *  wallet is the host's wallet. lib/cyrus/host/billing-own-stripe.ts is the other option (Cyrus' own Stripe, no wallet). */
  billing: HostBilling;
  /** r40: outgoing email through the host's mail stack (Nxeon: lib/mailer.ts sendMail: SMTP relay, EmailLog, open/click
   *  tracking). OPTIONAL: a host without it sends no Cyrus email at all (fails closed; in-app notifications still work). */
  mail?: {
    send(m: { to: string; from: string; replyTo?: string; subject: string; html: string; text: string; userId: string }): Promise<boolean>;
  };
  /** r44: ad-conversion transports (Meta CAPI event, Google Ads offline conversion) for lib/cyrus/analytics/conversions.
   *  OPTIONAL: absent = nothing is ever sent. Each returns false when the host's ad config is missing. */
  conversions?: {
    meta(event: Record<string, unknown>): Promise<boolean>;
    google(event: Record<string, unknown>, userId: string): Promise<boolean>;
  };
  /** The Nxeon Platform API (per-server grants the user gave Cyrus; ./platform.ts). Present only when Cyrus runs apart
   *  from the platform (createHttpHost({ platform })); inside Nxeon it is absent and installs use the platform's own
   *  install path (lib/cyrus/delivery via worker/cyrus-delivery.ts) as before. */
  platform?: PlatformClient;
  /** Append-only audit trail; attribution to the acting admin is the host's job. */
  audit: {
    record(userId: string | null, action: string, detail?: string): Promise<void>;
    /** A plain row exactly as given (no impersonation attribution, no request IP): Cyrus' own admin trail. */
    append(row: { userId: string | null; action: string; detail?: string; category?: string; target?: string }): Promise<void>;
  };
}

/** Stripe as Cyrus uses it. Inside Nxeon: Nxeon's account, its logged checkout helper and its customer rule (lib/stripe, lib/stripe-cards). */
export interface HostStripe {
  configured(): boolean;
  /** Throws when not configured. */
  client(): Stripe;
  publishableKey(): string;
  createCheckoutSession(params: Stripe.Checkout.SessionCreateParams, options?: Stripe.RequestOptions): Promise<Stripe.Checkout.Session>;
  readonly uiMode: Stripe.Checkout.SessionCreateParams["ui_mode"];
  readonly requestOptions: Stripe.RequestOptions;
  /** The payment customer for an account (created once, idempotently, keyed on the account id). */
  ensureCustomer(user: { id: string; email: string; name?: string | null; stripeCustomerId: string | null; stripePaymentMethodId: string | null }): Promise<string>;
}
/** The host's account wallet (cents). Not used by Cyrus today: it is the "wallet debits via the host" option, ready behind the seam. */
export interface HostWallet {
  balance(userId: string): Promise<number | null>;
  /** Atomic debit; never goes negative. With `reference` it is idempotent: a second charge with the same reference
   *  debits nothing and answers `{ ok: true, replay: true }`. */
  charge(a: { userId: string; cents: number; description: string; reference?: string }): Promise<{ ok: true; replay?: boolean } | { ok: false; error: "insufficient_funds" | "invalid" }>;
  /** Credit real funds back (a refund of an earlier charge). Idempotent per `reference` like charge. */
  refund(a: { userId: string; cents: number; description: string; reference?: string }): Promise<{ ok: true; replay?: boolean } | { ok: false; error: "invalid" }>;
  /** Referenced wallet movements since a time (reconciliation): charges are negative cents, refunds positive. */
  findByReference?(a: { userId?: string; prefix: string; sinceMs: number }): Promise<{ userId: string; reference: string; cents: number; at: Date }[]>;
}

/** A purchase the payment provider completed (or refunded) for Cyrus, sent as a signed webhook when Cyrus runs apart
 *  (lib/cyrus/tokens/purchase.ts applies it; idemKey is the SAME key the direct credit path uses). */
export type PurchaseEnvelope = {
  id: string;
  type: "purchase.completed" | "purchase.refunded";
  createdAt: string;
  subject: string;
  data: { idemKey: string; kind: "topup"; method: "wallet" | "card"; tokens: number; cents: number; expiresAt: string | null; note: string | null; refundedCents?: number;
    /** r44 card top-ups: the provider's ids, kept in the ledger exactly as the direct path stored them */
    sourceRef?: string; paymentIntent?: string | null; livemode?: boolean };
};
export type HostBilling = {
  /** "host" = the platform is the payment provider (default); "own-stripe" = Cyrus' own Stripe account. */
  provider: "host" | "own-stripe";
  stripe: HostStripe | null;
  wallet: HostWallet | null;
  /** Deliver a purchase event to Cyrus over the signed webhook path (CYRUS_PURCHASE_EVENTS). Absent = credit directly. */
  emitPurchase?: (e: PurchaseEnvelope) => Promise<void>;
  /** A user's plan/token entitlement changed on the payment provider's side: tell Cyrus (Nxeon: the signed
   *  entitlement.changed event, CYRUS_PLATFORM_EVENTS). Absent = nothing to tell (one app, or no events). */
  entitlementChanged?: (userId: string) => Promise<unknown>;
};

/** Settings stored as "true"/"on"/"1" are true. Same rule as the platform's own coercion. */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

// Cyrus purchases through the payment provider (Nxeon: one Stripe + one wallet), started on either host.
// HOST SEAM: wallet + event delivery come from host.billing; no Nxeon imports.
//
//   applyPurchaseEvent  THE credit/reverse step for a purchase, keyed by the SAME idemKey the direct path uses, so the
//                       direct call, the signed webhook (Cyrus apart), a redelivery and the reconcile sweep can all
//                       run it and tokens land exactly once. purchase.refunded takes back unspent tokens of that lot.
//   deliverPurchase     direct (one app, default) or, with CYRUS_PURCHASE_EVENTS=1 and host.billing.emitPurchase,
//                       the signed webhook/outbox path -> state "pending" until the receiver applies it.
//   payTopupWithWallet  wallet top-up saga (flag CYRUS_WALLET_PAY): idempotent wallet charge (reference) -> deliver
//                       -> on a failed credit, compensating refund; a lost step is found by reconcileWalletTopups.
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import type { PurchaseEnvelope } from "../host/types";
import { loadTokenConfig } from "./config";
import { topupTokens, validTopupCents, fmt } from "./economy";
import { creditTokens, revokeTokens } from "./ledger";

const DAY = 86_400_000;
const locks = new Set<string>();
export const walletPayEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_WALLET_PAY === "1";
export const purchaseEventsEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_PURCHASE_EVENTS === "1";

export function purchaseEnvelope(type: PurchaseEnvelope["type"], subject: string, data: PurchaseEnvelope["data"], now = new Date()): PurchaseEnvelope {
  return { id: `pe_${data.idemKey}${type === "purchase.refunded" ? `:r${data.refundedCents ?? 0}` : ""}`.slice(0, 160), type, createdAt: now.toISOString(), subject, data };
}

export type ApplyResult = { applied: boolean; tokens: number };

/** Idempotent. Completed -> a token lot; refunded -> unspent tokens of that lot back (pro rata to the refund). */
export async function applyPurchaseEvent(e: PurchaseEnvelope): Promise<ApplyResult> {
  const d = e.data;
  if (!/^[A-Za-z0-9:_-]{6,160}$/.test(d.idemKey) || !e.subject) throw new Error("invalid purchase event");
  if (e.type === "purchase.completed") {
    const r = await creditTokens({
      userId: e.subject, amount: d.tokens, kind: "purchase", source: "topup", idemKey: d.idemKey,
      sourceRef: typeof d.sourceRef === "string" && /^[A-Za-z0-9:_-]{1,200}$/.test(d.sourceRef) ? d.sourceRef : d.idemKey,
      expiresAt: d.expiresAt ? new Date(d.expiresAt) : null, note: d.note,
      meta: {
        paidCents: d.cents, method: d.method, event: e.id,
        // r44: card top-ups keep the facts revenue/reconciliation read (only well-formed values cross the wire)
        ...(typeof d.paymentIntent === "string" && /^pi_[A-Za-z0-9_]{1,200}$/.test(d.paymentIntent) ? { paymentIntent: d.paymentIntent } : {}),
        ...(typeof d.livemode === "boolean" ? { livemode: d.livemode } : {}),
      },
    });
    return { applied: r.created, tokens: r.created ? r.amount : 0 };
  }
  const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: d.idemKey } });
  if (!row?.lotId || row.delta <= 0 || row.userId !== e.subject || !d.cents) return { applied: false, tokens: 0 };
  const want = Math.round(row.delta * Math.min(1, (d.refundedCents ?? 0) / d.cents));
  // r49 (re-audit C-L4): refundedCents is CUMULATIVE (Stripe's amount_refunded), so take back only what earlier refund
  // events of this purchase did not already ask for (same rule as billing.ts handleRefundedCharge)
  const prior = await db.cyrusTokenLedger.findMany({ where: { kind: "revoke", sourceRef: row.id } });
  const already = prior.reduce((a, x) => a + ((x.meta as { requested?: number } | null)?.requested ?? 0), 0);
  if (want - already <= 0) return { applied: false, tokens: 0 };
  const r = await revokeTokens({ userId: row.userId, amount: want - already, lotIds: [row.lotId], sourceRef: row.id, idemKey: `refund:${d.idemKey}:${d.refundedCents ?? 0}`, note: `Refund ${d.idemKey}`, meta: { refundedCents: d.refundedCents ?? 0 } });
  return { applied: r.created, tokens: r.revoked };
}

/** Direct credit (one app) or the signed webhook path (Cyrus apart). */
export async function deliverPurchase(e: PurchaseEnvelope): Promise<{ state: "credited" | "pending"; tokens: number }> {
  const emit = getHost().billing.emitPurchase;
  if (purchaseEventsEnabled() && emit) {
    await emit(e);
    return { state: "pending", tokens: 0 };
  }
  const r = await applyPurchaseEvent(e);
  return { state: "credited", tokens: r.tokens };
}

export type WalletPayState = "credited" | "pending" | "insufficient_funds" | "failed" | "unavailable" | "in_progress" | "invalid";
export const walletRef = (userId: string, key: string) => `cwt:${userId}:${key}`;

/** Status of a wallet top-up by its key: honest, from the ledger and the wallet itself. */
export async function walletTopupStatus(userId: string, key: string): Promise<WalletPayState> {
  const ref = walletRef(userId, key);
  if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return "credited";
  const w = getHost().billing.wallet;
  const moves = (await w?.findByReference?.({ userId, prefix: ref, sinceMs: Date.now() - 30 * DAY })) ?? [];
  const charged = moves.some((m) => m.reference === ref && m.cents < 0);
  const refunded = moves.some((m) => m.reference === `${ref}:refund` && m.cents > 0);
  return refunded ? "failed" : charged ? "pending" : "invalid";
}

export async function payTopupWithWallet(user: { id: string }, cents: number, key: string): Promise<{ state: WalletPayState; tokens: number; error?: string }> {
  const wallet = getHost().billing.wallet;
  if (!walletPayEnabled() || !wallet) return { state: "unavailable", tokens: 0, error: "Paying with your wallet isn't available right now." };
  if (!/^[A-Za-z0-9_-]{16,64}$/.test(key)) return { state: "invalid", tokens: 0, error: "Missing purchase key." };
  const cfg = await loadTokenConfig();
  if (!cfg.topup.enabled) return { state: "unavailable", tokens: 0, error: "Top-ups aren't available right now." };
  if (!validTopupCents(cents, cfg)) return { state: "invalid", tokens: 0, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
  if (cfg.topup.requiresPaid) {
    const paid = (await getHost().servers.paidCount(user.id)) + (await db.cyrusPlan.count({ where: { userId: user.id } }));
    if (!paid) return { state: "invalid", tokens: 0, error: "Top-ups are for customers with a game server or a Cyrus plan." };
  }
  const ref = walletRef(user.id, key);
  if (locks.has(ref)) return { state: "in_progress", tokens: 0 };
  locks.add(ref);
  try {
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return { state: "credited", tokens: 0 };
    const tokens = topupTokens(cents, cfg);
    const charge = await wallet.charge({ userId: user.id, cents, description: `Cyrus tokens: ${fmt(tokens)}`, reference: ref });
    if (!charge.ok) return { state: charge.error === "insufficient_funds" ? "insufficient_funds" : "invalid", tokens: 0, error: charge.error === "insufficient_funds" ? "Not enough in your wallet. Add funds or pay by card." : "Couldn't charge your wallet." };
    const e = purchaseEnvelope("purchase.completed", user.id, {
      idemKey: ref, kind: "topup", method: "wallet", tokens, cents,
      expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet)`,
    });
    try {
      const r = await deliverPurchase(e);
      return { state: r.state, tokens: r.tokens };
    } catch (err) {
      console.error("[cyrus-purchase] credit failed after wallet charge", ref, (err as Error).message);
      // Compensate: the money goes back, the purchase is honestly failed. If the refund fails too, the charge stays
      // "pending" and reconcileWalletTopups credits it later.
      try {
        await wallet.refund({ userId: user.id, cents, description: "Refund: Cyrus tokens not credited", reference: `${ref}:refund` });
        return { state: "failed", tokens: 0, error: "We couldn't add your tokens, so your wallet was refunded." };
      } catch {
        return { state: "pending", tokens: 0, error: "Your tokens are on the way. If they don't appear in a few minutes, contact support." };
      }
    }
  } finally {
    locks.delete(ref);
  }
}

/** r44 card top-ups: the envelope for a paid Checkout session (same idemKey `topup:<session>` as the old direct credit). */
export function cardTopupEnvelope(a: { userId: string; sessionId: string; tokens: number; paidCents: number; expiresAt: Date; paymentIntent: string | null; livemode: boolean }, now = new Date()): PurchaseEnvelope {
  return purchaseEnvelope("purchase.completed", a.userId, {
    idemKey: `topup:${a.sessionId}`, kind: "topup", method: "card", tokens: a.tokens, cents: a.paidCents, expiresAt: a.expiresAt.toISOString(),
    note: `Top-up $${(a.paidCents / 100).toFixed(2)}`, sourceRef: a.sessionId, paymentIntent: a.paymentIntent, livemode: a.livemode,
  }, now);
}

/** r44 reconciliation for card top-ups on the event path: a paid session whose event never landed (dead sender row,
 *  lost process) is applied directly, once (same idemKey). Only runs with CYRUS_PURCHASE_EVENTS=1 (direct mode cannot
 *  lose one). `sessions` = recent paid Cyrus top-up sessions from the payment provider. */
export async function reconcileCardTopups(envelopes: PurchaseEnvelope[], minAgeMs = 15 * 60_000, now = new Date()): Promise<{ checked: number; credited: number }> {
  if (!purchaseEventsEnabled()) return { checked: 0, credited: 0 };
  let checked = 0, credited = 0;
  for (const e of envelopes) {
    if (now.getTime() - Date.parse(e.createdAt) < minAgeMs) continue; // give the event path time first
    checked++;
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: e.data.idemKey }, select: { id: true } })) continue;
    if ((await applyPurchaseEvent(e)).applied) credited++;
  }
  return { checked, credited };
}

/** Reconciliation: any referenced wallet charge without a ledger row (and without a refund) is credited. */
export async function reconcileWalletTopups(o: { userId?: string; sinceMs?: number } = {}): Promise<{ checked: number; credited: number }> {
  const w = getHost().billing.wallet;
  if (!walletPayEnabled() || !w?.findByReference) return { checked: 0, credited: 0 };
  const cfg = await loadTokenConfig();
  const moves = await w.findByReference({ userId: o.userId, prefix: "cwt:", sinceMs: o.sinceMs ?? Date.now() - 7 * DAY });
  const refunded = new Set(moves.filter((m) => m.cents > 0 && m.reference.endsWith(":refund")).map((m) => m.reference.slice(0, -":refund".length)));
  let credited = 0, checked = 0;
  for (const m of moves) {
    if (m.cents >= 0 || refunded.has(m.reference) || locks.has(m.reference)) continue;
    checked++;
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: m.reference }, select: { id: true } })) continue;
    const cents = -m.cents;
    const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", m.userId, {
      idemKey: m.reference, kind: "topup", method: "wallet", tokens: topupTokens(cents, cfg), cents,
      expiresAt: new Date(m.at.getTime() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet, reconciled)`,
    }));
    if (r.applied) credited++;
  }
  return { checked, credited };
}

/** Refund a wallet top-up: unspent tokens of that lot come back first, then the matching share of money. */
export async function refundWalletTopup(userId: string, key: string): Promise<{ ok: boolean; tokens: number; cents: number }> {
  const ref = walletRef(userId, key);
  const w = getHost().billing.wallet;
  const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref } });
  const paid = (row?.meta as { paidCents?: number } | null)?.paidCents ?? 0;
  if (!w || !row || row.userId !== userId || !paid || row.delta <= 0) return { ok: false, tokens: 0, cents: 0 };
  const lot = row.lotId ? await db.cyrusTokenLot.findUnique({ where: { id: row.lotId } }) : null;
  const unspent = Math.min(row.delta, lot?.remaining ?? 0);
  const cents = Math.floor((paid * unspent) / row.delta);
  if (!cents) return { ok: false, tokens: 0, cents: 0 };
  const r = await applyPurchaseEvent(purchaseEnvelope("purchase.refunded", userId, { idemKey: ref, kind: "topup", method: "wallet", tokens: row.delta, cents: paid, expiresAt: null, note: null, refundedCents: cents }));
  if (r.tokens <= 0) return { ok: false, tokens: 0, cents: 0 };
  const money = Math.floor((paid * r.tokens) / row.delta);
  await w.refund({ userId, cents: money, description: "Refund: unused Cyrus tokens", reference: `${ref}:refund` });
  return { ok: true, tokens: r.tokens, cents: money };
}
// CYRUS SIDE: the plan + token ENTITLEMENT mirrored from Nxeon, the payment provider (Katara / Saka / Yakko plans and
// token packs are Nxeon products). Flag CYRUS_ENTITLEMENT_MIRROR=1 (off = nothing here runs; tierOf reads the plan row
// exactly as before).
//   apply      entitlement.changed (signed webhook, lib/cyrus/bridge/platform-events.ts) or a pulled snapshot: the plan
//              becomes the mirrored CyrusPlan row (stripeSubscriptionId "nxeon:<user>"), older versions are ignored;
//              wallet purchases are credited once by idemKey (the SAME key the direct path uses), refunds/chargebacks
//              take back that lot's unspent tokens (applyPurchaseEvent).
//   read       tierOf -> gateMirroredPlan: a 60 s in-process cache; past it, the mirror must have been CONFIRMED by
//              Nxeon within CYRUS_ENTITLEMENT_MAX_AGE_H (default 36 h), else Cyrus pulls a fresh snapshot through the
//              Platform API; if that fails too the plan counts as unknown = no paid plan (FAIL CLOSED).
//   reconcile  reconcileEntitlements(): re-pull every mirrored user not confirmed in 12 h (worker sweep, daily cadence).
// HOST SEAM: Nxeon is reached only through host.platform.
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { loadTokenConfig } from "./config";
import { topupTokens } from "./economy";
import { applyPurchaseEvent, purchaseEnvelope } from "./purchase";

type Env = Record<string, string | undefined>;
export const entitlementMirrorEnabled = (env: Env = process.env) => env.CYRUS_ENTITLEMENT_MIRROR === "1";
const maxAgeMs = (env: Env = process.env) => Math.max(1, Math.min(24 * 14, Number(env.CYRUS_ENTITLEMENT_MAX_AGE_H) || 36)) * 3600_000;
export const CACHE_TTL_MS = 60_000;
export const MIRROR_PREFIX = "nxeon:";

/** The wire shape (docs/api/nxeon-platform-v1.openapi.yaml components.schemas.Entitlement). */
export type MirrorEntitlement = {
  subject: string; version: number; issuedAt: string;
  plan: { tier: "katara" | "saka" | "all" | null; status: "active" | "trialing" | "past_due" | "canceled" | "unpaid" | "none"; periodEnd: string | null; cancelAtPeriodEnd: boolean; product: string | null };
  purchases: { idemKey: string; tokens: number | null; cents: number; method: "wallet" | "card"; at: string; refundedCents: number; chargeback: boolean }[];
  partner: { code: string; firstPaymentPct: number; recurringPct: number } | null;
};

const IDEM_RE = /^[A-Za-z0-9:_-]{6,160}$/;
export function parseEntitlement(x: unknown): MirrorEntitlement | null {
  const e = x as MirrorEntitlement;
  if (!e || typeof e !== "object" || typeof e.subject !== "string" || !/^[A-Za-z0-9_:.-]{4,128}$/.test(e.subject) || !Number.isInteger(e.version) || e.version < 0) return null;
  if (!e.plan || !["katara", "saka", "all", null].includes(e.plan.tier) || !["active", "trialing", "past_due", "canceled", "unpaid", "none"].includes(e.plan.status)) return null;
  if (e.plan.periodEnd !== null && Number.isNaN(Date.parse(e.plan.periodEnd))) return null;
  if (!Array.isArray(e.purchases) || e.purchases.length > 1000) return null;
  for (const p of e.purchases) {
    if (!p || !IDEM_RE.test(p.idemKey) || !Number.isInteger(p.cents) || p.cents <= 0 || p.cents > 10_000_000 || !Number.isInteger(p.refundedCents) || p.refundedCents < 0) return null;
    if (p.tokens !== null && (!Number.isInteger(p.tokens) || p.tokens < 0 || p.tokens > 100_000_000)) return null;
    // a purchase must belong to the subject (wallet references embed the user id)
    if (p.idemKey.startsWith("cwt:") && !p.idemKey.startsWith(`cwt:${e.subject}:`)) return null;
  }
  return e;
}

const cache = new Map<string, number>();
export function clearEntitlementCacheForTests() { cache.clear(); }

export type ApplyEntitlementResult = { plan: "applied" | "stale" | "confirmed"; credited: number; reversed: number };

/** Idempotent. Older versions never overwrite newer ones (they still CONFIRM the mirror is current). */
