      if (!/cyrus/i.test(f) && !/lib\/cyrus|cyrus_/.test(t)) continue;
      for (const m of t.matchAll(/["'](cyrus_[a-z0-9_]+)["']/g)) if (!flags.includes("`" + m[1] + "`")) missing.add(m[1] + "  (" + f + ")");
    }
