import { readBodyCapped, ReplayCache, verifyWebhook } from "@/lib/cyrus/api/v1/signing";
import { applyPurchaseEvent } from "@/lib/cyrus/tokens/purchase";
import type { PurchaseEnvelope } from "@/lib/cyrus/host/types";
import { createDoneSet } from "@/lib/cyrus/bridge/platform-events";

export const dynamic = "force-dynamic";
// r38 fix: an id counts as seen only once it was APPLIED (a 500 must be redelivered and applied, not dropped as a duplicate)
const done = createDoneSet();
const MAX = 64 * 1024;

/**
 * Cyrus side of purchase -> credit (CYRUS_PURCHASE_EVENTS=1 + CYRUS_PURCHASE_EVENTS_SECRET): Nxeon, the payment
 * provider, posts signed purchase.completed / purchase.refunded events; the credit is idempotent by the event's idemKey
 * (the same key the direct path uses), so redeliveries and the reconcile sweep never double-credit. 5xx = retry.
 */
export async function POST(req: Request) {
  const secret = process.env.CYRUS_PURCHASE_EVENTS_SECRET ?? "";
  if (process.env.CYRUS_PURCHASE_EVENTS !== "1" || secret.length < 32 || secret === process.env.AUTH_SECRET) return new Response("Not found.", { status: 404 });
  const buf = await readBodyCapped(req, MAX); // r49: capped read before the signature check
  if (!buf) return Response.json({ error: "too_large" }, { status: 413 });
  const body = buf.toString("utf8");
  const id = req.headers.get("nxeon-webhook-id");
  const v = verifyWebhook({ secret, id, timestamp: req.headers.get("nxeon-webhook-timestamp"), body, signature: req.headers.get("nxeon-signature"), nowMs: Date.now(), replay: new ReplayCache() });
  if (!v.ok) return Response.json({ error: v.code }, { status: 401 });
  if (id && done.has(id)) return Response.json({ ok: true, duplicate: true });
  let e: PurchaseEnvelope;
  try {
    e = JSON.parse(body);
    if (e.id !== id || (e.type !== "purchase.completed" && e.type !== "purchase.refunded") || typeof e.subject !== "string" || typeof e.data?.idemKey !== "string"
      || !Number.isInteger(e.data.tokens) || e.data.tokens < 0 || e.data.tokens > 100_000_000 || !Number.isInteger(e.data.cents) || e.data.cents < 0) throw new Error("shape");
  } catch {
    return Response.json({ error: "invalid_event" }, { status: 400 });
  }
  try {
    const r = await applyPurchaseEvent(e);
    done.add(e.id);
    return Response.json({ ok: true, applied: r.applied });
  } catch (err) {
    console.error("[cyrus-purchase] receiver", e.id, (err as Error).message);
    // Let the sender retry this id.
    return Response.json({ error: "retry" }, { status: 500 });
  }
}
