// Cyrus storage (r51): plan quotas, the BUY-MORE-STORAGE price table and the pricing rule. PURE + client-safe (the slider
// renders the same numbers the server charges). Every number is a PLACEHOLDER until the owner confirms it (OWNER-ACTIONS
// "r51 storage"); a Setting row overrides each default, and a blank or bad value falls back to the default, never to 0.
//
// Units: 1 GB = 2^30 bytes (binary, what `df -h` shows). Money: integer cents, monthly.
//
// The owner's per-GB rates (1 GB $0.85, 5 GB $0.75, 25 GB $0.60, 50 GB $0.30, 100 GB $0.20) read literally have a CLIFF
// (49 GB = $29.40 but 50 GB = $15.00). Rule "capped" (DEFAULT, the stated assumption):
//   rate(n)  = the rate of the highest breakpoint <= n          (bands 1-4, 5-24, 25-49, 50-99, 100+)
//   cost(n)  = min( rate(n) * n , min over breakpoints b > n of rate(b) * b )
// so fewer GB never cost more than the next breakpoint. Alternatives, one setting away (cyrus_storage_pricing_rule):
//   "literal"    rate(n) * n, the cliff as written;
//   "graduated"  each GB priced at its own band's rate (like tax brackets): no cliff, no flat stretches, dearer at volume.
export const GB = 1024 ** 3;

export type PriceBand = { fromGb: number; centsPerGb: number };
export const PRICING_RULES = ["capped", "literal", "graduated"] as const;
export type PricingRule = (typeof PRICING_RULES)[number];

/** The owner's numbers (2026-10-11), monthly. */
export const DEFAULT_PRICE_TABLE: PriceBand[] = [
  { fromGb: 1, centsPerGb: 85 },
  { fromGb: 5, centsPerGb: 75 },
  { fromGb: 25, centsPerGb: 60 },
  { fromGb: 50, centsPerGb: 30 },
  { fromGb: 100, centsPerGb: 20 },
];

/** Validate an admin-edited table: 1-10 bands, the first from 1 GB, strictly ascending whole GB, 1..100000 cents per GB. */
export function validatePriceTable(raw: unknown): { ok: true; table: PriceBand[] } | { ok: false; error: string } {
  let v = raw;
  if (typeof v === "string") { try { v = JSON.parse(v); } catch { return { ok: false, error: "Not valid JSON." }; } }
  if (!Array.isArray(v) || v.length < 1 || v.length > 10) return { ok: false, error: "Use a list of 1 to 10 bands." };
  const out: PriceBand[] = [];
  for (const [i, b] of v.entries()) {
    const fromGb = Number((b as PriceBand)?.fromGb), cents = Number((b as PriceBand)?.centsPerGb);
    if (!Number.isInteger(fromGb) || fromGb < 1 || fromGb > 100_000) return { ok: false, error: `Band ${i + 1}: fromGb must be a whole number of GB.` };
    if (!Number.isInteger(cents) || cents < 1 || cents > 100_000) return { ok: false, error: `Band ${i + 1}: centsPerGb must be 1 to 100000 cents.` };
    if (i === 0 && fromGb !== 1) return { ok: false, error: "The first band must start at 1 GB." };
    if (i > 0 && fromGb <= out[i - 1].fromGb) return { ok: false, error: "Bands must go up in GB." };
    out.push({ fromGb, centsPerGb: cents });
  }
  return { ok: true, table: out };
}

/** Cents per GB of the band n falls in (n >= 1). */
export function rateFor(gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
  let r = table[0].centsPerGb;
  for (const b of table) if (gb >= b.fromGb) r = b.centsPerGb;
  return r;
}

export const literalCents = (gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE) => (gb >= 1 ? rateFor(gb, table) * gb : 0);

export function cappedCents(gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
  if (gb < 1) return 0;
  let best = literalCents(gb, table);
  for (const b of table) if (b.fromGb > gb) best = Math.min(best, b.centsPerGb * b.fromGb);
  return best;
}

export function graduatedCents(gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
  let total = 0;
  for (const [i, b] of table.entries()) {
    const end = table[i + 1]?.fromGb ?? Infinity; // band covers [fromGb, end)
    const n = Math.max(0, Math.min(gb + 1, end) - b.fromGb);
    total += n * b.centsPerGb;
  }
  return total;
}

/** THE monthly price of `gb` extra GB under the configured rule (0 GB = 0). */
export function storagePriceCents(gb: number, rule: PricingRule = "capped", table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
  const n = Math.floor(gb);
  if (!(n >= 1)) return 0;
  return rule === "literal" ? literalCents(n, table) : rule === "graduated" ? graduatedCents(n, table) : cappedCents(n, table);
}

export type PriceRow = { gb: number; cents: number; centsPerGb: number; literalCents: number; savedCents: number };
/** The table the owner reviews (tests print it; the slider charts it). */
export function priceRows(points: number[], rule: PricingRule = "capped", table: PriceBand[] = DEFAULT_PRICE_TABLE): PriceRow[] {
  return points.map((gb) => {
    const cents = storagePriceCents(gb, rule, table), lit = literalCents(gb, table);
    return { gb, cents, centsPerGb: Math.round((cents / gb) * 100) / 100, literalCents: lit, savedCents: lit - cents };
  });
}
export const REVIEW_POINTS = [1, 2, 4, 5, 10, 19, 20, 24, 25, 30, 40, 49, 50, 60, 66, 67, 80, 99, 100, 150, 200, 500];

export const fmtCents = (c: number) => `$${(c / 100).toFixed(2)}`;
export function fmtBytes(b: number): string {
  const n = Math.max(0, b);
  if (n >= GB) return `${(n / GB).toFixed(n >= 100 * GB ? 0 : n >= 10 * GB ? 1 : 2)} GB`;
  if (n >= 1024 ** 2) return `${(n / 1024 ** 2).toFixed(n >= 100 * 1024 ** 2 ? 0 : 1)} MB`;
  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
  return `${n} B`;
}

// ---------------------------------------------------------------------------
// Proration of a mid-period change (monthly add-on)
// ---------------------------------------------------------------------------

export type ChangePlan =
  | { kind: "new"; chargeCents: number; effective: "now" }
  | { kind: "increase"; chargeCents: number; effective: "now" }
  | { kind: "decrease"; chargeCents: 0; effective: "period_end" }
  | { kind: "same"; chargeCents: 0; effective: "now" };

/** Increase = the price difference for the rest of the period, charged now (rounded up to the cent); the next renewal
 *  charges the full new price. Decrease (or cancel, toGb 0) = nothing back mid-period, the smaller amount starts at the
 *  next renewal (the customer keeps what they paid for until then). */
export function planChange(a: { fromGb: number; toGb: number; periodStart: Date | null; periodEnd: Date | null; now: Date; rule?: PricingRule; table?: PriceBand[] }): ChangePlan {
  const price = (g: number) => storagePriceCents(g, a.rule, a.table);
  if (a.fromGb <= 0 || !a.periodEnd || !a.periodStart || a.periodEnd.getTime() <= a.now.getTime()) return a.toGb > 0 ? { kind: "new", chargeCents: price(a.toGb), effective: "now" } : { kind: "same", chargeCents: 0, effective: "now" };
  if (a.toGb === a.fromGb) return { kind: "same", chargeCents: 0, effective: "now" };
  if (a.toGb < a.fromGb) return { kind: "decrease", chargeCents: 0, effective: "period_end" };
  const total = a.periodEnd.getTime() - a.periodStart.getTime();
  const left = Math.max(0, Math.min(total, a.periodEnd.getTime() - a.now.getTime()));
  const diff = Math.max(0, price(a.toGb) - price(a.fromGb));
  return { kind: "increase", chargeCents: total > 0 ? Math.ceil((diff * left) / total) : diff, effective: "now" };
}

/** One calendar month later (end of month clamps: Jan 31 -> Feb 28/29). */
export function addMonth(d: Date): Date {
  const y = d.getUTCFullYear(), m = d.getUTCMonth(), day = d.getUTCDate();
  const last = new Date(Date.UTC(y, m + 2, 0)).getUTCDate();
  return new Date(Date.UTC(y, m + 1, Math.min(day, last), d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds(), d.getUTCMilliseconds()));
}

