// Cyrus storage settings (r51). Pure + client-safe except `loadStorageConfig` (settings read, server only, dynamic import).
// Every default is a PLACEHOLDER pending the owner (OWNER-ACTIONS "r51 storage"). A Setting row overrides its default; a
// blank or bad value falls back to the default (never to 0), like the token economy.
//
// Env switches (off = nothing in lib/cyrus/storage changes any request):
//   CYRUS_STORAGE=1          meter + accounting + SERVER-SIDE enforcement on builds, uploads, asset saves, library
//                            contributions and new Mod Pack versions (installing, keeping, exporting are never blocked)
//   CYRUS_STORAGE_ADDONS=1   buy more storage (monthly add-on through Nxeon: wallet, or card via Nxeon's Stripe)
import type { TokenTier } from "../tokens/config";
import { DEFAULT_PRICE_TABLE, GB, PRICING_RULES, validatePriceTable, type PriceBand, type PricingRule } from "./pricing";

type Env = Record<string, string | undefined>;
export const storageEnabled = (env: Env = process.env) => env.CYRUS_STORAGE === "1";
export const storageAddonsEnabled = (env: Env = process.env) => storageEnabled(env) && env.CYRUS_STORAGE_ADDONS === "1";

export const STORAGE_DEFAULTS = {
  /** Free accounts (no plan): PLACEHOLDER, the owner did not set one. */
  cyrus_storage_quota_free_gb: "1",
  cyrus_storage_quota_katara_gb: "5",
  cyrus_storage_quota_saka_gb: "25",
  /** Yakko (tier key "all"). */
  cyrus_storage_quota_all_gb: "50",
  /** Buy-more price bands, monthly: JSON [{fromGb, centsPerGb}] (the owner's numbers). */
  cyrus_storage_price_table: JSON.stringify(DEFAULT_PRICE_TABLE),
  /** capped (default: fewer GB never cost more than the next breakpoint) | literal (the cliff as written) | graduated. */
  cyrus_storage_pricing_rule: "capped",
  /** Largest add-on one account may buy. */
  cyrus_storage_addon_max_gb: "500",
  /** After a quota DROP (downgrade, cancel, refund, failed renewal, plan lapse) an over-quota account may keep writing
   *  this many days; after it, new builds / uploads / contributions are refused until it is under quota again. Data is
   *  never deleted automatically. */
  cyrus_storage_grace_days: "30",
  /** Meter warning levels in percent (the last one is "full"). */
  cyrus_storage_warn_pcts: "80,95,100",
  /** Cleanup suggestions: old build versions / drafts untouched this long. */
  cyrus_storage_retention_days: "90",
  /** Admin: estimated disk cost, USD per GB per month (an input for the cost estimate, not a price). */
  cyrus_storage_disk_cost_usd_gb_month: "0.05",
  /** Admin alerts: a disk or pool above these percentages. */
  cyrus_storage_pool_warn_pct: "80",
  cyrus_storage_pool_crit_pct: "90",
} as const;
export type StorageSettingKey = keyof typeof STORAGE_DEFAULTS;
export const STORAGE_SETTING_KEYS = Object.keys(STORAGE_DEFAULTS) as StorageSettingKey[];
export const STORAGE_PLACEHOLDER_KEYS: readonly StorageSettingKey[] = STORAGE_SETTING_KEYS;

export type StorageConfig = {
  quotaGb: Record<TokenTier, number>;
  table: PriceBand[];
  rule: PricingRule;
  addonMaxGb: number;
  graceDays: number;
  warnPcts: [number, number, number];
  retentionDays: number;
  diskCostUsdPerGbMonth: number;
  poolWarnPct: number;
  poolCritPct: number;
};

const num = (v: string | undefined, d: string, min: number, max: number, int = true): number => {
  const n = Number(v);
  if (v === undefined || v.trim() === "" || !Number.isFinite(n) || n < min || n > max || (int && !Number.isInteger(n))) return Number(d);
  return n;
};

export function parseStorageConfig(stored: Record<string, string | undefined> = {}): StorageConfig {
  const D = STORAGE_DEFAULTS;
  const g = (k: StorageSettingKey, min: number, max: number, int = true) => num(stored[k], D[k], min, max, int);
  const t = validatePriceTable(stored.cyrus_storage_price_table ?? "");
  const rule = (PRICING_RULES as readonly string[]).includes(stored.cyrus_storage_pricing_rule ?? "") ? (stored.cyrus_storage_pricing_rule as PricingRule) : (D.cyrus_storage_pricing_rule as PricingRule);
  const w = String(stored.cyrus_storage_warn_pcts ?? "").split(",").map((x) => Number(x.trim()));
  const warnOk = w.length === 3 && w.every((x) => Number.isInteger(x) && x >= 1 && x <= 100) && w[0] < w[1] && w[1] < w[2];
  const warnPcts = (warnOk ? w : D.cyrus_storage_warn_pcts.split(",").map(Number)) as [number, number, number];
  const warn = g("cyrus_storage_pool_warn_pct", 1, 99), crit = g("cyrus_storage_pool_crit_pct", 1, 100);
  return {
    quotaGb: {
      free: g("cyrus_storage_quota_free_gb", 0, 10_000, false),
      katara: g("cyrus_storage_quota_katara_gb", 0, 10_000, false),
      saka: g("cyrus_storage_quota_saka_gb", 0, 10_000, false),
      all: g("cyrus_storage_quota_all_gb", 0, 10_000, false),
    },
    table: t.ok ? t.table : DEFAULT_PRICE_TABLE,
    rule,
    addonMaxGb: g("cyrus_storage_addon_max_gb", 1, 100_000),
    graceDays: g("cyrus_storage_grace_days", 0, 365),
    warnPcts,
    retentionDays: g("cyrus_storage_retention_days", 1, 3650),
    diskCostUsdPerGbMonth: g("cyrus_storage_disk_cost_usd_gb_month", 0, 100, false),
    poolWarnPct: warn < crit ? warn : Number(D.cyrus_storage_pool_warn_pct),
    poolCritPct: warn < crit ? crit : Number(D.cyrus_storage_pool_crit_pct),
  };
}

/** Plan quota + add-on, in bytes. */
export const quotaBytes = (tier: TokenTier, addonGb: number, cfg: StorageConfig) => Math.round((cfg.quotaGb[tier] + Math.max(0, addonGb)) * GB);

export type MeterLevel = "ok" | "warn" | "high" | "full";
/** ok < warn% <= warn < high% <= high < full% <= full. Quota 0 with any usage = full. */
export function meterLevel(usedBytes: number, quota: number, cfg: Pick<StorageConfig, "warnPcts">): { level: MeterLevel; pct: number } {
  if (quota <= 0) return { level: usedBytes > 0 ? "full" : "ok", pct: usedBytes > 0 ? 100 : 0 };
  const pct = (usedBytes / quota) * 100;
  const [w, h, f] = cfg.warnPcts;
  return { level: pct >= f ? "full" : pct >= h ? "high" : pct >= w ? "warn" : "ok", pct: Math.round(pct * 10) / 10 };
}

