export async function loadStorageConfig(fresh = false): Promise<StorageConfig> {
  if (!fresh && cache && Date.now() - cache.at < 30_000) return cache.cfg;
  const { getHost } = await import("../host");
  const cfg = parseStorageConfig(await getHost().settings.readStoredPrefix("cyrus_storage_"));
  cache = { cfg, at: Date.now() };
  return cfg;
}
export function clearStorageConfigCache() { cache = null; }

