// r51 storage: the buy-more pricing function, the plan quotas and the settings. Prints the price table for the owner
// (run: npx tsx --test test/cyrus-storage-pricing.test.ts).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { addMonth, cappedCents, DEFAULT_PRICE_TABLE, GB, graduatedCents, literalCents, planChange, priceRows, rateFor, REVIEW_POINTS, sameePriceUpTo, storagePriceCents, validatePriceTable } from "../lib/cyrus/storage/pricing";
import { meterLevel, parseStorageConfig, quotaBytes, STORAGE_DEFAULTS } from "../lib/cyrus/storage/config";
import { CYRUS_SETTINGS, validateSettingValue } from "../lib/cyrus/admin/settings-catalog";

describe("storage pricing (owner's table, rule capped)", () => {
  it("prints the review table", () => {
    const rows = priceRows(REVIEW_POINTS);
    console.log("\n  GB   | capped  | $/GB  | literal | graduated");
    for (const r of rows) console.log(`  ${String(r.gb).padStart(4)} | ${("$" + (r.cents / 100).toFixed(2)).padStart(7)} | ${(r.centsPerGb / 100).toFixed(3)} | ${("$" + (r.literalCents / 100).toFixed(2)).padStart(7)} | $${(graduatedCents(r.gb) / 100).toFixed(2)}`);
    assert.equal(rows.length, REVIEW_POINTS.length);
  });

  it("band rates by breakpoint (1-4, 5-24, 25-49, 50-99, 100+)", () => {
    assert.deepEqual([1, 4, 5, 24, 25, 49, 50, 99, 100, 1000].map((g) => rateFor(g)), [85, 85, 75, 75, 60, 60, 30, 30, 20, 20]);
  });

  it("exact capped prices at the review points", () => {
