// Cyrus storage accounting (r51). PURE + client-safe: what counts, dedupe, per-mod / per-game rollups, the over-quota
// state machine and the write decision. The collector (./collect.ts) turns rows and files into StorageItems; the
// service (./service.ts) stores the result.
//
// WHAT COUNTS (one account):
//   builds     each stored build jar (ModBuild.jarPath set: jarSize, content key jarSha256)
//   assets     project assets (CyrusProjectAsset: size, key sha256), textures, sounds, models, designs, configs
//   revisions  each revision's spec + manifest + engine record as stored (Postgres column sizes)
//   packs      each Mod Pack version archive (.nxpack zip: bytes, key sha256)
//   drafts     autosaved studio drafts (CyrusModelDraft doc size)
//   uploads    reference images: pending uploads and the copies attached to builds
//   library    library contributions you own that are not removed (catalog entry bytes, key sha256)
// DEDUPE: content-addressed bytes (same sha256) count ONCE per account, under the first category in CATEGORY_ORDER that
// holds them. Rows without a content hash (revisions, drafts, uploads) count per row. Per mod and per game a file counts
// once inside that mod / game, so a file two mods share shows in both mods, while the account total counts it once.
// Never counted: the shared asset library itself, other creators' content, installs on servers (they live on the server).
export const CATEGORY_ORDER = ["builds", "assets", "packs", "revisions", "drafts", "uploads", "library"] as const;
export type StorageCategory = (typeof CATEGORY_ORDER)[number];
export const CATEGORY_LABEL: Record<StorageCategory, string> = {
  builds: "Builds (jars)",
  assets: "Assets (textures, sounds, models, designs)",
  packs: "Mod Packs",
  revisions: "Revisions and specs",
  drafts: "Studio drafts",
  uploads: "Uploads and reference images",
  library: "Library contributions you own",
};

export type StorageItem = {
  /** "sha256:<hex>" for content-addressed bytes, "row:<kind>:<id>" otherwise */
  key: string;
  bytes: number;
  category: StorageCategory;
  /** the mod (ModBuild chain root, or "p:<projectId>" for a project with no build) */
  modId: string | null;
  game: string | null;
  label?: string | null;
  at?: string | null;
};

export type ModRollup = { modId: string; game: string | null; label: string | null; bytes: number; byCategory: Partial<Record<StorageCategory, number>>; items: number };
export type StorageBreakdown = {
  totalBytes: number;
  /** before dedupe */
  rawBytes: number;
  dedupedBytes: number;
  items: number;
  byCategory: Record<StorageCategory, number>;
  byGame: Record<string, number>;
  byMod: ModRollup[];
  modsTruncated: number;
};

export const MAX_MODS_STORED = 200;
const rank = (c: StorageCategory) => CATEGORY_ORDER.indexOf(c);
const clean = (n: number) => (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0);

export function rollup(items: StorageItem[]): StorageBreakdown {
  const byKey = new Map<string, StorageItem>();
  let raw = 0;
  for (const it of items) {
    const b = clean(it.bytes);
    raw += b;
    const cur = byKey.get(it.key);
    if (!cur || rank(it.category) < rank(cur.category)) byKey.set(it.key, { ...it, bytes: Math.max(b, cur?.bytes ?? 0) });
    else if (b > cur.bytes) cur.bytes = b;
  }
  const byCategory = Object.fromEntries(CATEGORY_ORDER.map((c) => [c, 0])) as Record<StorageCategory, number>;
  let total = 0;
  for (const it of byKey.values()) { byCategory[it.category] += it.bytes; total += it.bytes; }

  const mods = new Map<string, { r: ModRollup; keys: Set<string> }>();
  const games = new Map<string, Set<string>>();
  const gameBytes: Record<string, number> = {};
  for (const it of items) {
    const b = clean(it.bytes);
    const g = it.game ?? "unassigned";
    const gs = games.get(g) ?? new Set<string>();
    if (!gs.has(it.key)) { gs.add(it.key); gameBytes[g] = (gameBytes[g] ?? 0) + b; }
    games.set(g, gs);
    if (!it.modId) continue;
    const m = mods.get(it.modId) ?? { r: { modId: it.modId, game: it.game, label: it.label ?? null, bytes: 0, byCategory: {}, items: 0 }, keys: new Set<string>() };
    if (!m.r.label && it.label) m.r.label = it.label;
    if (!m.keys.has(it.key)) {
      m.keys.add(it.key);
      m.r.bytes += b; m.r.items++;
      m.r.byCategory[it.category] = (m.r.byCategory[it.category] ?? 0) + b;
    }
    mods.set(it.modId, m);
  }
  const all = [...mods.values()].map((m) => m.r).sort((a, b) => b.bytes - a.bytes || a.modId.localeCompare(b.modId));
  return { totalBytes: total, rawBytes: raw, dedupedBytes: raw - total, items: byKey.size, byCategory, byGame: gameBytes, byMod: all.slice(0, MAX_MODS_STORED), modsTruncated: Math.max(0, all.length - MAX_MODS_STORED) };
}

// ---------------------------------------------------------------------------
// Over quota: grace after a quota DROP, read-only for new writes after it. Nothing is ever deleted automatically.
// ---------------------------------------------------------------------------

export type OverState = { overSince: Date | null; graceUntil: Date | null };

/** Called on every recompute. Grace starts when usage is over a quota that went DOWN since the last recompute
 *  (downgrade, cancel, refund, failed renewal, plan lapse) or on the account's first measurement (launch day); going over
 *  by your own new writes has no grace (the write gate refuses them first; only a build's own output can cross). */
export function nextOverState(a: { usedBytes: number; quotaBytes: number; prevQuotaBytes: number | null; prev: OverState | null; graceDays: number; now: Date }): OverState {
  if (a.usedBytes <= a.quotaBytes) return { overSince: null, graceUntil: null };
  const overSince = a.prev?.overSince ?? a.now;
  if (a.prev?.graceUntil) return { overSince, graceUntil: a.prev.graceUntil };
  const dropped = a.prevQuotaBytes === null || a.quotaBytes < a.prevQuotaBytes;
  return { overSince, graceUntil: dropped && a.graceDays > 0 ? new Date(a.now.getTime() + a.graceDays * 86_400_000) : null };
}

export type WriteKind = "build" | "upload" | "asset" | "library" | "pack" | "import";
export type WriteDecision = { ok: true; grace: boolean } | { ok: false; code: "storage_full" | "storage_unknown"; usedBytes: number; quotaBytes: number };

/** The ONE rule: a write of `addBytes` (0 = unknown size, e.g. a build) is allowed while used + pending + add stays within
 *  the quota (a build needs room left), or while a grace period runs. */
export function storageWriteDecision(a: { usedBytes: number; pendingBytes: number; quotaBytes: number; addBytes: number; graceUntil: Date | null; now: Date }): WriteDecision {
  const total = a.usedBytes + a.pendingBytes;
  const fits = a.addBytes > 0 ? total + a.addBytes <= a.quotaBytes : total < a.quotaBytes;
  if (fits) return { ok: true, grace: false };
  if (a.graceUntil && a.now.getTime() < a.graceUntil.getTime()) return { ok: true, grace: true };
  return { ok: false, code: "storage_full", usedBytes: total, quotaBytes: a.quotaBytes };
}

export const STORAGE_FULL_CODE = "storage_full";
export function storageFullMessage(what: WriteKind): string {
  const verb = what === "build" ? "start a new build" : what === "upload" ? "upload this file" : what === "pack" ? "save a new pack version" : what === "import" ? "import this mod" : what === "library" ? "add to the library" : "save this asset";
  return `Your Cyrus storage is full, so we couldn't ${verb}. Nothing was started or charged. Free up space or add storage under Account, Storage. Installing, keeping and exporting your mods still works.`;
}

