// Cyrus storage collector (r51), SERVER ONLY: where an account's bytes live today -> StorageItems (./accounting.ts).
//   builds     ModBuild rows (jarPath/jarSize/jarSha256; jars on disk in NXEON_MODBUILD_DIR/<id>.jar)
//   uploads    NXEON_MODBUILD_DIR/uploads/<user>/ (pending, 24 h) + per-build attachment copies (ModBuild.cyrus.attachments)
//   assets     CyrusProjectAsset (size, sha256; bytes under the project store or inline in specs)
//   revisions  CyrusRevision spec + manifest + engine (pg_column_size)
//   drafts     CyrusModelDraft doc (pg_column_size)
//   packs      NXEON_MODBUILD_DIR/modpacks/<user>/<pack>/<version>.zip (pack.json lists bytes + sha256)
//   library    CyrusCatalogEntry contributed by this account (opaque contributor id = HMAC of the user id), not removed
// HOST SEAM: Cyrus tables only through cyrusDb; files through Node fs under Cyrus' own directories.
import { readdir, stat } from "node:fs/promises";
import path from "node:path";
import { cyrusDb as db } from "../db";
import { cyrusConfig } from "../config";
import type { StorageItem } from "./accounting";

export type BuildRow = { id: string; rootBuildId: string | null; pluginName: string | null; jarSha256: string | null; jarSize: number | null; jarPath: string | null; createdAt: Date; cyrus: unknown };
export type ProjectRow = { id: string; game: string; rootBuildId: string | null; title: string | null };
export interface StorageSources {
  builds(userId: string): Promise<BuildRow[]>;
  projects(userId: string): Promise<ProjectRow[]>;
  assets(projectIds: string[]): Promise<{ id: string; projectId: string; sha256: string; size: number; createdAt: Date }[]>;
  revisions(projectIds: string[]): Promise<{ id: string; projectId: string; bytes: number; createdAt: Date }[]>;
  drafts(userId: string): Promise<{ id: string; projectId: string; bytes: number; updatedAt: Date }[]>;
  packs(userId: string): Promise<{ packId: string; name: string; versions: { versionId: string; sha256: string; bytes: number; createdAt: string }[] }[]>;
  uploads(userId: string): Promise<{ name: string; bytes: number }[]>;
  library(userId: string): Promise<{ id: string; bytes: number }[]>;
}

const iso = (d: Date | string | null | undefined) => (d ? new Date(d).toISOString() : null);
const SHA = /^[0-9a-f]{64}$/;

export async function collectItems(userId: string, src: StorageSources): Promise<StorageItem[]> {
  const [builds, projects, packs, uploads, library, drafts] = await Promise.all([src.builds(userId), src.projects(userId), src.packs(userId), src.uploads(userId), src.library(userId), src.drafts(userId)]);
  const out: StorageItem[] = [];
  const labelOf = new Map<string, string>();
  for (const b of builds) {
    const modId = b.rootBuildId ?? b.id;
    if (b.pluginName && !labelOf.has(modId)) labelOf.set(modId, b.pluginName);
    if (b.jarPath && b.jarSize) out.push({ key: b.jarSha256 && SHA.test(b.jarSha256) ? `sha256:${b.jarSha256}` : `row:jar:${b.id}`, bytes: b.jarSize, category: "builds", modId, game: "minecraft", label: b.pluginName, at: iso(b.createdAt) });
    const att = (b.cyrus as { attachments?: { n?: number; size?: number }[] } | null)?.attachments;
    if (Array.isArray(att)) for (const a of att) if (Number(a?.size) > 0) out.push({ key: `row:att:${b.id}:${a.n ?? 0}`, bytes: Number(a.size), category: "uploads", modId, game: "minecraft", label: b.pluginName, at: iso(b.createdAt) });
  }
  const proj = new Map(projects.map((p) => [p.id, p]));
  const modOf = (projectId: string) => { const p = proj.get(projectId); return p ? (p.rootBuildId ?? `p:${p.id}`) : null; };
  const gameOf = (projectId: string) => proj.get(projectId)?.game ?? null;
  const lbl = (projectId: string) => { const m = modOf(projectId); return (m && labelOf.get(m)) || proj.get(projectId)?.title || null; };
  const ids = projects.map((p) => p.id);
  const [assets, revisions] = ids.length ? await Promise.all([src.assets(ids), src.revisions(ids)]) : [[], []];
  for (const a of assets) out.push({ key: SHA.test(a.sha256) ? `sha256:${a.sha256}` : `row:asset:${a.id}`, bytes: a.size, category: "assets", modId: modOf(a.projectId), game: gameOf(a.projectId), label: lbl(a.projectId), at: iso(a.createdAt) });
  for (const r of revisions) out.push({ key: `row:rev:${r.id}`, bytes: r.bytes, category: "revisions", modId: modOf(r.projectId), game: gameOf(r.projectId), label: lbl(r.projectId), at: iso(r.createdAt) });
  for (const d of drafts) out.push({ key: `row:draft:${d.id}`, bytes: d.bytes, category: "drafts", modId: modOf(d.projectId), game: gameOf(d.projectId), label: lbl(d.projectId), at: iso(d.updatedAt) });
