  for (const u of uploads) out.push({ key: `row:upload:${u.name}`, bytes: u.bytes, category: "uploads", modId: null, game: null, label: null, at: null });
  for (const l of library) out.push({ key: SHA.test(l.id) ? `sha256:${l.id}` : `row:lib:${l.id}`, bytes: l.bytes, category: "library", modId: null, game: null, label: null, at: null });
  return out;
}

