/** Full recompute of one account: collect -> dedupe/rollup -> quota -> over-quota state -> store. */
export async function recomputeStorage(userId: string): Promise<AccountStorage> {
  const d = deps();
  const now = d.now();
  const before = await db.cyrusStorageAccount.findUnique({ where: { userId } });
  const pendingSeen = N(before?.pendingBytes);
  const [items, tier, cfg] = await Promise.all([collectItems(userId, d.sources), d.tier(userId), d.config()]);
  const b = rollup(items);
  const quota = quotaBytes(tier, effectiveAddonGb(before, now), cfg);
  const over = nextOverState({ usedBytes: b.totalBytes, quotaBytes: quota, prevQuotaBytes: before ? N(before.quotaBytes) : null, prev: before ? { overSince: before.overSince, graceUntil: before.graceUntil } : null, graceDays: cfg.graceDays, now });
  const data = { usedBytes: BigInt(b.totalBytes), quotaBytes: BigInt(quota), breakdown: b as unknown as object, computedAt: now, dirtyAt: null, overSince: over.overSince, graceUntil: over.graceUntil };
  const row = await db.cyrusStorageAccount.upsert({
    where: { userId },
    create: { userId, ...data, pendingBytes: BigInt(0) },
    // writes that landed while we collected stay pending (they may or may not be in this measurement: never under-count)
    update: { ...data, pendingBytes: { decrement: BigInt(pendingSeen) } },
  });
  if (N(row.pendingBytes) < 0) await db.cyrusStorageAccount.update({ where: { userId }, data: { pendingBytes: BigInt(0) } });
  return view({ ...row, pendingBytes: BigInt(Math.max(0, N(row.pendingBytes))) }, tier, cfg, now);
}

/** The account's storage as stored, recomputed when missing, stale (24 h) or when its quota went down since. */
export async function accountStorage(userId: string): Promise<AccountStorage> {
  const d = deps();
  const now = d.now();
  const row = await db.cyrusStorageAccount.findUnique({ where: { userId } });
  if (!row || !row.computedAt || now.getTime() - row.computedAt.getTime() > STALE_MS || row.dirtyAt) return recomputeStorage(userId);
  const [tier, cfg] = await Promise.all([d.tier(userId), d.config()]);
  const live = quotaBytes(tier, effectiveAddonGb(row, now), cfg);
  if (live < N(row.quotaBytes) && N(row.usedBytes) + N(row.pendingBytes) > live) return recomputeStorage(userId); // a drop: start the grace
  return view(row, tier, cfg, now);
}

export type StorageGate = { ok: true; grace: boolean } | { ok: false; status: 507 | 503; code: string; error: string; usedBytes?: number; quotaBytes?: number };

/** THE server-side gate for new builds, uploads, asset saves, library contributions, pack versions and imports.
 *  Off = allowed. On = fail CLOSED: if usage cannot be read the write is refused. Never call it for installs,
 *  downloads, exports or deletes. */
export async function checkStorageWrite(userId: string, addBytes: number, what: WriteKind): Promise<StorageGate> {
  if (!storageEnabled()) return { ok: true, grace: false };
  try {
    const s = await accountStorage(userId);
    const d = storageWriteDecision({ usedBytes: s.usedBytes, pendingBytes: s.pendingBytes, quotaBytes: s.quotaBytes, addBytes: Math.max(0, Math.floor(addBytes)), graceUntil: s.graceUntil, now: deps().now() });
    if (d.ok) return d;
    return { ok: false, status: 507, code: STORAGE_FULL_CODE, error: storageFullMessage(what), usedBytes: d.usedBytes, quotaBytes: d.quotaBytes };
  } catch (e) {
    console.error("[cyrus-storage] gate failed closed", userId, (e as Error).message);
    return { ok: false, status: 503, code: "storage_unknown", error: "We couldn't check your Cyrus storage just now, so nothing was started or charged. Please try again in a minute." };
  }
}

/** Incremental update after a write: the bytes count at once (pending), the next sweep recomputes exactly. Best effort. */
export async function noteStorageWrite(userId: string, bytes: number): Promise<void> {
  if (!storageEnabled() || !userId) return;
  const add = BigInt(Math.max(0, Math.floor(bytes)));
  const now = deps().now();
  await db.cyrusStorageAccount.upsert({ where: { userId }, create: { userId, pendingBytes: add, dirtyAt: now }, update: { pendingBytes: { increment: add }, dirtyAt: now } })
    .catch((e) => console.error("[cyrus-storage] note write", (e as Error).message));
}
/** Something was removed or changed size: recompute on the next sweep. */
export async function markStorageDirty(userId: string): Promise<void> { await noteStorageWrite(userId, 0); }

const dayKey = (d: Date) => d.toISOString().slice(0, 10);

/** Sweep (worker, every 5 min): recompute dirty and stale accounts (batch), then today's snapshot once. */
export async function storageSweep(batch = 50): Promise<{ recomputed: number; snapshot: boolean }> {
  if (!storageEnabled()) return { recomputed: 0, snapshot: false };
  const now = deps().now();
  const rows = await db.cyrusStorageAccount.findMany({ where: { OR: [{ dirtyAt: { not: null } }, { computedAt: null }, { computedAt: { lt: new Date(now.getTime() - STALE_MS) } }] }, select: { userId: true }, orderBy: { dirtyAt: "asc" }, take: batch });
  let recomputed = 0;
  for (const r of rows) { try { await recomputeStorage(r.userId); recomputed++; } catch (e) { console.error("[cyrus-storage] recompute", r.userId, (e as Error).message); } }
  return { recomputed, snapshot: await takeSnapshot(now) };
}

export async function takeSnapshot(now: Date): Promise<boolean> {
  const day = dayKey(now);
  if (await db.cyrusStorageSnapshot.findUnique({ where: { day }, select: { day: true } })) return false;
  const agg = await db.cyrusStorageAccount.aggregate({ _sum: { usedBytes: true, pendingBytes: true }, _count: { userId: true } });
  const over = await db.cyrusStorageAccount.count({ where: { overSince: { not: null } } });
  const addons = await db.cyrusStorageAccount.aggregate({ where: { addonStatus: "active" }, _sum: { addonGb: true }, _count: { userId: true } });
  await db.cyrusStorageSnapshot.create({ data: { day, totalBytes: BigInt(N(agg._sum.usedBytes) + N(agg._sum.pendingBytes)), accounts: agg._count.userId, detail: { over, addonAccounts: addons._count.userId, addonGb: addons._sum.addonGb ?? 0 } } }).catch(() => undefined);
  return true;
}

