// Cyrus storage cleanup (r51), SERVER ONLY. Customer-initiated, with a typed confirm; NOTHING here runs automatically.
//   old build versions  the stored jar of a finished version that is NOT the newest version of its mod, NOT installed
//                       anywhere (lastInstall), NOT in a Mod Pack and NOT the build of a project head / last passing
//                       revision. The build row, its history and spec stay; only the jar file goes ("ask for a change"
//                       rebuilds it). Suggested when older than cyrus_storage_retention_days.
//   studio drafts       autosaved, never-saved studio work (CyrusModelDraft); suggested when untouched that long.
//   pending uploads     reference images not attached to a build yet (they expire after 24 h anyway).
// Revisions and project assets are append-only history and are never offered here.
import { readdir, stat, unlink } from "node:fs/promises";
import path from "node:path";
import { cyrusDb as db } from "../db";
import { cyrusConfig } from "../config";
import { getHost } from "../host";
import { loadStorageConfig } from "./config";
import { markStorageDirty } from "./service";

export const CLEANUP_CONFIRM = "DELETE";
const DAY = 86_400_000;

export type CleanupCandidates = {
  builds: { id: string; modId: string; label: string | null; version: string | null; bytes: number; createdAt: string; suggested: boolean }[];
  drafts: { id: string; projectId: string; assetKey: string; surface: string; bytes: number; updatedAt: string; suggested: boolean }[];
  uploads: { name: string; bytes: number }[];
  retentionDays: number;
};

/** Pure: which finished builds' jars may go (see the header). */
export function removableBuilds<T extends { id: string; rootBuildId: string | null; status: string; jarPath: string | null; createdAt: Date; lastInstall: unknown }>(rows: T[], protectedIds: Set<string>): T[] {
  const newest = new Map<string, T>();
  for (const r of rows) {
    if (r.status !== "succeeded") continue;
    const k = r.rootBuildId ?? r.id;
    const cur = newest.get(k);
    if (!cur || r.createdAt.getTime() > cur.createdAt.getTime()) newest.set(k, r);
  }
  return rows.filter((r) => r.status === "succeeded" && !!r.jarPath && newest.get(r.rootBuildId ?? r.id)?.id !== r.id && !r.lastInstall && !protectedIds.has(r.id));
}

async function protectedBuildIds(userId: string): Promise<Set<string>> {
  const out = new Set<string>();
  const projects = await db.cyrusProject.findMany({ where: { userId }, select: { headRevisionId: true, lastPassingRevisionId: true } });
  const revIds = projects.flatMap((p) => [p.headRevisionId, p.lastPassingRevisionId]).filter((x): x is string => !!x);
  if (revIds.length) for (const r of await db.cyrusRevision.findMany({ where: { id: { in: revIds } }, select: { modBuildId: true } })) if (r.modBuildId) out.add(r.modBuildId);
  try {
    const { FsModPackStore } = await import("../modpack/store");
    for (const p of await new FsModPackStore().list(userId)) for (const m of p.members) out.add(m.buildId);
  } catch { /* no packs */ }
  return out;
}

const uploadsDir = (userId: string) => path.join(cyrusConfig().modbuildDir, "uploads", userId.replace(/[^A-Za-z0-9_-]/g, ""));

export async function cleanupCandidates(userId: string, now = new Date()): Promise<CleanupCandidates> {
  const cfg = await loadStorageConfig();
  const cutoff = now.getTime() - cfg.retentionDays * DAY;
  const rows = await db.modBuild.findMany({ where: { userId, status: "succeeded", jarPath: { not: null } }, select: { id: true, rootBuildId: true, status: true, jarPath: true, jarSize: true, createdAt: true, lastInstall: true, pluginName: true, version: true }, take: 5000 });
  const builds = removableBuilds(rows, await protectedBuildIds(userId))
    .map((r) => ({ id: r.id, modId: r.rootBuildId ?? r.id, label: r.pluginName, version: r.version, bytes: r.jarSize ?? 0, createdAt: r.createdAt.toISOString(), suggested: r.createdAt.getTime() < cutoff }))
    .sort((a, b) => b.bytes - a.bytes);
  const drafts = (await db.$queryRaw<{ id: string; projectId: string; assetKey: string; surface: string; bytes: number; updatedAt: Date }[]>`
    SELECT id, "projectId", "assetKey", surface, COALESCE(pg_column_size(doc), 0)::int AS bytes, "updatedAt" FROM "CyrusModelDraft" WHERE "ownerRef" = ${userId} ORDER BY "updatedAt" ASC LIMIT 500`)
    .map((d) => ({ ...d, updatedAt: d.updatedAt.toISOString(), suggested: d.updatedAt.getTime() < cutoff }));
  const uploads: { name: string; bytes: number }[] = [];
  try { for (const n of (await readdir(uploadsDir(userId))).slice(0, 500)) { const s = await stat(path.join(uploadsDir(userId), n)).catch(() => null); if (s?.isFile()) uploads.push({ name: n, bytes: s.size }); } } catch { /* none */ }
  return { builds, drafts, uploads, retentionDays: cfg.retentionDays };
}

export type CleanupResult = { ok: true; removedBytes: number; builds: number; drafts: number; uploads: number } | { ok: false; error: string };

/** Delete what the customer ticked, re-checking every rule here (never trusts the list it was shown). */
export async function runCleanup(userId: string, a: { buildIds?: string[]; draftIds?: string[]; uploads?: boolean; confirm: string }): Promise<CleanupResult> {
  if (a.confirm !== CLEANUP_CONFIRM) return { ok: false, error: `Type ${CLEANUP_CONFIRM} to confirm.` };
  const root = path.resolve(cyrusConfig().modbuildDir);
  let removed = 0, nb = 0, nd = 0, nu = 0;
  const want = new Set((a.buildIds ?? []).slice(0, 500));
  if (want.size) {
    const rows = await db.modBuild.findMany({ where: { userId, status: "succeeded", jarPath: { not: null } }, select: { id: true, rootBuildId: true, status: true, jarPath: true, jarSize: true, createdAt: true, lastInstall: true }, take: 5000 });
    for (const r of removableBuilds(rows, await protectedBuildIds(userId))) {
      if (!want.has(r.id) || !r.jarPath) continue;
      const p = path.resolve(r.jarPath);
      if (!p.startsWith(root + path.sep)) continue; // only Cyrus' own jar store
      await unlink(p).catch((e: NodeJS.ErrnoException) => { if (e.code !== "ENOENT") throw e; });
      await db.modBuild.update({ where: { id: r.id }, data: { jarPath: null } });
      removed += r.jarSize ?? 0; nb++;
    }
  }
  const drafts = (a.draftIds ?? []).slice(0, 500);
  if (drafts.length) {
    const del = await db.cyrusModelDraft.deleteMany({ where: { id: { in: drafts }, ownerRef: userId } });
    nd = del.count;
  }
  if (a.uploads) {
    try {
      for (const n of await readdir(uploadsDir(userId))) {
        if (!/^up[0-9a-f]{20}(\.[a-z]{3,4})?(\.json)?$/.test(n)) continue;
        const s = await stat(path.join(uploadsDir(userId), n)).catch(() => null);
        if (!s?.isFile()) continue;
        await unlink(path.join(uploadsDir(userId), n)).catch(() => undefined);
        removed += s.size; nu++;
      }
    } catch { /* none */ }
  }
  await getHost().audit.record(userId, "cyrus.storage.cleanup", JSON.stringify({ builds: nb, drafts: nd, uploads: nu, bytes: removed })).catch(() => undefined);
  await markStorageDirty(userId);
  return { ok: true, removedBytes: removed, builds: nb, drafts: nd, uploads: nu };
}

