// r51 storage accounting: what counts, dedupe, per-mod / per-game rollups, over-quota grace, the write gate rule,
// cleanup eligibility, and that every write path is wired to the server-side gate (and installs/exports are not).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { nextOverState, rollup, storageWriteDecision, type StorageItem } from "../lib/cyrus/storage/accounting";
import { collectItems, type StorageSources } from "../lib/cyrus/storage/collect";
import { removableBuilds } from "../lib/cyrus/storage/cleanup";

const SHA = (c: string) => c.repeat(64).slice(0, 64);
const now = new Date("2026-10-11T12:00:00Z");

describe("rollup: dedupe + rollups", () => {
  const items: StorageItem[] = [
    { key: `sha256:${SHA("a")}`, bytes: 1000, category: "assets", modId: "m1", game: "minecraft" },
    { key: `sha256:${SHA("a")}`, bytes: 1000, category: "assets", modId: "m2", game: "minecraft" }, // same texture in two mods
    { key: `sha256:${SHA("a")}`, bytes: 1000, category: "library", modId: null, game: null }, // and contributed
    { key: `sha256:${SHA("b")}`, bytes: 5000, category: "builds", modId: "m1", game: "minecraft" },
    { key: "row:rev:r1", bytes: 300, category: "revisions", modId: "m1", game: "minecraft" },
    { key: "row:upload:x", bytes: 50, category: "uploads", modId: null, game: null },
  ];
  const r = rollup(items);
  it("content-addressed bytes count once per account", () => {
    assert.equal(r.totalBytes, 1000 + 5000 + 300 + 50);
    assert.equal(r.rawBytes, 8350);
    assert.equal(r.dedupedBytes, 2000);
  });
  it("a shared blob is attributed to the first category in order (assets before library)", () => {
    assert.equal(r.byCategory.assets, 1000);
    assert.equal(r.byCategory.library, 0);
    assert.equal(Object.values(r.byCategory).reduce((a, b) => a + b, 0), r.totalBytes);
  });
  it("per mod: a shared file shows in both mods; sorted by size", () => {
    assert.deepEqual(r.byMod.map((m) => [m.modId, m.bytes]), [["m1", 6300], ["m2", 1000]]);
    assert.equal(r.byMod[0].byCategory.builds, 5000);
  });
  it("per game, once inside the game", () => assert.deepEqual(r.byGame, { minecraft: 6300, unassigned: 1050 }));
  it("bad sizes count as 0", () => assert.equal(rollup([{ key: "row:x", bytes: -5, category: "drafts", modId: null, game: null }, { key: "row:y", bytes: NaN, category: "drafts", modId: null, game: null }]).totalBytes, 0));
});

describe("collectItems: where the bytes live", () => {
  const src: StorageSources = {
    builds: async () => [
      { id: "b1", rootBuildId: null, pluginName: "Lanterns", jarSha256: SHA("c"), jarSize: 4000, jarPath: "/x/b1.jar", createdAt: now, cyrus: { attachments: [{ n: 1, size: 70 }] } },
      { id: "b2", rootBuildId: "b1", pluginName: "Lanterns", jarSha256: SHA("c"), jarSize: 4000, jarPath: "/x/b2.jar", createdAt: now, cyrus: null }, // identical jar
      { id: "b3", rootBuildId: "b1", pluginName: "Lanterns", jarSha256: SHA("d"), jarSize: 4100, jarPath: null, createdAt: now, cyrus: null }, // jar removed
    ],
    projects: async () => [{ id: "p1", game: "minecraft", rootBuildId: "b1", title: null }, { id: "p2", game: "hytale", rootBuildId: null, title: "Orbs" }],
    assets: async () => [{ id: "a1", projectId: "p1", sha256: SHA("e"), size: 900, createdAt: now }, { id: "a2", projectId: "p2", sha256: SHA("e"), size: 900, createdAt: now }],
    revisions: async () => [{ id: "r1", projectId: "p1", bytes: 120, createdAt: now }],
    drafts: async () => [{ id: "d1", projectId: "p2", bytes: 40, updatedAt: now }],
    packs: async () => [{ packId: "mp_x", name: "Pack", versions: [{ versionId: "1.0.0", sha256: SHA("f"), bytes: 6000, createdAt: now.toISOString() }] }],
    uploads: async () => [{ name: "up1.bin", bytes: 30 }],
    library: async () => [{ id: SHA("e"), bytes: 900 }],
  };
  it("every source, deduped, per mod and per game", async () => {
    const r = rollup(await collectItems("u1", src));
    assert.equal(r.byCategory.builds, 4000); // b1 + b2 same sha, b3 has no stored jar
    assert.equal(r.byCategory.assets, 900); // same texture in two projects + the library: once
    assert.equal(r.byCategory.library, 0);
    assert.equal(r.byCategory.packs, 6000);
    assert.equal(r.byCategory.uploads, 70 + 30);
    assert.equal(r.byCategory.revisions, 120);
    assert.equal(r.byCategory.drafts, 40);
    assert.equal(r.totalBytes, 4000 + 900 + 6000 + 100 + 120 + 40);
    const m = Object.fromEntries(r.byMod.map((x) => [x.modId, x]));
    assert.equal(m.b1.label, "Lanterns");
    assert.equal(m.b1.bytes, 4000 + 70 + 900 + 120);
    assert.equal(m["p:p2"].label, "Orbs");
    assert.equal(r.byGame.hytale, 940);
  });
});

describe("over quota: grace after a drop, never deletion", () => {
  const G = 30, MB = 1e6;
  it("under quota = clear", () => assert.deepEqual(nextOverState({ usedBytes: 5, quotaBytes: 10, prevQuotaBytes: 20, prev: { overSince: now, graceUntil: now }, graceDays: G, now }), { overSince: null, graceUntil: null }));
  it("a quota drop below usage starts a 30-day grace", () => {
    const s = nextOverState({ usedBytes: 30 * MB, quotaBytes: 25 * MB, prevQuotaBytes: 50 * MB, prev: { overSince: null, graceUntil: null }, graceDays: G, now });
    assert.equal(s.graceUntil?.toISOString(), "2026-11-10T12:00:00.000Z");
  });
  it("first measurement over quota (launch day) gets the grace too", () => assert.ok(nextOverState({ usedBytes: 2, quotaBytes: 1, prevQuotaBytes: null, prev: null, graceDays: G, now }).graceUntil));
  it("going over by your own writes gets no grace", () => assert.equal(nextOverState({ usedBytes: 26, quotaBytes: 25, prevQuotaBytes: 25, prev: { overSince: null, graceUntil: null }, graceDays: G, now }).graceUntil, null));
  it("an existing grace is kept, never extended", () => {
    const g = new Date("2026-10-20T00:00:00Z");
    assert.equal(nextOverState({ usedBytes: 30, quotaBytes: 5, prevQuotaBytes: 10, prev: { overSince: now, graceUntil: g }, graceDays: G, now }).graceUntil, g);
  });
});

describe("the write rule", () => {
  const base = { usedBytes: 90, pendingBytes: 5, quotaBytes: 100, graceUntil: null, now };
  it("fits", () => assert.deepEqual(storageWriteDecision({ ...base, addBytes: 5 }), { ok: true, grace: false }));
  it("does not fit", () => assert.equal(storageWriteDecision({ ...base, addBytes: 6 }).ok, false));
  it("a build (size unknown) needs room left", () => {
    assert.equal(storageWriteDecision({ ...base, addBytes: 0 }).ok, true);
    assert.equal(storageWriteDecision({ ...base, usedBytes: 95, addBytes: 0 }).ok, false);
  });
  it("grace allows, expired grace refuses", () => {
    assert.deepEqual(storageWriteDecision({ ...base, usedBytes: 200, addBytes: 1, graceUntil: new Date(now.getTime() + 1) }), { ok: true, grace: true });
    assert.equal(storageWriteDecision({ ...base, usedBytes: 200, addBytes: 1, graceUntil: now }).ok, false);
  });
});

describe("cleanup eligibility", () => {
  const d = (s: string) => new Date(s);
  const rows = [
    { id: "v1", rootBuildId: "v1", status: "succeeded", jarPath: "/j/v1", createdAt: d("2026-01-01"), lastInstall: null },
    { id: "v2", rootBuildId: "v1", status: "succeeded", jarPath: "/j/v2", createdAt: d("2026-02-01"), lastInstall: { serverId: "s" } }, // installed
    { id: "v3", rootBuildId: "v1", status: "succeeded", jarPath: "/j/v3", createdAt: d("2026-03-01"), lastInstall: null }, // in a pack
    { id: "v4", rootBuildId: "v1", status: "succeeded", jarPath: "/j/v4", createdAt: d("2026-04-01"), lastInstall: null }, // newest
    { id: "v5", rootBuildId: "v1", status: "failed", jarPath: null, createdAt: d("2026-05-01"), lastInstall: null },
  ];
  it("never the newest, an installed one, a pack member or a project head", () => assert.deepEqual(removableBuilds(rows, new Set(["v3"])).map((r) => r.id), ["v1"]));
});

describe("enforcement is wired server-side (and only on writes)", () => {
  const rd = (p: string) => readFileSync(path.join(__dirname, "..", p), "utf8");
  it("builds (both create paths), uploads, asset saves, library contributions, pack versions, imports", () => {
    assert.equal((rd("lib/modbuilder/create.ts").match(/checkStorageWrite\(user\.id, 0, "build"\)/g) ?? []).length, 2);
    assert.match(rd("app/api/mod-builder/uploads/route.ts"), /checkStorageWrite\(user\.id, bytes\.length, "upload"\)/);
    assert.match(rd("lib/cyrus/engine-core/store.ts"), /assetWriteGate\(projectId, a\.sha256, a\.size, a\.origin\)/);
    assert.match(rd("lib/cyrus/library/backend/studio-hook.ts"), /checkStorageWrite\(userId, rest\.bytes\.length, "library"\)/);
    assert.match(rd("lib/cyrus/api/v1/deps-writes.ts"), /checkStorageWrite\(subject, bytes\.length, "library"\)/);
    assert.match(rd("lib/modbuilder/modpack.ts"), /checkStorageWrite\(userId, bytes, "pack"\)/);
    assert.match(rd("lib/cyrus/import/deps-real.ts"), /checkStorageWrite\(userId, bytes, "import"\)/);
  });
  it("install, download and export paths never call the gate", () => {
    for (const f of ["lib/modbuilder/install.ts", "lib/cyrus/delivery/job.ts", "lib/cyrus/app/data-jobs.ts"]) {
      let t = ""; try { t = rd(f); } catch { continue; }
      assert.doesNotMatch(t, /checkStorageWrite/, f);
    }
  });
  it("the gate fails closed", () => assert.match(rd("lib/cyrus/storage/service.ts"), /gate failed closed[\s\S]{0,200}storage_unknown/));
});

