export type CheckoutOpen = { ok: true; clientSecret: string; publishableKey: string } | { ok: false; error: string };

const ACTIVE = ["active", "trialing", "past_due", "incomplete"];

async function customerFor(user: User): Promise<string> {
  if (override) {
    if (user.stripeCustomerId) return user.stripeCustomerId;
    const c = await sc().customers.create({ email: user.email, metadata: { nxeonUserId: user.id } });
    await getHost().users.setBillingCustomerId(user.id, c.id);
    return c.id;
  }
  const h = hostStripe();
  if (!h) throw new Error("Stripe is not configured");
  return h.ensureCustomer(user);
}

export async function openPlanCheckout(user: User, tier: PlanTier, opts: { returnBase?: string } = {}): Promise<CheckoutOpen> {
  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
  const cfg = await loadTokenConfig();
  const price = (await planPrices(cfg))[tier];
  if (!price) return { ok: false, error: "Plans aren't set up yet. Please try again later." };
  const cur = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
  if (cur && ACTIVE.includes(cur.status) && !cur.endedAt) return { ok: false, error: "You already have a plan. Change it from your plan instead." };
  const customer = await customerFor(user);
  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
    mode: "subscription",
    customer,
    ui_mode: uiMode(),
    payment_method_types: ["card"],
    line_items: [{ price: price.id, quantity: 1 }],
    return_url: `${opts.returnBase ?? appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: { cyrusUserId: user.id, cyrusKind: "plan", cyrusTier: tier },
    subscription_data: { metadata: { cyrusUserId: user.id, cyrusTier: tier }, description: `Cyrus ${tier === "all" ? "All models" : tier[0].toUpperCase() + tier.slice(1)} plan` },
  }, requestOpts());
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

export async function openTopupCheckout(user: User, cents: number, opts: { returnBase?: string } = {}): Promise<CheckoutOpen> {
  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
  const cfg = await loadTokenConfig();
  if (!cfg.topup.enabled) return { ok: false, error: "Top-ups aren't available right now." };
  if (!validTopupCents(cents, cfg)) return { ok: false, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
  if (cfg.topup.requiresPaid) {
    const paid = await getHost().servers.paidCount(user.id) + await db.cyrusPlan.count({ where: { userId: user.id } });
    if (!paid) return { ok: false, error: "Top-ups are for customers with a game server or a Cyrus plan." };
  }
  const tokens = topupTokens(cents, cfg);
  const customer = await customerFor(user);
  const md = { cyrusUserId: user.id, cyrusKind: "topup", cyrusTokens: String(tokens), cyrusCents: String(cents) };
  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
    mode: "payment",
    customer,
    ui_mode: uiMode(),
    payment_method_types: ["card"],
    line_items: [{ price_data: { currency: "usd", unit_amount: cents, product_data: { name: `${fmt(tokens)} Cyrus tokens` } }, quantity: 1 }],
    return_url: `${opts.returnBase ?? appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: md,
    payment_intent_data: { metadata: md, description: `${fmt(tokens)} Cyrus tokens` },
  }, requestOpts());
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

/** A paid top-up session -> tokens (idempotent per session). Returns tokens granted (0 if replay/unpaid). */
export async function fulfilTopup(session: Stripe.Checkout.Session): Promise<number> {
  const md = session.metadata ?? {};
  if (md.cyrusKind !== "topup" || !md.cyrusUserId || session.payment_status !== "paid" || session.mode !== "payment") return 0;
  const cfg = await loadTokenConfig();
  const paidCents = session.amount_total ?? 0;
}

/** The Checkout return leg (and the webhook's checkout events). */
export async function fulfilCyrusSession(sessionOrId: string | Stripe.Checkout.Session): Promise<{ kind: "plan" | "topup" | "none"; userId: string | null; tokens: number }> {
  const session = typeof sessionOrId === "string" ? await sc().checkout.sessions.retrieve(sessionOrId) : sessionOrId;
  const md = session.metadata ?? {};
  if (!md.cyrusUserId) return { kind: "none", userId: null, tokens: 0 };
  if (md.cyrusKind === "topup") return { kind: "topup", userId: md.cyrusUserId, tokens: await fulfilTopup(session) };
  if (md.cyrusKind === "plan" && session.subscription) {
    const before = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
    await reconcileSubscription(idOf(session.subscription as string | { id: string })!);
    const after = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
    return { kind: "plan", userId: md.cyrusUserId, tokens: (after._sum.delta ?? 0) - (before._sum.delta ?? 0) };
  }
  return { kind: "none", userId: md.cyrusUserId, tokens: 0 };
}

// ---------------------------------------------------------------------------
// Subscriptions + invoices
// ---------------------------------------------------------------------------

function subUserId(sub: Stripe.Subscription): string | null {
  return sub.metadata?.cyrusUserId || null;
}

function subPeriod(sub: Stripe.Subscription): { start: Date | null; end: Date | null } {
  const it = sub.items?.data?.[0] as (Stripe.SubscriptionItem & { current_period_start?: number; current_period_end?: number }) | undefined;
  const legacy = sub as unknown as { current_period_start?: number; current_period_end?: number };
  return { start: ts(it?.current_period_start ?? legacy.current_period_start), end: ts(it?.current_period_end ?? legacy.current_period_end) };
}

/** Mirror a Cyrus subscription into CyrusPlan. Returns the row (null if not ours). */
export async function syncSubscription(sub: Stripe.Subscription): Promise<{ userId: string } | null> {
  const userId = subUserId(sub);
  if (!userId) return null;

/**
 * Called by app/api/stripe/webhook for EVERY verified event. Returns true when the event
 * was a Cyrus one. Re-fetches the object from Stripe before acting (the event body is a
 * hint, not the truth), so a replayed or out-of-order event applies the current state.
 */
export async function handleCyrusStripeEvent(event: Stripe.Event): Promise<boolean> {
  const obj = event.data.object as unknown as Record<string, unknown> & { id: string; metadata?: Record<string, string> };
  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded": {
      if (!obj.metadata?.cyrusUserId) return false;
      await fulfilCyrusSession(obj.id);
      return true;
    }
    case "invoice.paid":
    case "invoice.payment_succeeded": {
      const inv = obj as unknown as Stripe.Invoice;
      const subId = invoiceSubscriptionId(inv);
      const ours = !!invoiceMetaUser(inv) || (subId ? !!(await db.cyrusPlan.findUnique({ where: { stripeSubscriptionId: subId }, select: { userId: true } })) : false);
      if (!ours || !subId) return false;
      await reconcileSubscription(subId);
      return true;
    }
    case "customer.subscription.created":
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      if (!obj.metadata?.cyrusUserId) return false;
      await reconcileSubscription(obj.id);
      return true;
    }
    case "charge.refunded": {
      const n = await handleRefundedCharge(obj as unknown as Stripe.Charge);
      return n > 0;
    }
    // r38 (CYRUS_CHARGEBACK_REVERSAL=1, default off): a chargeback takes back the disputed share of that purchase's unspent tokens, like a refund (re-fetched
    // charge; its own idemKey per dispute; the "already revoked" sum keeps a later refund from taking twice)
    case "charge.dispute.created":
    case "charge.dispute.funds_withdrawn": {
      const d = obj as unknown as Stripe.Dispute;
      const chId = idOf(d.charge as string | { id: string } | null);
      if (process.env.CYRUS_CHARGEBACK_REVERSAL !== "1" || !chId || !configured()) return false;
      const ch = await sc().charges.retrieve(chId);
      const n = await handleRefundedCharge({ ...ch, id: `${ch.id}:dispute:${d.id}`, amount_refunded: Math.min(ch.amount, Math.max(ch.amount_refunded ?? 0, d.amount ?? 0)) } as Stripe.Charge);
      return n > 0;
    }
    default:
      return false;
  }
}

