// Cyrus storage add-on (r51): extra GB, monthly, paid through Nxeon (the payment provider): the Nxeon WALLET (default,
// renewed by the storage sweep) or a CARD subscription on Nxeon's Stripe. SERVER ONLY. Switch CYRUS_STORAGE_ADDONS=1
// (and CYRUS_STORAGE=1); off = every call answers "unavailable", nothing is charged.
//
// Same pattern as token top-ups (lib/cyrus/tokens/purchase.ts):
//   reference   cst:<user>:g<gb>:<key>   the wallet reference AND the idemKey (the GB are in it, so a reconcile or the
//                                         entitlement mirror can apply a lost charge without guessing GB from cents)
//   apply       applyStorageEvent: THE step, idempotent by idemKey (CyrusStorageCharge.idemKey UNIQUE): direct (one app),
//               the signed purchase webhook (CYRUS_PURCHASE_EVENTS, Cyrus apart), a redelivery, the reconcile and the
//               entitlement mirror can all run it; it lands once.
//   change      increase = prorated difference now; decrease / cancel = at the period end (never a mid-period refund).
//   refund      a full refund of the charge in force takes the add-on back (quota drops -> 30-day grace); data is never
//               deleted automatically.
import type Stripe from "stripe";
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import type { PurchaseEnvelope } from "../host/types";
import { purchaseEventsEnabled } from "../tokens/purchase";
import { loadStorageConfig, storageAddonsEnabled } from "./config";
import { addMonth, planChange, storagePriceCents } from "./pricing";
import { effectiveAddonGb, markStorageDirty, recomputeStorage } from "./service";

const DAY = 86_400_000;
const locks = new Set<string>();
const KEY_RE = /^[A-Za-z0-9_-]{16,64}$/;
const REF_RE = /^cst:([A-Za-z0-9_-]{1,64}):g(\d{1,6}):([A-Za-z0-9_-]{16,64})$/;
export const storageRef = (userId: string, gb: number, key: string) => `cst:${userId}:g${gb}:${key}`;
export function parseStorageRef(ref: string): { userId: string; gb: number; key: string } | null {
  const m = REF_RE.exec(ref);
  return m ? { userId: m[1], gb: Number(m[2]), key: m[3] } : null;
}

export type StorageChange = "purchase" | "increase" | "renewal";
export type StorageEnvelope = Omit<PurchaseEnvelope, "data"> & { data: PurchaseEnvelope["data"] & { kind: "storage"; gb: number; gbFrom: number; change: StorageChange; periodEnd: string | null } };

export function storageEnvelope(type: PurchaseEnvelope["type"], subject: string, d: { idemKey: string; method: "wallet" | "card"; gb: number; gbFrom: number; change: StorageChange; cents: number; periodEnd: Date | null; refundedCents?: number; sourceRef?: string }, now = new Date()): StorageEnvelope {
  return {
    id: `pe_${d.idemKey}${type === "purchase.refunded" ? `:r${d.refundedCents ?? 0}` : ""}`.slice(0, 160), type, createdAt: now.toISOString(), subject,
    data: { idemKey: d.idemKey, kind: "storage", method: d.method, tokens: 0, cents: d.cents, expiresAt: null, note: `Cyrus storage +${d.gb} GB (${d.change})`, gb: d.gb, gbFrom: d.gbFrom, change: d.change, periodEnd: d.periodEnd ? d.periodEnd.toISOString() : null, ...(d.refundedCents !== undefined ? { refundedCents: d.refundedCents } : {}), ...(d.sourceRef ? { sourceRef: d.sourceRef } : {}) },
  };
}
export const isStorageEnvelope = (e: { data?: { kind?: string } }): e is StorageEnvelope => e?.data?.kind === "storage";

const isUnique = (e: unknown) => (e as { code?: string })?.code === "P2002";

/** Idempotent. completed -> the add-on in force (new period, increase in the period, or renewal); refunded -> money back
 *  recorded once (cumulative refundedCents), and a FULL refund of the charge in force takes its GB back. */
export async function applyStorageEvent(e: StorageEnvelope): Promise<{ applied: boolean }> {
  const d = e.data;
  if (!/^[A-Za-z0-9:_-]{6,160}$/.test(d.idemKey) || !e.subject || !Number.isInteger(d.gb) || d.gb < 0 || d.gb > 1_000_000 || !Number.isInteger(d.cents) || d.cents < 0) throw new Error("invalid storage event");
  const at = new Date(e.createdAt);
  if (e.type === "purchase.completed") {
    const periodEnd = d.periodEnd ? new Date(d.periodEnd) : null;
    try {
      await db.cyrusStorageCharge.create({ data: { idemKey: d.idemKey, userId: e.subject, kind: d.change, gbFrom: d.gbFrom, gbTo: d.gb, cents: d.cents, method: d.method, periodEnd, meta: { event: e.id, ...(d.sourceRef ? { sourceRef: d.sourceRef } : {}) } } });
    } catch (err) {
      if (isUnique(err)) return { applied: false };
      throw err;
    }
    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: e.subject } });
    const end = periodEnd ?? (d.change === "increase" && cur?.addonPeriodEnd ? cur.addonPeriodEnd : addMonth(at));
    const data = d.change === "increase" && cur?.addonPeriodEnd
      ? { addonGb: d.gb, addonNextGb: null, addonStatus: "active", addonMethod: d.method }
      : { addonGb: d.gb, addonNextGb: null, addonStatus: "active", addonMethod: d.method, addonPeriodStart: d.change === "renewal" && cur?.addonPeriodEnd ? cur.addonPeriodEnd : at, addonPeriodEnd: end };
    await db.cyrusStorageAccount.upsert({ where: { userId: e.subject }, create: { userId: e.subject, ...data, dirtyAt: new Date() }, update: { ...data, dirtyAt: new Date() } });
    await recomputeStorage(e.subject).catch(() => markStorageDirty(e.subject));
    return { applied: true };
  }
  const row = await db.cyrusStorageCharge.findUnique({ where: { idemKey: d.idemKey } });
  const refunded = Math.min(row?.cents ?? 0, Math.max(0, d.refundedCents ?? 0));
  if (!row || row.userId !== e.subject || refunded <= row.refundedCents) return { applied: false };
  await db.cyrusStorageCharge.update({ where: { id: row.id }, data: { refundedCents: refunded } });
  if (refunded >= row.cents) {
    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: e.subject } });
    // the charge in force: same GB, and (for a period charge) the same period end
    const inForce = cur && cur.addonGb === row.gbTo && (row.kind === "increase" || !row.periodEnd || cur.addonPeriodEnd?.getTime() === row.periodEnd.getTime());
    if (inForce) {
      const back = row.kind === "increase" ? { addonGb: row.gbFrom } : { addonGb: 0, addonStatus: "canceled", addonNextGb: null };
      await db.cyrusStorageAccount.update({ where: { userId: e.subject }, data: { ...back, dirtyAt: new Date() } });
      await recomputeStorage(e.subject).catch(() => markStorageDirty(e.subject));
    }
  }
  return { applied: true };
}

/** Direct (one app) or the signed webhook/outbox path (Cyrus apart): the same envelope type the token path uses. */
export async function deliverStorage(e: StorageEnvelope): Promise<"applied" | "pending"> {
  const emit = getHost().billing.emitPurchase;
  if (purchaseEventsEnabled() && emit) { await emit(e as unknown as PurchaseEnvelope); return "pending"; }
  await applyStorageEvent(e);
  return "applied";
}

export type BuyState = "active" | "pending" | "scheduled" | "unchanged" | "insufficient_funds" | "failed" | "unavailable" | "in_progress" | "invalid";
export type BuyResult = { state: BuyState; chargedCents: number; error?: string; effective?: "now" | "period_end" };

/** Buy, increase or decrease the add-on, paying from the Nxeon wallet. Idempotent per `key` (one click = one key). */
export async function setStorageAddonWallet(user: { id: string }, gb: number, key: string, now = new Date()): Promise<BuyResult> {
  const wallet = getHost().billing.wallet;
  if (!storageAddonsEnabled() || !wallet) return { state: "unavailable", chargedCents: 0, error: "Buying storage isn't available right now." };
  if (!KEY_RE.test(key)) return { state: "invalid", chargedCents: 0, error: "Missing purchase key." };
  const cfg = await loadStorageConfig();
  if (!Number.isInteger(gb) || gb < 0 || gb > cfg.addonMaxGb) return { state: "invalid", chargedCents: 0, error: `Pick 1 to ${cfg.addonMaxGb} GB.` };
  const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: user.id } });
  if (cur?.addonMethod === "card" && cur.addonStatus === "active") return { state: "invalid", chargedCents: 0, error: "Your storage is paid by card: change it from the card subscription (cancel, then buy the new amount)." };
  const from = effectiveAddonGb(cur, now);
  const plan = planChange({ fromGb: from, toGb: gb, periodStart: cur?.addonPeriodStart ?? null, periodEnd: cur?.addonPeriodEnd ?? null, now, rule: cfg.rule, table: cfg.table });
  if (plan.kind === "same") {
    if (cur?.addonNextGb !== null && cur?.addonNextGb !== undefined) { await db.cyrusStorageAccount.update({ where: { userId: user.id }, data: { addonNextGb: null } }); return { state: "scheduled", chargedCents: 0, effective: "now" }; }
    return { state: "unchanged", chargedCents: 0 };
  }
  if (plan.kind === "decrease") {
    await db.cyrusStorageAccount.update({ where: { userId: user.id }, data: { addonNextGb: gb } });
    await getHost().audit.record(user.id, "cyrus.storage.addon.decrease", `${from} -> ${gb} GB at period end`).catch(() => undefined);
    return { state: "scheduled", chargedCents: 0, effective: "period_end" };
  }
  const change: StorageChange = plan.kind === "new" ? "purchase" : "increase";
  const ref = storageRef(user.id, gb, key);
  if (locks.has(ref)) return { state: "in_progress", chargedCents: 0 };
  locks.add(ref);
  try {
    if (await db.cyrusStorageCharge.findUnique({ where: { idemKey: ref }, select: { id: true } })) return { state: "active", chargedCents: 0 };
    const periodEnd = change === "purchase" ? addMonth(now) : cur?.addonPeriodEnd ?? addMonth(now);
    const env = storageEnvelope("purchase.completed", user.id, { idemKey: ref, method: "wallet", gb, gbFrom: from, change, cents: plan.chargeCents, periodEnd }, now);
    if (plan.chargeCents > 0) {
      const c = await wallet.charge({ userId: user.id, cents: plan.chargeCents, description: `Cyrus storage +${gb} GB monthly${change === "increase" ? " (upgrade, prorated)" : ""}`, reference: ref });
      if (!c.ok) return { state: c.error === "insufficient_funds" ? "insufficient_funds" : "invalid", chargedCents: 0, error: c.error === "insufficient_funds" ? "Not enough in your wallet. Add funds at Nxeon or pay by card." : "Couldn't charge your wallet." };
    }
    try {
      const s = await deliverStorage(env);
      return { state: s === "applied" ? "active" : "pending", chargedCents: plan.chargeCents, effective: "now" };
    } catch (err) {
      console.error("[cyrus-storage] apply failed after wallet charge", ref, (err as Error).message);
      if (plan.chargeCents <= 0) return { state: "failed", chargedCents: 0, error: "We couldn't change your storage. Nothing was charged." };
      try {
        await wallet.refund({ userId: user.id, cents: plan.chargeCents, description: "Refund: Cyrus storage not added", reference: `${ref}:refund` });
        return { state: "failed", chargedCents: 0, error: "We couldn't add your storage, so your wallet was refunded." };
      } catch {
        return { state: "pending", chargedCents: plan.chargeCents, error: "Your storage is on the way. If it doesn't appear in a few minutes, contact support." };
      }
    }
  } finally {
    locks.delete(ref);
  }
}

/** Cancel (at the period end) or undo a pending cancel. */
export async function cancelStorageAddon(user: { id: string }, cancel: boolean): Promise<{ ok: boolean; error?: string }> {
  if (!storageAddonsEnabled()) return { ok: false, error: "Not available right now." };
  const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: user.id } });
  if (!cur || cur.addonStatus !== "active") return { ok: false, error: "You have no storage add-on." };
  if (cur.addonMethod === "card" && cur.addonSubRef) {
    const s = getHost().billing.stripe;
    if (!s?.configured()) return { ok: false, error: "Payments aren't available right now." };
    await s.client().subscriptions.update(cur.addonSubRef, { cancel_at_period_end: cancel }, s.requestOptions);
  }
  await db.cyrusStorageAccount.update({ where: { userId: user.id }, data: { addonNextGb: cancel ? 0 : null } });
  await getHost().audit.record(user.id, cancel ? "cyrus.storage.addon.cancel" : "cyrus.storage.addon.resume", `${cur.addonGb} GB`).catch(() => undefined);
  return { ok: true };
}

/** Refund the wallet charge of the current period (staff or the customer's refund window): money back, GB back. */
export async function refundStorageCharge(userId: string, idemKey: string, cents?: number): Promise<{ ok: boolean; cents: number }> {
  const row = await db.cyrusStorageCharge.findUnique({ where: { idemKey } });
  const w = getHost().billing.wallet;
  if (!row || row.userId !== userId || row.method !== "wallet" || !w) return { ok: false, cents: 0 };
  const amount = Math.min(row.cents - row.refundedCents, cents ?? row.cents - row.refundedCents);
  if (amount <= 0) return { ok: false, cents: 0 };
  const r = await applyStorageEvent(storageEnvelope("purchase.refunded", userId, { idemKey, method: "wallet", gb: row.gbTo, gbFrom: row.gbFrom, change: row.kind as StorageChange, cents: row.cents, periodEnd: row.periodEnd, refundedCents: row.refundedCents + amount }));
  if (!r.applied) return { ok: false, cents: 0 };
  await w.refund({ userId, cents: amount, description: "Refund: Cyrus storage", reference: `${idemKey}:refund:${row.refundedCents + amount}` });
  return { ok: true, cents: amount };
}

/** Sweep: renew wallet add-ons whose period ended (once per period, idempotent key), apply scheduled decreases and
 *  cancels, retry a failed renewal once a day for 7 days, then cancel. Card add-ons renew on Stripe's side. */
export async function storageRenewalSweep(now = new Date(), batch = 50): Promise<{ renewed: number; lapsed: number; failed: number }> {
  if (!storageAddonsEnabled()) return { renewed: 0, lapsed: 0, failed: 0 };
  const wallet = getHost().billing.wallet;
  const cfg = await loadStorageConfig();
  const due = await db.cyrusStorageAccount.findMany({ where: { addonMethod: "wallet", addonStatus: { in: ["active", "past_due"] }, addonPeriodEnd: { lte: now } }, take: batch });
  let renewed = 0, lapsed = 0, failed = 0;
  for (const r of due) {
    const end = r.addonPeriodEnd!;
    const next = r.addonNextGb ?? r.addonGb;
    const lapse = async (status: string) => { await db.cyrusStorageAccount.update({ where: { userId: r.userId }, data: { addonStatus: status, addonGb: status === "canceled" ? 0 : r.addonGb, addonNextGb: null, dirtyAt: now } }); await recomputeStorage(r.userId).catch(() => undefined); lapsed++; };
    if (next <= 0) { await lapse("canceled"); continue; }
    if (r.addonStatus === "past_due" && (now.getTime() - end.getTime() > 7 * DAY)) { await lapse("canceled"); continue; }
    if (r.addonStatus === "past_due" && now.getTime() - r.updatedAt.getTime() < DAY) continue;
    if (!wallet) continue;
    const ref = storageRef(r.userId, next, `renew_${end.getTime()}`);
    const cents = storagePriceCents(next, cfg.rule, cfg.table);
    let newEnd = addMonth(end); if (newEnd.getTime() <= now.getTime()) newEnd = addMonth(now);
    const c = await wallet.charge({ userId: r.userId, cents, description: `Cyrus storage +${next} GB monthly (renewal)`, reference: ref });
    if (!c.ok) { await db.cyrusStorageAccount.update({ where: { userId: r.userId }, data: { addonStatus: "past_due", dirtyAt: now } }); await recomputeStorage(r.userId).catch(() => undefined); failed++; continue; }
    await deliverStorage(storageEnvelope("purchase.completed", r.userId, { idemKey: ref, method: "wallet", gb: next, gbFrom: r.addonGb, change: "renewal", cents, periodEnd: newEnd }, now));
    renewed++;
  }
  return { renewed, lapsed, failed };
}

/** Reconcile: a referenced wallet charge without a charge row (lost apply, dead webhook) is applied once, from its reference. */
export async function reconcileStorageCharges(o: { userId?: string; sinceMs?: number } = {}, now = new Date()): Promise<{ checked: number; applied: number }> {
  const w = getHost().billing.wallet;
  if (!storageAddonsEnabled() || !w?.findByReference) return { checked: 0, applied: 0 };
  const moves = await w.findByReference({ userId: o.userId, prefix: "cst:", sinceMs: o.sinceMs ?? now.getTime() - 7 * DAY });
  const refunded = new Set(moves.filter((m) => m.cents > 0 && m.reference.includes(":refund")).map((m) => m.reference.split(":refund")[0]));
  let checked = 0, applied = 0;
  for (const m of moves) {
    const p = parseStorageRef(m.reference);
    if (m.cents >= 0 || !p || refunded.has(m.reference) || locks.has(m.reference) || now.getTime() - m.at.getTime() < 10 * 60_000) continue;
    checked++;
    if (await db.cyrusStorageCharge.findUnique({ where: { idemKey: m.reference }, select: { id: true } })) continue;
    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: m.userId } });
    const change: StorageChange = p.key.startsWith("renew_") ? "renewal" : effectiveAddonGb(cur, m.at) > 0 ? "increase" : "purchase";
    if ((await applyStorageEvent(storageEnvelope("purchase.completed", m.userId, { idemKey: m.reference, method: "wallet", gb: p.gb, gbFrom: cur?.addonGb ?? 0, change, cents: -m.cents, periodEnd: change === "increase" ? cur?.addonPeriodEnd ?? null : addMonth(m.at) }, m.at))).applied) applied++;
  }
  return { checked, applied };
}

// ---------------------------------------------------------------------------
// Card: a monthly subscription on Nxeon's Stripe (built; NOT run against Stripe)
// ---------------------------------------------------------------------------

export async function openStorageCheckout(user: { id: string; email: string; name?: string | null; stripeCustomerId: string | null; stripePaymentMethodId: string | null }, gb: number, opts: { returnBase?: string } = {}): Promise<{ ok: true; clientSecret: string; publishableKey: string } | { ok: false; error: string }> {
  const s = getHost().billing.stripe;
  if (!storageAddonsEnabled() || !s?.configured()) return { ok: false, error: "Paying by card isn't available right now." };
  const cfg = await loadStorageConfig();
  if (!Number.isInteger(gb) || gb < 1 || gb > cfg.addonMaxGb) return { ok: false, error: `Pick 1 to ${cfg.addonMaxGb} GB.` };
  const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: user.id } });
  if (cur && effectiveAddonGb(cur, new Date()) > 0) return { ok: false, error: "You already have extra storage. Change it from your storage settings." };
  const customer = await s.ensureCustomer(user);
  const md = { cyrusUserId: user.id, cyrusKind: "storage", cyrusGb: String(gb) };
  const session = await s.createCheckoutSession({
    mode: "subscription", customer, ui_mode: s.uiMode, payment_method_types: ["card"],
    line_items: [{ price_data: { currency: "usd", unit_amount: storagePriceCents(gb, cfg.rule, cfg.table), recurring: { interval: "month" }, product_data: { name: `Cyrus storage +${gb} GB` } }, quantity: 1 }],
    return_url: `${opts.returnBase ?? process.env.APP_URL ?? "http://localhost:3000"}/api/cyrus/storage/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: md, subscription_data: { metadata: md, description: `Cyrus storage +${gb} GB` },
  }, s.requestOptions);
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: s.publishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

const subMeta = (sub: Stripe.Subscription | null | undefined) => (sub?.metadata?.cyrusKind === "storage" && sub.metadata.cyrusUserId ? { userId: sub.metadata.cyrusUserId, gb: Number(sub.metadata.cyrusGb) } : null);

/** Card add-on events (call from the Stripe webhook BEFORE the plan handler). true = it was a storage event.
 *  invoice.paid -> purchase / renewal (idemKey stripe:<invoice>); subscription deleted -> lapse; charge.refunded -> refund. */
export async function handleStorageStripeEvent(event: Stripe.Event): Promise<boolean> {
  const s = getHost().billing.stripe;
  if (!storageAddonsEnabled() || !s?.configured()) return false;
  const obj = event.data.object as unknown as Record<string, unknown> & { id: string };
  const subOf = async (id: string | null) => (id ? s.client().subscriptions.retrieve(id, {}, s.requestOptions).catch(() => null) : null);
  if (event.type === "invoice.paid" || event.type === "invoice.payment_succeeded") {
    const inv = await s.client().invoices.retrieve(obj.id, {}, s.requestOptions);
    const subId = (inv as unknown as { subscription?: string | { id: string } | null; parent?: { subscription_details?: { subscription?: string | { id: string } } } }).subscription ?? (inv as unknown as { parent?: { subscription_details?: { subscription?: string | { id: string } } } }).parent?.subscription_details?.subscription ?? null;
    const sid = typeof subId === "string" ? subId : subId?.id ?? null;
    const sub = await subOf(sid);
    const m = subMeta(sub);
    if (!m || !sid || inv.status !== "paid") return !!m;
    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: m.userId } });
    const line = inv.lines?.data?.[0] as unknown as { period?: { end?: number } } | undefined;
    const periodEnd = line?.period?.end ? new Date(line.period.end * 1000) : null;
    await applyStorageEvent(storageEnvelope("purchase.completed", m.userId, { idemKey: `stripe:${inv.id}`, method: "card", gb: m.gb, gbFrom: cur?.addonGb ?? 0, change: cur?.addonSubRef === sid ? "renewal" : "purchase", cents: inv.amount_paid ?? 0, periodEnd, sourceRef: sid }));
    await db.cyrusStorageAccount.update({ where: { userId: m.userId }, data: { addonSubRef: sid } }).catch(() => undefined);
    return true;
  }
  if (event.type === "customer.subscription.deleted" || event.type === "customer.subscription.updated") {
    const sub = await subOf(obj.id);
    const m = subMeta(sub);
    if (!m) return false;
    if (event.type === "customer.subscription.deleted" || sub?.status === "canceled" || sub?.status === "unpaid") {
      await db.cyrusStorageAccount.updateMany({ where: { userId: m.userId, addonSubRef: obj.id }, data: { addonStatus: "canceled", addonGb: 0, addonNextGb: null, dirtyAt: new Date() } });
      await recomputeStorage(m.userId).catch(() => undefined);
    } else {
      await db.cyrusStorageAccount.updateMany({ where: { userId: m.userId, addonSubRef: obj.id }, data: { addonNextGb: sub?.cancel_at_period_end ? 0 : null } });
    }
    return true;
  }
  if (event.type === "charge.refunded") {
    const ch = await s.client().charges.retrieve(obj.id, { expand: ["invoice"] }, s.requestOptions).catch(() => null);
    const invId = (ch as unknown as { invoice?: string | { id: string } | null } | null)?.invoice;
    const iid = typeof invId === "string" ? invId : invId?.id ?? null;
    if (!ch || !iid) return false;
    const row = await db.cyrusStorageCharge.findUnique({ where: { idemKey: `stripe:${iid}` } });
    if (!row) return false;
    await applyStorageEvent(storageEnvelope("purchase.refunded", row.userId, { idemKey: row.idemKey, method: "card", gb: row.gbTo, gbFrom: row.gbFrom, change: row.kind as StorageChange, cents: row.cents, periodEnd: row.periodEnd, refundedCents: ch.amount_refunded ?? 0 }));
    return true;
  }
  return false;
}

