type Move = { reference: string; cents: number; at: Date };
export type EntitlementSources = {
  plan(userId: string): Promise<Plan>;
  /** referenced wallet moves for Cyrus top-ups (charges negative, refunds positive) */
  walletMoves(userId: string, sinceMs: number): Promise<Move[]>;
  partner?(userId: string): Promise<Entitlement["partner"]>;
};

const STATUSES = new Set(["active", "trialing", "past_due", "canceled", "unpaid"]);
/** Pure: the entitlement from its sources' answers. Version = the newest change it reflects (ms). */
export function composeEntitlement(userId: string, plan: Plan, moves: Move[], partner: Entitlement["partner"], now = new Date()): Entitlement {
  const tier = plan && (ENTITLEMENT_TIERS as readonly string[]).includes(plan.tier) ? (plan.tier as EntitlementTier) : null;
  const charges = moves.filter((m) => m.cents < 0 && /^cwt:[^:]+:[A-Za-z0-9_-]{16,64}$/.test(m.reference));
  const refunds = new Map<string, number>();
  for (const m of moves) if (m.cents > 0 && m.reference.endsWith(":refund")) refunds.set(m.reference.slice(0, -":refund".length), (refunds.get(m.reference.slice(0, -":refund".length)) ?? 0) + m.cents);
  const purchases = charges.map((c) => ({ idemKey: c.reference, tokens: null, cents: -c.cents, method: "wallet" as const, at: c.at.toISOString(), refundedCents: Math.min(-c.cents, refunds.get(c.reference) ?? 0), chargeback: false }));
  const version = Math.max(0, plan ? plan.updatedAt.getTime() : 0, ...moves.map((m) => m.at.getTime()));
  return {
    subject: userId, version, issuedAt: now.toISOString(),
    plan: tier && plan ? { tier, status: STATUSES.has(plan.status) ? (plan.status as Entitlement["plan"]["status"]) : "unpaid", periodEnd: plan.currentPeriodEnd?.toISOString() ?? null, cancelAtPeriodEnd: plan.cancelAtPeriodEnd, product: productForTier(tier) }
      : { tier: null, status: "none", periodEnd: null, cancelAtPeriodEnd: false, product: null },
    purchases, partner,
  };
}

export const partnerAttributionEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_PARTNER_ATTRIBUTION === "1";

export const nxeonEntitlementSources: EntitlementSources = {
  plan: (userId) => cyrusDb.cyrusPlan.findUnique({ where: { userId }, select: { tier: true, status: true, currentPeriodEnd: true, cancelAtPeriodEnd: true, updatedAt: true } }),
  async walletMoves(userId, sinceMs) {
    const rows = await db.walletTransaction.findMany({ where: { userId, createdAt: { gte: new Date(sinceMs) }, description: { contains: `[ref:cwt:${userId}:` } }, select: { amountCents: true, description: true, createdAt: true }, orderBy: { createdAt: "asc" }, take: 500 });
    return rows.flatMap((r) => { const m = /\[ref:(cwt:[A-Za-z0-9:_-]+)\]$/.exec(r.description ?? ""); return m ? [{ reference: m[1], cents: r.amountCents, at: r.createdAt }] : []; });
  },
  async partner(userId) {
    if (!partnerAttributionEnabled()) return null;
    const a = await db.partnerCustomer.findUnique({ where: { customerId: userId }, include: { partner: true } });
    if (!a || a.partner.status !== "ACTIVE") return null;
    return { code: a.partner.code, firstPaymentPct: 50, recurringPct: 10 };
  },
};

/** GET /entitlements for one user (90 days of wallet top-ups). */
export async function entitlementsFor(userId: string, src: EntitlementSources = nxeonEntitlementSources, now = new Date()): Promise<Entitlement> {
  const [plan, moves, partner] = await Promise.all([src.plan(userId), src.walletMoves(userId, now.getTime() - 90 * DAY), src.partner?.(userId) ?? Promise.resolve(null)]);
  return composeEntitlement(userId, plan, moves, partner, now);

