/** Entitlement mirror (lib/cyrus/tokens/entitlement.ts): a wallet storage charge Nxeon reports. Applies it once if this
 *  side never did (same idemKey), and records a refund once. */
export async function applyMirroredStorageCharge(userId: string, s: { idemKey: string; gb: number; cents: number; at: string; refundedCents: number }, now = new Date()): Promise<void> {
