"use client";
// r51 storage: the buy-more slider (price from the SAME pricing function the server charges, with a chart of the price
// table), the cancel switch and the cleanup tool. Purchases are server actions; the server recomputes the price.
import { useMemo, useState, useTransition } from "react";
import { fmtBytes, fmtCents, literalCents, planChange, samePriceUpTo, storagePriceCents, type PriceBand, type PricingRule } from "@/lib/cyrus/storage/pricing";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { buyStorageWalletAction, cancelStorageAction, cleanupStorageAction, openStorageCardAction } from "@/app/dashboard/cyrus/app/account/storage-actions";

const newKey = () => Array.from(crypto.getRandomValues(new Uint8Array(12)), (b) => b.toString(16).padStart(2, "0")).join("");

type SliderProps = {
  table: PriceBand[]; rule: PricingRule; maxGb: number; planGb: number; currentGb: number; nextGb: number | null;
  periodStart: string | null; periodEnd: string | null; usedBytes: number; walletOk: boolean; cardOk: boolean; addonsOn: boolean; method: string | null;
};

/** Log-scale price chart: the price you pay (solid) against the owner's rates read literally (dashed: shows the cliffs). */
function PriceChart({ table, rule, maxGb, gb, onPick }: { table: PriceBand[]; rule: PricingRule; maxGb: number; gb: number; onPick: (g: number) => void }) {
  const W = 560, H = 190, L = 44, R = 12, T = 12, B = 30;
  const [hover, setHover] = useState<number | null>(null);
  const pts = useMemo(() => Array.from({ length: maxGb }, (_, i) => i + 1), [maxGb]);
  const yMax = Math.max(...pts.map((g) => Math.max(storagePriceCents(g, rule, table), literalCents(g, table)))) || 1;
  const x = (g: number) => L + (Math.log(g) / Math.log(Math.max(2, maxGb))) * (W - L - R);
  const y = (c: number) => T + (1 - c / yMax) * (H - T - B);
  const path = (f: (g: number) => number) => pts.map((g, i) => `${i ? "L" : "M"}${x(g).toFixed(1)},${y(f(g)).toFixed(1)}`).join("");
  const ticks = [...new Set([1, ...table.map((b) => b.fromGb).filter((b) => b <= maxGb), maxGb])];
  const yTicks = [0, 0.5, 1].map((f) => Math.round((yMax * f) / 100) * 100);
  const show = hover ?? gb;
  const gFromX = (px: number) => Math.max(1, Math.min(maxGb, Math.round(Math.exp(((px - L) / (W - L - R)) * Math.log(Math.max(2, maxGb))))));
  return (
    <figure className="cx-st-chart" aria-label="Monthly price by GB">
      <div className="cx-st-legend" aria-hidden="true"><span><i className="cx-st-k cx-st-ka" />Your price</span><span><i className="cx-st-k cx-st-kb" />Rate x GB, read literally</span></div>
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Price for ${show} GB: ${fmtCents(storagePriceCents(show, rule, table))} a month`}
        onPointerMove={(e) => { const r = (e.currentTarget as SVGSVGElement).getBoundingClientRect(); setHover(gFromX(((e.clientX - r.left) / r.width) * W)); }}
        onPointerLeave={() => setHover(null)} onClick={() => hover && onPick(hover)}>
        {yTicks.map((c) => <g key={c}><line x1={L} x2={W - R} y1={y(c)} y2={y(c)} className="cx-st-grid" /><text x={L - 6} y={y(c) + 4} textAnchor="end" className="cx-st-ax">${c / 100}</text></g>)}
        {ticks.map((g) => <text key={g} x={x(g)} y={H - 10} textAnchor="middle" className="cx-st-ax">{g} GB</text>)}
        <path d={path((g) => literalCents(g, table))} className="cx-st-lit" />
        <path d={path((g) => storagePriceCents(g, rule, table))} className="cx-st-line" />
        <line x1={x(show)} x2={x(show)} y1={T} y2={H - B} className="cx-st-cross" />
        <circle cx={x(show)} cy={y(storagePriceCents(show, rule, table))} r={5} className="cx-st-dot" />
      </svg>
      <figcaption className="cx-faint" style={{ fontSize: 12 }}>{show} GB: {fmtCents(storagePriceCents(show, rule, table))} a month{literalCents(show, table) !== storagePriceCents(show, rule, table) ? ` (literal rate would be ${fmtCents(literalCents(show, table))})` : ""}. Hover or tap the chart to pick.</figcaption>
    </figure>
  );
}

export function StorageSlider(p: SliderProps) {
  const [gb, setGb] = useState(Math.max(1, p.currentGb || 5));
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  const [busy, start] = useTransition();
  const price = storagePriceCents(gb, p.rule, p.table);
  const same = samePriceUpTo(gb, p.rule, p.table, p.maxGb);
  const change = planChange({ fromGb: p.currentGb, toGb: gb, periodStart: p.periodStart ? new Date(p.periodStart) : null, periodEnd: p.periodEnd ? new Date(p.periodEnd) : null, now: new Date(), rule: p.rule, table: p.table });
  const total = p.planGb + gb;
  const verb = change.kind === "new" ? `Add ${gb} GB` : change.kind === "increase" ? `Upgrade to ${gb} GB` : change.kind === "decrease" ? `Lower to ${gb} GB at renewal` : "No change";
  const pay = () => start(async () => {
    setMsg(null);
    const r = await buyStorageWalletAction(gb, newKey());
    setMsg(r.ok ? { ok: true, text: r.message } : { ok: false, text: r.error });
    if (r.ok) setTimeout(() => location.reload(), 900);
  });
  const card = () => start(async () => {
    setMsg(null);
    const r = await openStorageCardAction(gb);
    if (r.ok) setCheckout({ clientSecret: r.clientSecret, publishableKey: r.publishableKey }); else setMsg({ ok: false, text: r.error });
  });
  return (
    <div className="cx-st-buy">
      <div className="cx-st-pick">
        <label className="cx-label" htmlFor="cx-st-gb">Extra storage</label>
        <div className="cx-st-val"><b className="cx-big">{gb} GB</b><span className="cx-muted">{fmtCents(price)} / month</span><span className="cx-faint">{(price / gb / 100).toFixed(3)} $/GB</span></div>
        <input id="cx-st-gb" type="range" min={1} max={p.maxGb} step={1} value={gb} onChange={(e) => setGb(Number(e.target.value))} aria-valuetext={`${gb} GB, ${fmtCents(price)} a month`} className="cx-st-range" />
        <div className="cx-st-quick">{[1, 5, 25, 50, 100].filter((g) => g <= p.maxGb).map((g) => <button key={g} type="button" className="cx-btn cx-btn-sm" aria-pressed={g === gb} onClick={() => setGb(g)}>{g} GB</button>)}</div>
        {same > gb ? <p className="cx-note" style={{ margin: 0 }}><b>Same price, more space:</b> {same} GB also costs {fmtCents(price)} a month. <button type="button" className="cx-btn cx-btn-sm" onClick={() => setGb(same)}>Take {same} GB</button></p> : null}
        <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Your total would be <b>{total} GB</b> ({p.planGb} GB with your plan + {gb} GB extra). You use {fmtBytes(p.usedBytes)} today.</p>
        {change.kind === "increase" ? <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Upgrading now costs {fmtCents(change.chargeCents)} for the rest of this month, then {fmtCents(price)} a month.</p> : null}
        {change.kind === "decrease" ? <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Lowering takes effect at your next renewal; you keep {p.currentGb} GB until then. Nothing is deleted.</p> : null}
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button type="button" className="cx-btn cx-btn-pri" disabled={!p.addonsOn || !p.walletOk || busy || change.kind === "same" || p.method === "card"} onClick={pay}>{busy ? "Working..." : `${verb}${change.chargeCents ? ` · ${fmtCents(change.chargeCents)} from wallet` : ""}`}</button>
          {p.currentGb === 0 ? <button type="button" className="cx-btn" disabled={!p.addonsOn || !p.cardOk || busy} onClick={card}>Pay by card</button> : null}
        </div>
        {!p.addonsOn ? <p className="cx-note" style={{ margin: 0 }}>Buying storage isn&apos;t open yet. Prices shown are placeholders.</p> : null}
        {msg ? <p className={msg.ok ? "cx-okmsg" : "cx-error"} role="status" style={{ margin: 0 }}>{msg.text}</p> : null}
      </div>
      <PriceChart table={p.table} rule={p.rule} maxGb={p.maxGb} gb={gb} onPick={setGb} />
      {checkout ? <StripeCheckoutModal clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onClose={() => setCheckout(null)} title="Cyrus storage" /> : null}
    </div>
  );
}

export function CancelStorage({ cancelling, until }: { cancelling: boolean; until: string | null }) {
  const [busy, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span style={{ display: "inline-flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
      <button type="button" className="cx-btn cx-btn-sm" disabled={busy} onClick={() => start(async () => { const r = await cancelStorageAction(!cancelling); if (r.ok) location.reload(); else setErr(r.error); })}>
        {cancelling ? "Keep my extra storage" : "Cancel at renewal"}
      </button>
      {cancelling && until ? <span className="cx-faint" style={{ fontSize: 12 }}>Ends {new Date(until).toLocaleDateString("en-GB", { day: "numeric", month: "short" })}. Nothing is deleted.</span> : null}
      {err ? <span className="cx-error">{err}</span> : null}
    </span>
  );
}

type Cand = { builds: { id: string; label: string | null; version: string | null; bytes: number; createdAt: string; suggested: boolean }[]; drafts: { id: string; assetKey: string; surface: string; bytes: number; updatedAt: string; suggested: boolean }[]; uploads: { name: string; bytes: number }[]; retentionDays: number };

export function StorageCleanup({ c, confirmWord }: { c: Cand; confirmWord: string }) {
  const [builds, setBuilds] = useState(() => new Set(c.builds.filter((b) => b.suggested).map((b) => b.id)));
  const [drafts, setDrafts] = useState(() => new Set(c.drafts.filter((d) => d.suggested).map((d) => d.id)));
  const [uploads, setUploads] = useState(false);
  const [confirm, setConfirm] = useState("");
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [busy, start] = useTransition();
  const bytes = c.builds.filter((b) => builds.has(b.id)).reduce((a, b) => a + b.bytes, 0) + c.drafts.filter((d) => drafts.has(d.id)).reduce((a, d) => a + d.bytes, 0) + (uploads ? c.uploads.reduce((a, u) => a + u.bytes, 0) : 0);
  const tog = (s: Set<string>, set: (x: Set<string>) => void, id: string) => { const n = new Set(s); if (n.has(id)) n.delete(id); else n.add(id); set(n); };
  const day = (s: string) => new Date(s).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
  if (!c.builds.length && !c.drafts.length && !c.uploads.length) return <p className="cx-muted" style={{ margin: 0 }}>Nothing to clean up: every stored build is your newest version, installed, or part of a pack.</p>;
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Ticked by default: things untouched for {c.retentionDays} days. Removing an old version&apos;s jar keeps its history; ask for a change to rebuild it. Your newest version, installed versions and pack members are never offered.</p>
      {c.builds.length ? <div className="cx-list" aria-label="Old build versions">{c.builds.slice(0, 50).map((b) => (
        <label key={b.id} className="cx-row cx-check"><input type="checkbox" checked={builds.has(b.id)} onChange={() => tog(builds, setBuilds, b.id)} /><span className="cx-grow">{b.label ?? "Mod"} {b.version ? `v${b.version}` : ""} <span className="cx-faint">· built {day(b.createdAt)}</span></span><span className="cx-mono">{fmtBytes(b.bytes)}</span></label>
      ))}</div> : null}
      {c.drafts.length ? <div className="cx-list" aria-label="Studio drafts">{c.drafts.slice(0, 50).map((d) => (
        <label key={d.id} className="cx-row cx-check"><input type="checkbox" checked={drafts.has(d.id)} onChange={() => tog(drafts, setDrafts, d.id)} /><span className="cx-grow">Unsaved {d.surface} draft of {d.assetKey} <span className="cx-faint">· last edited {day(d.updatedAt)}</span></span><span className="cx-mono">{fmtBytes(d.bytes)}</span></label>
      ))}</div> : null}
      {c.uploads.length ? <label className="cx-row cx-check"><input type="checkbox" checked={uploads} onChange={() => setUploads(!uploads)} /><span className="cx-grow">{c.uploads.length} pending reference image files not attached to a build</span><span className="cx-mono">{fmtBytes(c.uploads.reduce((a, u) => a + u.bytes, 0))}</span></label> : null}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        <input className="cx-input" style={{ maxWidth: 160 }} placeholder={`Type ${confirmWord}`} value={confirm} onChange={(e) => setConfirm(e.target.value)} aria-label={`Type ${confirmWord} to confirm`} />
        <button type="button" className="cx-btn cx-btn-danger" disabled={busy || confirm !== confirmWord || bytes === 0} onClick={() => start(async () => {
          const r = await cleanupStorageAction({ buildIds: [...builds], draftIds: [...drafts], uploads, confirm });
          setMsg(r.ok ? { ok: true, text: `Freed ${fmtBytes(r.removedBytes)}.` } : { ok: false, text: r.error });
          if (r.ok) setTimeout(() => location.reload(), 900);
        })}>Delete selected · {fmtBytes(bytes)}</button>
      </div>
      {msg ? <p className={msg.ok ? "cx-okmsg" : "cx-error"} role="status" style={{ margin: 0 }}>{msg.text}</p> : null}
    </div>
  );
}

