"use server";
// r51 storage actions. Every action re-runs the app gate (fail closed), acts only on the viewer's own account, and the
// server prices everything again (the slider's number is never trusted).
import { checkRateLimit } from "@/lib/rate-limit";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { cancelStorageAddon, openStorageCheckout, setStorageAddonWallet } from "@/lib/cyrus/storage/addon";
import { runCleanup } from "@/lib/cyrus/storage/cleanup";
import { fmtCents } from "@/lib/cyrus/storage/pricing";
import { appViewerOrNull } from "../_gate";

type R<T = object> = ({ ok: true } & T) | { ok: false; error: string };
const NOPE = { ok: false as const, error: "Not found." };
const limited = (key: string, max: number) => { const r = checkRateLimit(key, { max, windowMs: 60_000 }); return r.ok ? null : { ok: false as const, error: `Too many requests. Try again in ${r.retryAfterSec}s.` }; };

export async function buyStorageWalletAction(gb: number, key: string): Promise<R<{ message: string }>> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:storage:${v.user.id}`, 6); if (rl) return rl;
  const r = await setStorageAddonWallet(v.user, Math.floor(Number(gb)), String(key));
  if (r.state === "active") return { ok: true, message: r.chargedCents ? `Done: ${fmtCents(r.chargedCents)} from your wallet. Your extra storage is active.` : "Done. Your extra storage is active." };
  if (r.state === "pending") return { ok: true, message: "Paid. Your extra storage will appear in a moment." };
  if (r.state === "scheduled") return { ok: true, message: r.effective === "period_end" ? "Saved. The new amount starts at your next renewal." : "Saved." };
  if (r.state === "unchanged") return { ok: true, message: "That's what you have already." };
  return { ok: false, error: r.error ?? "Couldn't change your storage." };
}

export async function openStorageCardAction(gb: number): Promise<R<{ clientSecret: string; publishableKey: string }>> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:storagecard:${v.user.id}`, 6); if (rl) return rl;
  const cfg = bridgeConfig();
  return openStorageCheckout(v.user, Math.floor(Number(gb)), { returnBase: v.onCyrus ? cfg.cyrusOrigin : cfg.nxeonOrigin });
}

export async function cancelStorageAction(cancel: boolean): Promise<R> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:storagecancel:${v.user.id}`, 10); if (rl) return rl;
  const r = await cancelStorageAddon(v.user, !!cancel);
  return r.ok ? { ok: true } : { ok: false, error: r.error ?? "Couldn't change it." };
}

export async function cleanupStorageAction(input: { buildIds: string[]; draftIds: string[]; uploads: boolean; confirm: string }): Promise<R<{ removedBytes: number }>> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:storageclean:${v.user.id}`, 6); if (rl) return rl;
  const ids = (a: unknown) => (Array.isArray(a) ? a.filter((x): x is string => typeof x === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(x)).slice(0, 500) : []);
  const r = await runCleanup(v.user.id, { buildIds: ids(input?.buildIds), draftIds: ids(input?.draftIds), uploads: !!input?.uploads, confirm: String(input?.confirm ?? "") });
  return r.ok ? { ok: true, removedBytes: r.removedBytes } : r;
}

