// r51 storage tab (server component): the meter, the breakdown per category / game / mod, the "storage full" state,
// the add-on, the slider and the cleanup tool. Reads only the viewer's own account.
import { accountStorage } from "@/lib/cyrus/storage/service";
import { loadStorageConfig, meterLevel, storageAddonsEnabled, storageEnabled } from "@/lib/cyrus/storage/config";
import { CATEGORY_LABEL, CATEGORY_ORDER } from "@/lib/cyrus/storage/accounting";
import { CLEANUP_CONFIRM, cleanupCandidates } from "@/lib/cyrus/storage/cleanup";
import { fmtBytes, fmtCents, GB, storagePriceCents } from "@/lib/cyrus/storage/pricing";
import { getHost } from "@/lib/cyrus/host";
import { Card, Empty } from "./ui";
import { CancelStorage, StorageCleanup, StorageSlider } from "./StoragePanels";

const LEVEL_TEXT = { ok: "", warn: "You have used most of your storage.", high: "Your storage is almost full.", full: "Your storage is full." } as const;
const day = (d: Date | string) => new Date(d).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
const PLAN_NAME: Record<string, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "Yakko" };

export async function StorageView({ userId, accountHref }: { userId: string; accountHref: string }) {
  const cfg = await loadStorageConfig();
  const on = storageEnabled();
  const s = on ? await accountStorage(userId).catch(() => null) : null;
  const tier = s?.tier ?? "free";
  const used = s ? s.usedBytes + s.pendingBytes : 0;
  const quota = s?.quotaBytes ?? Math.round(cfg.quotaGb[tier] * GB);
  const m = meterLevel(used, quota, cfg);
  const b = s?.breakdown;
  const graceOn = !!s?.graceUntil && s.graceUntil.getTime() > Date.now();
  const blocked = m.level === "full" && !graceOn;
  const cand = on ? await cleanupCandidates(userId).catch(() => null) : null;
  const h = getHost().billing;
  const addon = s?.addon;
  const pct = Math.min(100, m.pct);
  const marks = cfg.warnPcts;
  return (
    <div style={{ display: "grid", gap: 14 }}>
      <Card title="Storage" aside={on ? `${PLAN_NAME[tier] ?? tier} plan` : "not active yet"}>
        {!on ? <p className="cx-note" style={{ marginTop: 0 }}>Storage limits are not switched on yet: nothing is measured or blocked. Below are the planned quotas and prices (placeholders until they are confirmed).</p> : null}
        {on && !s ? <p className="cx-error">We couldn&apos;t measure your storage just now. New builds and uploads wait until we can (installing and exporting still work).</p> : null}
        <div className={`cx-st-meter cx-st-${m.level}`}>
          <div className="cx-st-nums"><b className="cx-big">{fmtBytes(used)}</b><span className="cx-muted"> of {fmtBytes(quota)} used</span><span className="cx-st-pct">{m.pct}%</span></div>
          <div className="cx-st-bar" role="meter" aria-valuemin={0} aria-valuemax={100} aria-valuenow={pct} aria-label="Storage used">
            <i style={{ width: `${pct}%` }} />
