              {addon.status === "active" ? <div className="cx-row"><span className="cx-grow" /><CancelStorage cancelling={addon.nextGb === 0} until={addon.periodEnd ? addon.periodEnd.toISOString() : null} /></div> : null}
            </div>
          ) : null}
          <StorageSlider table={cfg.table} rule={cfg.rule} maxGb={cfg.addonMaxGb} planGb={cfg.quotaGb[tier]} currentGb={s?.addonGb ?? 0} nextGb={addon?.nextGb ?? null}
            periodStart={addon?.periodStart ? addon.periodStart.toISOString() : null} periodEnd={addon?.periodEnd ? addon.periodEnd.toISOString() : null} usedBytes={used}
            walletOk={!!h.wallet} cardOk={!!h.stripe?.configured()} addonsOn={storageAddonsEnabled()} method={addon?.status === "active" ? addon.method : null} />
          <p className="cx-faint" style={{ fontSize: 12, marginBottom: 0 }}>Included: Free {cfg.quotaGb.free} GB, Katara {cfg.quotaGb.katara} GB, Saka {cfg.quotaGb.saka} GB, Yakko {cfg.quotaGb.all} GB. Prices are placeholders until confirmed. Cancel any time: you keep the space until the end of the month you paid for, and nothing is ever deleted for you. <a href={`${accountHref}?tab=billing`}>Plan and billing</a></p>
        </Card>
      </section>

      {on ? (
        <section id="clean-up" style={{ scrollMarginTop: 16 }}>
          <Card title="Free up space">
            {cand ? <StorageCleanup c={cand} confirmWord={CLEANUP_CONFIRM} /> : <p className="cx-error">Couldn&apos;t load the cleanup list.</p>}
          </Card>
        </section>
      ) : null}
    </div>
  );
}

