// r51 storage tab (server component): the meter, the breakdown per category / game / mod, the "storage full" state,
// the add-on, the slider and the cleanup tool. Reads only the viewer's own account.
import { accountStorage } from "@/lib/cyrus/storage/service";
import { loadStorageConfig, meterLevel, storageAddonsEnabled, storageEnabled } from "@/lib/cyrus/storage/config";
import { CATEGORY_LABEL, CATEGORY_ORDER } from "@/lib/cyrus/storage/accounting";
import { CLEANUP_CONFIRM, cleanupCandidates } from "@/lib/cyrus/storage/cleanup";
import { fmtBytes, fmtCents, GB, storagePriceCents } from "@/lib/cyrus/storage/pricing";
import { getHost } from "@/lib/cyrus/host";
import { Card, Empty } from "./ui";
import { CancelStorage, StorageCleanup, StorageSlider } from "./StoragePanels";

const LEVEL_TEXT = { ok: "", warn: "You have used most of your storage.", high: "Your storage is almost full.", full: "Your storage is full." } as const;
const day = (d: Date | string) => new Date(d).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
const PLAN_NAME: Record<string, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "Yakko" };

export async function StorageView({ userId, accountHref }: { userId: string; accountHref: string }) {
  const cfg = await loadStorageConfig();
  const on = storageEnabled();
  const s = on ? await accountStorage(userId).catch(() => null) : null;
  const tier = s?.tier ?? "free";
  const used = s ? s.usedBytes + s.pendingBytes : 0;
  const quota = s?.quotaBytes ?? Math.round(cfg.quotaGb[tier] * GB);
  const m = meterLevel(used, quota, cfg);
  const b = s?.breakdown;
  const graceOn = !!s?.graceUntil && s.graceUntil.getTime() > Date.now();
  const blocked = m.level === "full" && !graceOn;
  const cand = on ? await cleanupCandidates(userId).catch(() => null) : null;
  const h = getHost().billing;
  const addon = s?.addon;
  const pct = Math.min(100, m.pct);
  const marks = cfg.warnPcts;
  return (
    <div style={{ display: "grid", gap: 14 }}>
      <Card title="Storage" aside={on ? `${PLAN_NAME[tier] ?? tier} plan` : "not active yet"}>
        {!on ? <p className="cx-note" style={{ marginTop: 0 }}>Storage limits are not switched on yet: nothing is measured or blocked. Below are the planned quotas and prices (placeholders until they are confirmed).</p> : null}
        {on && !s ? <p className="cx-error">We couldn&apos;t measure your storage just now. New builds and uploads wait until we can (installing and exporting still work).</p> : null}
        <div className={`cx-st-meter cx-st-${m.level}`}>
          <div className="cx-st-nums"><b className="cx-big">{fmtBytes(used)}</b><span className="cx-muted"> of {fmtBytes(quota)} used</span><span className="cx-st-pct">{m.pct}%</span></div>
          <div className="cx-st-bar" role="meter" aria-valuemin={0} aria-valuemax={100} aria-valuenow={pct} aria-label="Storage used">
            <i style={{ width: `${pct}%` }} />
            {marks.slice(0, 2).map((x) => <span key={x} className="cx-st-mark" style={{ left: `${x}%` }} title={`${x}%`} />)}
          </div>
          <div className="cx-st-scale cx-faint"><span>0</span><span style={{ left: `${marks[0]}%` }}>{marks[0]}%</span><span style={{ left: `${marks[1]}%` }}>{marks[1]}%</span><span style={{ right: 0 }}>{fmtBytes(quota)}</span></div>
          <p className="cx-muted" style={{ margin: "8px 0 0", fontSize: 13 }}>{cfg.quotaGb[tier]} GB with your plan{s?.addonGb ? ` + ${s.addonGb} GB extra` : ""}. {b && b.dedupedBytes > 0 ? `Shared files counted once saved you ${fmtBytes(b.dedupedBytes)}.` : ""}{s?.computedAt ? ` Measured ${s.computedAt.toLocaleString("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}.` : ""}</p>
        </div>
        {m.level !== "ok" ? (
          <div className={`cx-st-alert cx-st-${m.level}`} role={blocked ? "alert" : "status"}>
            <b>{LEVEL_TEXT[m.level]}</b>{" "}
            {blocked ? "New builds, uploads and library contributions are paused until you free up space or add storage. Installing, keeping and exporting your mods still works, and nothing is ever deleted for you." : graceOn ? `You're over your storage after a change to your plan or storage. Everything keeps working until ${day(s!.graceUntil!)}; after that new builds and uploads pause until you're under it. Nothing is deleted.` : "Free up space or add storage before it fills up."}
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10 }}>
              <a className="cx-btn cx-btn-sm cx-btn-pri" href="#add-storage">Add storage</a>
              <a className="cx-btn cx-btn-sm" href="#clean-up">Free up space</a>
            </div>
          </div>
        ) : null}
      </Card>

      {b ? (
        <div className="cx-grid" style={{ display: "grid", gap: 14, gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))" }}>
          <Card title="What uses it">
            <div className="cx-list">{CATEGORY_ORDER.map((c) => (
              <div key={c} className="cx-row cx-st-cat"><span className="cx-grow">{CATEGORY_LABEL[c]}<span className="cx-meter" style={{ display: "block", marginTop: 6 }}><i style={{ width: `${b.totalBytes ? Math.max(b.byCategory[c] ? 1 : 0, (b.byCategory[c] / b.totalBytes) * 100) : 0}%` }} /></span></span><span className="cx-mono">{fmtBytes(b.byCategory[c])}</span></div>
            ))}</div>
          </Card>
          <Card title="Per game">
            {Object.keys(b.byGame).length ? <div className="cx-list">{Object.entries(b.byGame).sort((x, y) => y[1] - x[1]).map(([g, n]) => (
              <div key={g} className="cx-row"><span className="cx-grow">{g === "unassigned" ? "Not tied to a game (packs, uploads, library)" : g[0].toUpperCase() + g.slice(1)}</span><span className="cx-mono">{fmtBytes(n)}</span></div>
            ))}</div> : <Empty>Nothing stored yet.</Empty>}
            <p className="cx-faint" style={{ fontSize: 12, marginBottom: 0 }}>A file used in two games shows in both; your total counts it once.</p>
          </Card>
        </div>
      ) : null}

      {b ? (
        <Card title="Per mod" aside={b.byMod.length ? `${b.byMod.length + b.modsTruncated} mods` : undefined}>
          {b.byMod.length ? (
            <div className="cx-st-table" role="table" aria-label="Storage per mod">
              <div className="cx-st-tr cx-st-th" role="row"><span role="columnheader">Mod</span><span role="columnheader">Builds</span><span role="columnheader">Assets</span><span role="columnheader">Revisions</span><span role="columnheader">Other</span><span role="columnheader">Total</span></div>
              {b.byMod.slice(0, 30).map((x) => {
                const o = (x.byCategory.drafts ?? 0) + (x.byCategory.uploads ?? 0) + (x.byCategory.packs ?? 0) + (x.byCategory.library ?? 0);
                return (
                  <div key={x.modId} className="cx-st-tr" role="row">
                    <span role="cell" className="cx-st-name">{x.label ?? "Untitled mod"} <span className="cx-faint">{x.game ?? ""}</span></span>
                    <span role="cell" className="cx-mono" data-l="Builds">{fmtBytes(x.byCategory.builds ?? 0)}</span>
                    <span role="cell" className="cx-mono" data-l="Assets">{fmtBytes(x.byCategory.assets ?? 0)}</span>
                    <span role="cell" className="cx-mono" data-l="Revisions">{fmtBytes(x.byCategory.revisions ?? 0)}</span>
                    <span role="cell" className="cx-mono" data-l="Other">{fmtBytes(o)}</span>
                    <span role="cell" className="cx-mono" data-l="Total"><b>{fmtBytes(x.bytes)}</b></span>
                  </div>
                );
              })}
            </div>
          ) : <Empty>No mods yet.</Empty>}
        </Card>
      ) : null}

      <section id="add-storage" style={{ scrollMarginTop: 16 }}>
        <Card title="Add storage" aside="monthly · billed through Nxeon">
          {addon && addon.status !== "none" ? (
            <div className="cx-list" style={{ marginBottom: 14 }}>
              <div className="cx-row"><span className="cx-grow cx-muted">Extra storage</span><b>{addon.status === "active" ? `${addon.gb} GB` : `none (${addon.status.replace("_", " ")})`}</b></div>
              {addon.status === "active" && addon.periodEnd ? <div className="cx-row"><span className="cx-grow cx-muted">{addon.nextGb === 0 ? "Ends" : "Renews"}</span><span>{day(addon.periodEnd)} · {fmtCents(storagePriceCents(addon.nextGb ?? addon.gb, cfg.rule, cfg.table))}{addon.nextGb && addon.nextGb !== addon.gb ? ` for ${addon.nextGb} GB` : ""} · {addon.method === "card" ? "card" : "wallet"}</span></div> : null}
              {addon.status === "past_due" ? <div className="cx-row"><span className="cx-error">Your last renewal couldn&apos;t be paid from your wallet. Add funds at Nxeon; we retry daily for 7 days.</span></div> : null}
              {addon.status === "active" ? <div className="cx-row"><span className="cx-grow" /><CancelStorage cancelling={addon.nextGb === 0} until={addon.periodEnd ? addon.periodEnd.toISOString() : null} /></div> : null}
            </div>
          ) : null}
          <StorageSlider table={cfg.table} rule={cfg.rule} maxGb={cfg.addonMaxGb} planGb={cfg.quotaGb[tier]} currentGb={s?.addonGb ?? 0} nextGb={addon?.nextGb ?? null}
            periodStart={addon?.periodStart ? addon.periodStart.toISOString() : null} periodEnd={addon?.periodEnd ? addon.periodEnd.toISOString() : null} usedBytes={used}
            walletOk={!!h.wallet} cardOk={!!h.stripe?.configured()} addonsOn={storageAddonsEnabled()} method={addon?.status === "active" ? addon.method : null} />
          <p className="cx-faint" style={{ fontSize: 12, marginBottom: 0 }}>Included: Free {cfg.quotaGb.free} GB, Katara {cfg.quotaGb.katara} GB, Saka {cfg.quotaGb.saka} GB, Yakko {cfg.quotaGb.all} GB. Prices are placeholders until confirmed. Cancel any time: you keep the space until the end of the month you paid for, and nothing is ever deleted for you. <a href={`${accountHref}?tab=billing`}>Plan and billing</a></p>
        </Card>
      </section>

      {on ? (
        <section id="clean-up" style={{ scrollMarginTop: 16 }}>
          <Card title="Free up space">
            {cand ? <StorageCleanup c={cand} confirmWord={CLEANUP_CONFIRM} /> : <p className="cx-error">Couldn&apos;t load the cleanup list.</p>}
          </Card>
        </section>
      ) : null}
    </div>
  );
}

