// r51 storage against the devhost THROWAWAY database: real recompute + dedupe, the fail-closed gate and the grace, the
// wallet add-on (buy once on retry, prorated increase, decrease at renewal, renewal, cancel -> grace, refund reverses),
// the event path once, the entitlement mirror and the reconcile.
// Opt-in, fail-closed: runs only when DATABASE_URL is a node-2 devhost db (127.0.0.1:5433/wt_*) and CYRUS_STORAGE_DB_TEST=1.
//   scripts/devhost run -- env CYRUS_STORAGE_DB_TEST=1 npx tsx --test test/cyrus-storage-db.test.ts
import "./_cyrus-server-only-shim";
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_STORAGE_DB_TEST === "1" && /@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?|$)/.test(url);
const skip = safe ? false : "devhost throwaway DB only (CYRUS_STORAGE_DB_TEST=1)";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let S: typeof import("../lib/cyrus/storage/service.ts");
let A: typeof import("../lib/cyrus/storage/addon.ts");
let C: typeof import("../lib/cyrus/storage/config.ts");
const users: string[] = [];
const key = () => `k${Date.now().toString(36)}${Math.random().toString(36).slice(2)}xxxxxxxxxxxx`.slice(0, 32);
const SHA = (c: string) => c.repeat(64).slice(0, 64);
async function mkUser(cents: number) {
  const u = await db.user.create({ data: { email: `stg-${key()}@example.test`, passwordHash: "x", name: "Storage", balanceCents: cents, emailVerifiedAt: new Date() } });
  users.push(u.id);
  return u;
}
const wallet = async (id: string) => (await db.user.findUniqueOrThrow({ where: { id } })).balanceCents;
const acct = (id: string) => db.cyrusStorageAccount.findUniqueOrThrow({ where: { userId: id } });

before(async () => {
  if (!safe) return;
  process.env.CYRUS_STORAGE = "1";
  process.env.CYRUS_STORAGE_ADDONS = "1";
  process.env.NXEON_MODBUILD_DIR = mkdtempSync(path.join(tmpdir(), "cyrus-storage-"));
  db = (await import("../lib/db.ts")).db;
  S = await import("../lib/cyrus/storage/service.ts");
  A = await import("../lib/cyrus/storage/addon.ts");
  C = await import("../lib/cyrus/storage/config.ts");
  S.setStorageDepsForTests({ tier: async () => "free", config: async () => C.parseStorageConfig({ cyrus_storage_quota_free_gb: "0.00001" }) }); // ~10.7 KB
});
after(async () => {
  if (!safe) return;
  S.setStorageDepsForTests(null);
  const projects = await db.cyrusProject.findMany({ where: { userId: { in: users } }, select: { id: true } });
  await db.cyrusProjectAsset.deleteMany({ where: { projectId: { in: projects.map((p) => p.id) } } });
  await db.cyrusRevision.deleteMany({ where: { projectId: { in: projects.map((p) => p.id) } } });
  await db.cyrusProject.deleteMany({ where: { userId: { in: users } } });
  await db.modBuild.deleteMany({ where: { userId: { in: users } } });
  await db.cyrusStorageCharge.deleteMany({ where: { userId: { in: users } } });
  await db.cyrusStorageAccount.deleteMany({ where: { userId: { in: users } } });
  await db.walletTransaction.deleteMany({ where: { userId: { in: users } } });
  await db.user.deleteMany({ where: { id: { in: users } } });
  await db.$disconnect();
});

describe("accounting + gate on Postgres", { skip }, () => {
  it("recomputes from real rows, deduped by sha256, per mod", async () => {
    const u = await mkUser(0);
    await db.modBuild.create({ data: { id: `mb${key()}`.slice(0, 22), userId: u.id, prompt: "p", mcVersion: "1.21.11", status: "succeeded", jarPath: "/nonexistent/a.jar", jarSize: 4000, jarSha256: SHA("a"), pluginName: "Lamps" } });
    const p = await db.cyrusProject.create({ data: { id: `cp${key()}`.slice(0, 24), userId: u.id, game: "minecraft", namespace: `nx_${key().slice(0, 8)}` } });
    const rev = await db.cyrusRevision.create({ data: { projectId: p.id, seq: 1, kind: "asset", manifest: [], status: "passed" } });
    for (const k of ["a1", "a2"]) await db.cyrusProjectAsset.create({ data: { projectId: p.id, revisionId: rev.id, assetKey: k, kind: "texture", sha256: SHA("b"), size: 900, origin: "upload" } });
    const s = await S.recomputeStorage(u.id);
    assert.equal(s.breakdown!.byCategory.builds, 4000);
    assert.equal(s.breakdown!.byCategory.assets, 900);
    assert.ok(s.breakdown!.byCategory.revisions > 0);
    assert.equal(s.usedBytes, s.breakdown!.totalBytes);
    assert.equal(s.breakdown!.dedupedBytes, 900);
  });

  it("first measurement over quota gets the grace; after it, writes are refused (507); data stays", async () => {
    const u = await mkUser(0);
    await db.modBuild.create({ data: { id: `mb${key()}`.slice(0, 22), userId: u.id, prompt: "p", mcVersion: "1.21.11", status: "succeeded", jarPath: "/nonexistent/b.jar", jarSize: 50_000, jarSha256: SHA("c") } });
    const g1 = await S.checkStorageWrite(u.id, 10, "upload");
    assert.deepEqual(g1, { ok: true, grace: true });
    await db.cyrusStorageAccount.update({ where: { userId: u.id }, data: { graceUntil: new Date(Date.now() - 1000) } });
    const g2 = await S.checkStorageWrite(u.id, 10, "upload");
    assert.equal(g2.ok, false);
    assert.equal(!g2.ok && g2.status, 507);
    assert.equal(!g2.ok && g2.code, "storage_full");
    assert.equal(await db.modBuild.count({ where: { userId: u.id } }), 1);
  });

  it("fails closed when usage cannot be read", async () => {
    const u = await mkUser(0);
    S.setStorageDepsForTests({ tier: async () => { throw new Error("down"); }, config: async () => C.parseStorageConfig({}) });
    try {
      const g = await S.checkStorageWrite(u.id, 1, "build");
      assert.equal(g.ok, false);
      assert.equal(!g.ok && g.code, "storage_unknown");
    } finally {
      S.setStorageDepsForTests({ tier: async () => "free", config: async () => C.parseStorageConfig({ cyrus_storage_quota_free_gb: "0.00001" }) });
    }
  });

  it("incremental: a noted write counts at once, the recompute settles it", async () => {
    const u = await mkUser(0);
    await S.recomputeStorage(u.id);
    await S.noteStorageWrite(u.id, 5000);
    assert.equal(Number((await acct(u.id)).pendingBytes), 5000);
    const g = await S.checkStorageWrite(u.id, 6000, "upload");
    assert.equal(g.ok, false); // 5000 pending + 6000 > ~10.7 KB
    await S.recomputeStorage(u.id);
    assert.equal(Number((await acct(u.id)).pendingBytes), 0);
  });
});

describe("storage add-on through the Nxeon wallet", { skip }, () => {
  it("buy once on retry, prorated increase, decrease at renewal, renewal, cancel -> lapse + grace, refund reverses", async () => {
    S.setStorageDepsForTests({ tier: async () => "free", config: async () => C.parseStorageConfig({}) });
    const u = await mkUser(10_000);
    const k = key();
    const t0 = new Date();
    const r1 = await A.setStorageAddonWallet(u, 10, k, t0);
    assert.equal(r1.state, "active");
    assert.equal(r1.chargedCents, 750);
    const r1b = await A.setStorageAddonWallet(u, 10, k, t0);
    assert.notEqual(r1b.chargedCents, 750);
    assert.equal(await wallet(u.id), 10_000 - 750);
    let a = await acct(u.id);
    assert.deepEqual([a.addonGb, a.addonStatus, a.addonMethod], [10, "active", "wallet"]);
    assert.equal(Number(a.quotaBytes), 11 * 1024 ** 3);

    const r2 = await A.setStorageAddonWallet(u, 20, key(), new Date(t0.getTime() + 1000));
    assert.equal(r2.state, "active");
    assert.ok(r2.chargedCents > 700 && r2.chargedCents <= 750, `prorated ${r2.chargedCents}`);
    a = await acct(u.id);
    assert.equal(a.addonGb, 20);

    const r3 = await A.setStorageAddonWallet(u, 5, key(), new Date(t0.getTime() + 2000));
    assert.deepEqual([r3.state, r3.effective], ["scheduled", "period_end"]);
    assert.equal((await acct(u.id)).addonNextGb, 5);

    const before = await wallet(u.id);
    const end = (await acct(u.id)).addonPeriodEnd!;
    const s1 = await A.storageRenewalSweep(new Date(end.getTime() + 60_000));
    assert.equal(s1.renewed, 1);
    assert.equal(await wallet(u.id), before - 375);
    a = await acct(u.id);
    assert.deepEqual([a.addonGb, a.addonNextGb], [5, null]);
    assert.ok(a.addonPeriodEnd!.getTime() > end.getTime());
    const again = await A.storageRenewalSweep(new Date(end.getTime() + 120_000));
    assert.equal(again.renewed, 0); // once per period

    // refund the renewal: money back, GB back
    const renewal = await db.cyrusStorageCharge.findFirstOrThrow({ where: { userId: u.id, kind: "renewal" } });
    const rf = await A.refundStorageCharge(u.id, renewal.idemKey);
    assert.deepEqual(rf, { ok: true, cents: 375 });
    assert.equal(await wallet(u.id), before);
    a = await acct(u.id);
    assert.deepEqual([a.addonGb, a.addonStatus], [0, "canceled"]);
    assert.equal((await A.refundStorageCharge(u.id, renewal.idemKey)).ok, false); // once
  });

  it("cancel at renewal lapses the add-on and an over-quota account gets the grace, nothing deleted", async () => {
    const u = await mkUser(5_000);
    S.setStorageDepsForTests({ tier: async () => "free", config: async () => C.parseStorageConfig({ cyrus_storage_quota_free_gb: "0.00001" }) });
    await db.modBuild.create({ data: { id: `mb${key()}`.slice(0, 22), userId: u.id, prompt: "p", mcVersion: "1.21.11", status: "succeeded", jarPath: "/nonexistent/c.jar", jarSize: 60_000, jarSha256: SHA("d") } });
    assert.equal((await A.setStorageAddonWallet(u, 1, key())).state, "active");
    assert.equal((await S.recomputeStorage(u.id)).graceUntil, null); // under quota with the add-on
    assert.equal((await A.cancelStorageAddon(u, true)).ok, true);
    const end = (await acct(u.id)).addonPeriodEnd!;
    const s = await A.storageRenewalSweep(new Date(end.getTime() + 1000));
    assert.equal(s.lapsed, 1);
    const a = await acct(u.id);
    assert.equal(a.addonStatus, "canceled");
    assert.ok(a.graceUntil && a.graceUntil.getTime() > Date.now() + 29 * 86_400_000, "30-day grace after the drop");
    assert.equal(await db.modBuild.count({ where: { userId: u.id } }), 1);
  });

  it("insufficient funds charges nothing", async () => {
    S.setStorageDepsForTests({ tier: async () => "free", config: async () => C.parseStorageConfig({}) });
    const u = await mkUser(100);
    const r = await A.setStorageAddonWallet(u, 10, key());
    assert.equal(r.state, "insufficient_funds");
    assert.equal(await wallet(u.id), 100);
    assert.equal(await db.cyrusStorageCharge.count({ where: { userId: u.id } }), 0);
  });

  it("event path, entitlement mirror and reconcile apply a charge exactly once", async () => {
    const u = await mkUser(0);
    const ref = A.storageRef(u.id, 7, key());
    const e = A.storageEnvelope("purchase.completed", u.id, { idemKey: ref, method: "wallet", gb: 7, gbFrom: 0, change: "purchase", cents: 525, periodEnd: null });
    assert.equal((await A.applyStorageEvent(e)).applied, true);
    assert.equal((await A.applyStorageEvent(e)).applied, false);
    await A.applyMirroredStorageCharge(u.id, { idemKey: ref, gb: 7, cents: 525, at: new Date().toISOString(), refundedCents: 0 });
    assert.equal(await db.cyrusStorageCharge.count({ where: { idemKey: ref } }), 1);
    assert.equal((await acct(u.id)).addonGb, 7);
    // a lost apply: the wallet moved, no charge row -> the mirror applies it once
    const u2 = await mkUser(0);
    const ref2 = A.storageRef(u2.id, 3, key());
    await A.applyMirroredStorageCharge(u2.id, { idemKey: ref2, gb: 3, cents: 255, at: new Date().toISOString(), refundedCents: 0 });
    await A.applyMirroredStorageCharge(u2.id, { idemKey: ref2, gb: 3, cents: 255, at: new Date().toISOString(), refundedCents: 0 });
    assert.equal(await db.cyrusStorageCharge.count({ where: { idemKey: ref2 } }), 1);
    assert.equal((await acct(u2.id)).addonGb, 3);
    // a refund reported by the mirror takes it back once
    await A.applyMirroredStorageCharge(u2.id, { idemKey: ref2, gb: 3, cents: 255, at: new Date().toISOString(), refundedCents: 255 });
    assert.equal((await acct(u2.id)).addonGb, 0);
    // reconcile from the wallet
    const u3 = await mkUser(1000);
    const { getHost } = await import("../lib/cyrus/host/index.ts");
    const ref3 = A.storageRef(u3.id, 2, key());
    const c = await getHost().billing.wallet!.charge({ userId: u3.id, cents: 170, description: "Cyrus storage +2 GB monthly", reference: ref3 });
    assert.equal(c.ok, true);
    const rc = await A.reconcileStorageCharges({ userId: u3.id }, new Date(Date.now() + 15 * 60_000));
    assert.equal(rc.applied, 1);
    assert.equal((await A.reconcileStorageCharges({ userId: u3.id }, new Date(Date.now() + 15 * 60_000))).applied, 0);
    assert.equal((await acct(u3.id)).addonGb, 2);
  });
});

