// Cyrus customer app (r39) screenshots (run ON node-2 against `devhost dev`). Not part of the app.
//   devhost run -- node scripts/cyrus/app-shots.mjs   (env: BASE, TOKENS, OUT, SHOTS=name,name)
// Writes <OUT>/app-*.png and prints page errors + horizontal overflow per shot.
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots/app";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".studio-tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
const A = "/dashboard/cyrus/app";
async function shot(name, url, { view = "desktop", theme = "dark", wait = ".cx-page", act, full = true, who = "all", tour = false } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  // the portal frame scrolls inside a fixed-height box, so a "full" shot uses a tall viewport instead of fullPage
  const ctx = await browser.newContext({ viewport: { width: v.width, height: full ? (v.mobile ? 2000 : 1700) : v.height }, deviceScaleFactor: v.mobile ? 2 : 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript(([t, tr]) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); if (!tr) localStorage.setItem("cyrus-app-tour-v1", "done"); else localStorage.removeItem("cyrus-app-tour-v1"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, [theme, tour]);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  const res = await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForSelector(wait, { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  await page.waitForTimeout(1500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(900);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: false, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
await shot("app-home-dark", A);
await shot("app-home-light", A, { theme: "light" });
await shot("app-home-phone", A, { view: "phone" });
await shot("app-tour-dark", A, { tour: true, full: false, wait: ".cx-tour" });
