// Cyrus storage (r51) screenshots: seed the devhost THROWAWAY database (run AFTER studio-fixtures.ts and app-fixtures.ts).
// usr_studio_all: stored jars + a large sound, a 1 GB wallet add-on, quota setting lowered so the meter sits in the
// warning band; usr_studio_free: over quota with no grace (the "storage full" state). Fixture data for screenshots only.
// Refuses to run against anything but devhost's wt_* database.
//   devhost run -- npx tsx scripts/cyrus/storage-fixtures.ts
process.env.CYRUS_STORAGE = "1";
import { db } from "../../lib/db";
import { cyrusDb } from "../../lib/cyrus/db";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const DAY = 86_400_000;
const set = (key: string, value: string) => db.setting.upsert({ where: { key }, update: { value }, create: { key, value } });

async function main() {
  await set("cyrus_storage_quota_all_gb", "2");
  await set("cyrus_storage_quota_free_gb", "0.05");
  const { recomputeStorage } = await import("../../lib/cyrus/storage/service");
  const sizes = [612_000_000, 418_000_000, 377_000_000, 296_000_000, 241_000_000, 188_000_000];
  const builds = await cyrusDb.modBuild.findMany({ where: { userId: "usr_studio_all", status: "succeeded" }, orderBy: { createdAt: "asc" } });
  for (const [i, b] of builds.entries()) {
    await cyrusDb.modBuild.update({ where: { id: b.id }, data: { jarPath: `/var/lib/nxeon/modbuilds/${b.id}.jar`, jarSize: sizes[i % sizes.length], jarSha256: (b.id + "0".repeat(64)).replace(/[^0-9a-f]/g, "a").slice(0, 64), ...(b.id === "mbappbounty" ? { createdAt: new Date(Date.now() - 120 * DAY) } : {}) } });
  }
  const now = new Date();
  const start = new Date(now.getTime() - 9 * DAY), end = new Date(now.getTime() + 21 * DAY);
  await cyrusDb.cyrusStorageAccount.upsert({ where: { userId: "usr_studio_all" }, create: { userId: "usr_studio_all", addonGb: 1, addonStatus: "active", addonMethod: "wallet", addonPeriodStart: start, addonPeriodEnd: end }, update: { addonGb: 1, addonStatus: "active", addonMethod: "wallet", addonPeriodStart: start, addonPeriodEnd: end, addonNextGb: null, graceUntil: null, overSince: null } });
  await cyrusDb.cyrusStorageCharge.upsert({ where: { idemKey: "cst:usr_studio_all:g1:fixturefixturefix" }, update: {}, create: { idemKey: "cst:usr_studio_all:g1:fixturefixturefix", userId: "usr_studio_all", kind: "purchase", gbFrom: 0, gbTo: 1, cents: 85, method: "wallet", periodEnd: end } });
  const a = await recomputeStorage("usr_studio_all");
  console.log("all:", a.usedBytes, "/", a.quotaBytes);

  await cyrusDb.modBuild.deleteMany({ where: { id: "mbstoragefree" } });
  await cyrusDb.modBuild.create({ data: { id: "mbstoragefree", userId: "usr_studio_free", prompt: "Lantern festival with floating lights", mcVersion: "1.21.11", pluginName: "LanternFest", version: "1.0.0", status: "succeeded", jarName: "LanternFest-1.0.0.jar", jarPath: "/var/lib/nxeon/modbuilds/mbstoragefree.jar", jarSize: 61_000_000, jarSha256: "f".repeat(64) } });
  await recomputeStorage("usr_studio_free");
  await cyrusDb.cyrusStorageAccount.update({ where: { userId: "usr_studio_free" }, data: { graceUntil: null } });
  console.log("free: over quota, no grace");
}
main().then(() => process.exit(0), (e) => { console.error(e); process.exit(1); });

