// Cyrus storage (r51) screenshots (run ON node-2 against `devhost dev` with CYRUS_CUSTOMER_APP=1 CYRUS_STORAGE=1
// CYRUS_STORAGE_ADDONS=1, after scripts/cyrus/storage-fixtures.ts). Not part of the app.
//   devhost run -- node scripts/cyrus/storage-shots.mjs   (env: BASE, TOKENS, OUT, SHOTS=name,name, ADMIN=1 for admin shots)
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots/storage";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".studio-tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
async function shot(name, url, { view = "desktop", theme = "dark", wait = ".cx-page", act, h, who = "all", cookie } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: h ?? (v.mobile ? 2400 : 1900) }, deviceScaleFactor: v.mobile ? 2 : 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: cookie ?? tok[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript(([t]) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-app-tour-v1", "done"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, [theme]);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  const res = await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForSelector(wait, { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  await page.waitForTimeout(1500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(700);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: false, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
const S = "/dashboard/cyrus/app/account?tab=storage";
const slide = (gb) => async (p) => { await p.locator("#cx-st-gb").fill(String(gb)); await p.locator("#add-storage").scrollIntoViewIfNeeded(); };
if (process.env.ADMIN !== "1") {
  await shot("storage-meter-dark", S);
  await shot("storage-meter-light", S, { theme: "light" });
  await shot("storage-meter-phone", S, { view: "phone" });
  await shot("storage-full-dark", S, { who: "free" });
  await shot("storage-slider-dark", S, { act: slide(20), h: 1000 });
  await shot("storage-slider-phone", S, { view: "phone", act: slide(67), h: 1500 });
  await shot("storage-cleanup-dark", S, { h: 1100, act: async (p) => { await p.locator("#clean-up").scrollIntoViewIfNeeded(); } });
} else {
  const A = process.env.ADMIN_TOKEN;
  await shot("storage-admin-dark", "/admin/cyrus/storage", { wait: "[data-cyrus-admin]", cookie: A });
  await shot("storage-admin-phone", "/admin/cyrus/storage", { view: "phone", wait: "[data-cyrus-admin]", cookie: A });
}
await browser.close();

