const csvCell = (v: unknown) => { const s = v instanceof Date ? v.toISOString() : v === null || v === undefined ? "" : String(v); return /[",\n]/.test(s) || /^[=+\-@]/.test(s) ? `"${(/^[=+\-@]/.test(s) ? "'" : "") + s.replace(/"/g, '""')}"` : s; };
export const toCsv = (rows: unknown[][]) => rows.map((r) => r.map(csvCell).join(",")).join("\n") + "\n";

/** CSV: kind "accounts" (every measured account) or "summary" (the tab's numbers, one metric per row). */
export async function storageCsv(kind: "accounts" | "summary"): Promise<string> {
  if (kind === "accounts") {
    const rows = await db.cyrusStorageAccount.findMany({ orderBy: { usedBytes: "desc" }, take: 200_000 });
    const emails = new Map((await getHost().users.emails(rows.map((r) => r.userId)).catch(() => [])).map((u) => [u.id, u.email]));
    return toCsv([["userId", "email", "usedBytes", "pendingBytes", "quotaBytes", "addonGb", "addonStatus", "addonPeriodEnd", "overSince", "graceUntil", "computedAt", ...CATEGORY_ORDER.map((c) => `bytes_${c}`)],
      ...rows.map((r) => { const b = (r.breakdown as { byCategory?: Record<string, number> } | null)?.byCategory ?? {}; return [r.userId, emails.get(r.userId) ?? "", N(r.usedBytes), N(r.pendingBytes), N(r.quotaBytes), r.addonGb, r.addonStatus, r.addonPeriodEnd, r.overSince, r.graceUntil, r.computedAt, ...CATEGORY_ORDER.map((c) => N(b[c]))]; })]);
  }
  const p = await platformStorage(25);
  const rows: unknown[][] = [["section", "metric", "value"]];
  rows.push(["accounts", "count", p.accounts.count], ["accounts", "usedBytes", p.accounts.usedBytes + p.accounts.pendingBytes], ["accounts", "quotaBytes", p.accounts.quotaBytes]);
  for (const c of CATEGORY_ORDER) rows.push(["content", c, p.byCategory[c]]);
  rows.push(["raw", "jarBytes", p.raw.jarBytes], ["raw", "assetBytes", p.raw.assetBytes]);
  for (const s of p.library.byStatus) rows.push(["library.status", s.status, s.bytes]);
  for (const t of p.library.byTier) rows.push(["library.tier", t.tier, t.bytes]);
  rows.push(["library", "motion-effects", p.library.motion.bytes]);
  for (const d of p.disks) rows.push(["disk", `${d.host} ${d.mount}`, `${d.used}/${d.size} (${d.pct}%)`]);
  for (const d of p.dirs) rows.push(["dir", `${d.host} ${d.label} ${d.path}`, d.bytes ?? "missing"]);
  rows.push(["addons", "active", p.addons.active], ["addons", "gb", p.addons.gb], ["addons", "runRateCents", p.addons.runRateCents], ["addons", "revenue30dCents", p.addons.revenue30dCents]);
  rows.push(["cost", "usdPerGbMonth", p.cost.usdPerGbMonth], ["cost", "customerUsdMonth", p.cost.customerUsd.toFixed(2)], ["cost", "diskUsedUsdMonth", p.cost.diskUsedUsd.toFixed(2)]);
  for (const a of p.alerts) rows.push(["alert", a.level, a.text]);
  return toCsv(rows);
}

