const DAY = 86_400_000;
const N = (x: unknown) => Number(x ?? 0) || 0;
export const MOTION_KINDS = ["flipbook", "particle-texture", "animation-clip", "animated-model", "motion-preset", "effect-preset"];
export const DIST_BUCKETS: [string, number][] = [["< 10 MB", 10e6], ["10-100 MB", 100e6], ["100 MB-1 GB", GB], ["1-5 GB", 5 * GB], ["5-25 GB", 25 * GB], ["25-50 GB", 50 * GB], ["50 GB+", Infinity]];

export type DiskRow = { host: string; mount: string; size: number; used: number; avail: number; pct: number; source: "live" | "report" };
export type DirRow = { host: string; label: string; path: string; bytes: number | null };
export type StorageAlert = { level: "warn" | "crit"; text: string };

export type PlatformStorage = {
  at: Date;
  accounts: { count: number; usedBytes: number; pendingBytes: number; quotaBytes: number; top: { userId: string; email: string | null; usedBytes: number; quotaBytes: number; addonGb: number; overSince: Date | null; graceUntil: Date | null }[]; distribution: { label: string; count: number }[] };
  byCategory: Record<StorageCategory, number>;
  raw: { jarBytes: number; jars: number; assetBytes: number; assets: number };
  library: { byStatus: { status: string; count: number; bytes: number }[]; byTier: { tier: string; count: number; bytes: number }[]; motion: { count: number; bytes: number } };
  growth: { day: string; totalBytes: number; accounts: number }[];
  breaches: { userId: string; email: string | null; usedBytes: number; quotaBytes: number; overSince: Date | null; graceUntil: Date | null }[];
  addons: { active: number; gb: number; runRateCents: number; revenue30dCents: number; refunded30dCents: number; pastDue: number };
  disks: DiskRow[]; dirs: DirRow[]; reportAt: string | null; reportError: string | null;
  cost: { usdPerGbMonth: number; customerUsd: number; diskUsedUsd: number };
  alerts: StorageAlert[];
};

async function liveDisks(): Promise<DiskRow[]> {
  const out: DiskRow[] = [];
  for (const m of ["/", "/tank"]) {
    try {
      const s = await statfs(m);
      const size = s.blocks * s.bsize, avail = s.bavail * s.bsize, used = size - s.bfree * s.bsize;
      out.push({ host: "this host", mount: m, size, used, avail, pct: size ? Math.round((used / (used + avail)) * 1000) / 10 : 0, source: "live" });
    } catch { /* not mounted here */ }
  }
  return out;
}

type ReportRow = { host: string; t: string; mount?: string; size?: number; used?: number; avail?: number; label?: string; path?: string; bytes?: number; missing?: boolean; error?: string };
export async function readStorageReport(path = process.env.CYRUS_STORAGE_REPORT || "/var/lib/cyrus/storage-report.json"): Promise<{ at: string | null; disks: DiskRow[]; dirs: DirRow[]; error: string | null }> {
  let j: { at?: string; rows?: ReportRow[] };
  try { j = JSON.parse(await readFile(path, "utf8")); } catch { return { at: null, disks: [], dirs: [], error: "no report yet (scripts/cyrus/storage-report.sh is not installed or has not run)" }; }
  const rows = Array.isArray(j.rows) ? j.rows : [];
  return {
    at: typeof j.at === "string" ? j.at : null,
    disks: rows.filter((r) => (r.t === "disk" || r.t === "pool") && r.mount).map((r) => { const size = N(r.size), used = N(r.used), avail = N(r.avail); return { host: String(r.host), mount: String(r.mount), size, used, avail, pct: used + avail ? Math.round((used / (used + avail)) * 1000) / 10 : 0, source: "report" as const }; }),
    dirs: rows.filter((r) => r.t === "dir").map((r) => ({ host: String(r.host), label: String(r.label), path: String(r.path), bytes: r.missing ? null : N(r.bytes) })),
    error: rows.find((r) => r.t === "error")?.error ? `node-2: ${rows.find((r) => r.t === "error")!.error}` : null,
  };
}

/** Pure: disk/pool alerts from thresholds. */
export function diskAlerts(disks: DiskRow[], warn: number, crit: number): StorageAlert[] {
  return disks.filter((d) => d.pct >= warn).map((d) => ({ level: d.pct >= crit ? "crit" : "warn", text: `${d.host} ${d.mount} is ${d.pct}% full (${d.pct >= crit ? `critical at ${crit}%` : `warning at ${warn}%`})` }));
}

/** Pure: size distribution of accounts. */
export function distribution(used: number[]): { label: string; count: number }[] {
  const out = DIST_BUCKETS.map(([label]) => ({ label, count: 0 }));
  for (const u of used) out[DIST_BUCKETS.findIndex(([, max]) => u < max)].count++;
  return out;
}

