// Cyrus GDPR export (r40): GET ?user=<id> -> a JSON download of every Cyrus row about that person (lib/cyrus/admin/gdpr.ts).
// ADMIN only (action user.gdpr.export), real account, not impersonating, preview list; anything else is a plain 404.
// Every export is audited. Nxeon's own account data is not included (Nxeon's GDPR process covers it).
import { cyrusAdminApiUser } from "@/lib/cyrus/admin/gate";
import { cyrusAudit } from "@/lib/cyrus/admin/audit";
import { gdprExport } from "@/lib/cyrus/admin/gdpr";
import { getHost } from "@/lib/cyrus/host";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const nf = () => new Response("Not found", { status: 404 });

export async function GET(req: Request) {
  const admin = await cyrusAdminApiUser("user.gdpr.export");
  if (!admin) return nf();
  const id = new URL(req.url).searchParams.get("user") ?? "";
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return nf();
  const u = await getHost().users.get(id);
  if (!u) return nf();
  const data = await gdprExport(u.id, u.email);
  await cyrusAudit({ actorId: admin.id, action: "user.gdpr.export", target: `user:${u.id}`, after: { tables: Object.keys(data.tables as object).length } });
  return new Response(JSON.stringify(data, (_k, v) => (typeof v === "bigint" ? v.toString() : v), 1), {
    headers: { "content-type": "application/json; charset=utf-8", "content-disposition": `attachment; filename="cyrus-export-${u.id}.json"`, "cache-control": "no-store" },
  });
}

