import { realUser } from "@/lib/auth";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { platformStorage } from "@/lib/cyrus/admin/storage";
import { CATEGORY_LABEL, CATEGORY_ORDER } from "@/lib/cyrus/storage/accounting";
import { loadStorageConfig, storageAddonsEnabled, storageEnabled } from "@/lib/cyrus/storage/config";
import { fmtBytes, fmtCents } from "@/lib/cyrus/storage/pricing";
import { adminCyrusSetSetting } from "@/lib/actions-cyrus-admin";
import { AreaChart, MeterBar } from "@/components/ui/charts";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Flash, Hidden, Section, TableWrap, UserLink, n, tdRow, thCls, usd, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Storage");
}

const LIB_STATUS: Record<string, string> = { "pending-checks": "Staging (checks pending)", held: "Staging (held for review)", published: "Published", removed: "Removed (bytes purged, hash kept)" };
const TIER: Record<string, string> = { cc0: "CC0", "cc-by": "CC-BY", "proprietary-nxeon": "Proprietary (owner SFX + templates)", "user-contributed": "Customer contributions" };

/** Cyrus r51: total storage across every account, the content kinds, the asset library, backups and disks, cost, add-on revenue. */
export default async function CyrusStorageAdmin({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("storage");
  const me = (await realUser())!;
  const sp = await searchParams;
  const [p, cfg] = await Promise.all([platformStorage(25), loadStorageConfig()]);
  const total = p.accounts.usedBytes + p.accounts.pendingBytes;
  const maxCat = Math.max(1, ...CATEGORY_ORDER.map((c) => p.byCategory[c]));
  const canSet = canCyrusAdmin(me.role, "setting.set");
  const canExport = canCyrusAdmin(me.role, "storage.export");
  const libBytes = p.library.byStatus.filter((s) => s.status !== "removed").reduce((a, s) => a + s.bytes, 0);
  return (
    <div data-cyrus-storage>
      <Flash sp={sp} />
      <div className="mb-4 flex flex-wrap items-center gap-2">
        {storageEnabled() ? <Badge tone="green">metering + enforcement on</Badge> : <Badge tone="slate">CYRUS_STORAGE off: nothing measured or enforced</Badge>}
        {storageAddonsEnabled() ? <Badge tone="green">add-ons on sale</Badge> : <Badge tone="slate">add-ons off</Badge>}
        <Badge tone="amber">prices and quotas are placeholders</Badge>
        {canExport ? <span className="ml-auto flex gap-2"><a className="btn-secondary text-xs" href="/api/admin/cyrus/storage?kind=summary">CSV: summary</a><a className="btn-secondary text-xs" href="/api/admin/cyrus/storage?kind=accounts">CSV: accounts</a></span> : null}
      </div>

      {p.alerts.length ? (
        <div className="mb-5 space-y-2" role="status">
          {p.alerts.map((a, i) => <div key={i} className={`rounded-lg border px-3 py-2 text-sm ${a.level === "crit" ? "border-red-500/40 bg-red-500/10 text-red-200" : "border-amber-500/40 bg-amber-500/10 text-amber-100"}`}><b>{a.level === "crit" ? "Critical" : "Warning"}:</b> {a.text}</div>)}
        </div>
      ) : null}

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Customer storage (counted)" value={fmtBytes(total)} delta={`${n(p.accounts.count)} accounts measured`} />
        <StatCard label="Quota handed out" value={fmtBytes(p.accounts.quotaBytes)} delta={p.accounts.quotaBytes ? `${Math.round((total / p.accounts.quotaBytes) * 100)}% used` : "–"} />
        <StatCard label="Estimated disk cost / month" value={usd(p.cost.diskUsedUsd)} delta={`customers ${usd(p.cost.customerUsd)} at $${p.cost.usdPerGbMonth}/GB`} />
        <StatCard label="Add-on run rate / month" value={fmtCents(p.addons.runRateCents)} delta={`${n(p.addons.active)} active · ${n(p.addons.gb)} GB · 30 d ${fmtCents(p.addons.revenue30dCents)}`} deltaGood={p.addons.pastDue === 0} />
      </div>

      <Section title="Disks and pools" sub={p.reportAt ? `live statfs + nightly report (${when(p.reportAt)})` : "live statfs on this host; node-2, ZFS pools and directory sizes need the nightly report (scripts/cyrus/storage-report.sh, not installed)"}>
        {p.disks.length ? (
          <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Host</th><th>Mount / pool</th><th>Used</th><th>Size</th><th className="w-1/3">Usage</th><th>Source</th></tr></thead>
            <tbody>{p.disks.map((d) => (
              <tr key={`${d.host}${d.mount}${d.source}`} className={tdRow}><td>{d.host}</td><td className="font-mono text-xs">{d.mount}</td><td>{fmtBytes(d.used)}</td><td>{fmtBytes(d.size)}</td>
                <td><div className="flex items-center gap-2"><MeterBar value={d.pct} max={100} color={d.pct >= cfg.poolCritPct ? "#ef4444" : d.pct >= cfg.poolWarnPct ? "#f59e0b" : "#6f47f5"} /><span className="w-12 text-right text-xs tabular-nums">{d.pct}%</span></div></td><td className="text-xs text-slate-500">{d.source}</td></tr>
            ))}</tbody></table></TableWrap>
        ) : <Empty>No disk readings on this host.</Empty>}
        <p className="mt-2 text-xs text-slate-500">Alerts at {cfg.poolWarnPct}% (warning) and {cfg.poolCritPct}% (critical); the same thresholds run in scripts/cyrus/alert-check.sh (rules disk-*).</p>
      </Section>

      <div className="grid min-w-0 gap-4 lg:grid-cols-2">
        <Section title="What customers store" sub="from per-account measurements: shared bytes count once per account">
          <ul className="space-y-2">{CATEGORY_ORDER.map((c) => (
            <li key={c} className="text-sm"><div className="flex justify-between gap-2"><span>{CATEGORY_LABEL[c]}</span><span className="tabular-nums">{fmtBytes(p.byCategory[c])}</span></div><MeterBar value={p.byCategory[c]} max={maxCat} className="mt-1" /></li>
          ))}</ul>
          <p className="mt-3 text-xs text-slate-500">Raw tables (every account, no dedupe): {n(p.raw.jars)} stored jars {fmtBytes(p.raw.jarBytes)} · {n(p.raw.assets)} project assets {fmtBytes(p.raw.assetBytes)}.</p>
        </Section>
        <Section title="Account sizes" sub="distribution of measured accounts">
          <ul className="space-y-2">{p.accounts.distribution.map((b) => (
            <li key={b.label} className="text-sm"><div className="flex justify-between"><span>{b.label}</span><span className="tabular-nums">{n(b.count)}</span></div><MeterBar value={b.count} max={Math.max(1, ...p.accounts.distribution.map((x) => x.count))} className="mt-1" /></li>
          ))}</ul>
        </Section>
      </div>

      <Section title="Growth" sub="customer storage per day (daily snapshot by the storage sweep)">
        {p.growth.length >= 2 ? (
          <AreaChart id="cyrus-storage-growth" series={[{ name: "Customer storage", data: p.growth.map((g) => g.totalBytes), color: "#6f47f5" }]} xLabels={p.growth.map((g) => g.day.slice(5))} yLabel={(v) => fmtBytes(v)} />
        ) : <Empty waitsFor="CYRUS_STORAGE=1 and two daily snapshots">{p.growth.length ? `One snapshot so far (${p.growth[0].day}: ${fmtBytes(p.growth[0].totalBytes)}).` : "No snapshots yet."}</Empty>}
      </Section>

      <div className="grid min-w-0 gap-4 lg:grid-cols-2">
        <Section title="Asset library" sub={`${fmtBytes(libBytes)} kept (not removed)`}>
          <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Status</th><th>Entries</th><th>Bytes</th></tr></thead>
            <tbody>{p.library.byStatus.length ? p.library.byStatus.map((s) => <tr key={s.status} className={tdRow}><td>{LIB_STATUS[s.status] ?? s.status}</td><td>{n(s.count)}</td><td>{fmtBytes(s.bytes)}</td></tr>) : <tr className={tdRow}><td colSpan={3} className="text-slate-500">No catalog entries in this database.</td></tr>}</tbody></table></TableWrap>
          <TableWrap><table className="mt-3 w-full text-sm"><thead><tr className={thCls}><th>Tier</th><th>Entries</th><th>Bytes</th></tr></thead>
            <tbody>{p.library.byTier.map((t) => <tr key={t.tier} className={tdRow}><td>{TIER[t.tier] ?? t.tier}</td><td>{n(t.count)}</td><td>{fmtBytes(t.bytes)}</td></tr>)}
              <tr className={tdRow}><td>Motion and effects kinds</td><td>{n(p.library.motion.count)}</td><td>{fmtBytes(p.library.motion.bytes)}</td></tr></tbody></table></TableWrap>
          <p className="mt-2 text-xs text-slate-500">Bytes are the catalog&apos;s recorded original sizes; derivatives (thumbs, previews) are extra and live in the object store directory below.</p>
        </Section>
        <Section title="Directories, backups and dumps" sub="from the nightly report (du, read only)">
          {p.dirs.length ? (
            <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Host</th><th>What</th><th>Path</th><th>Size</th></tr></thead>
              <tbody>{p.dirs.map((d) => <tr key={d.host + d.path} className={tdRow}><td>{d.host}</td><td>{d.label}</td><td className="font-mono text-xs">{d.path}</td><td>{d.bytes === null ? <span className="text-slate-500">missing</span> : fmtBytes(d.bytes)}</td></tr>)}</tbody></table></TableWrap>
          ) : <Empty waitsFor="scripts/cyrus/storage-report.sh (nightly timer, owner installs)">{p.reportError ?? "No directory sizes yet."}</Empty>}
        </Section>
      </div>

      <Section title="Top accounts" sub={`largest ${p.accounts.top.length} of ${n(p.accounts.count)}`}>
        {p.accounts.top.length ? (
          <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Account</th><th>Used</th><th>Quota</th><th className="w-1/4">Usage</th><th>Add-on</th><th>State</th></tr></thead>
            <tbody>{p.accounts.top.map((a) => { const pc = a.quotaBytes ? Math.round((a.usedBytes / a.quotaBytes) * 100) : 0; return (
              <tr key={a.userId} className={tdRow}><td><UserLink id={a.userId} email={a.email} /></td><td>{fmtBytes(a.usedBytes)}</td><td>{fmtBytes(a.quotaBytes)}</td>
                <td><div className="flex items-center gap-2"><MeterBar value={Math.min(100, pc)} max={100} color={pc >= 100 ? "#ef4444" : pc >= 80 ? "#f59e0b" : "#6f47f5"} /><span className="w-10 text-right text-xs tabular-nums">{pc}%</span></div></td>
                <td>{a.addonGb ? `${a.addonGb} GB` : "–"}</td><td>{a.overSince ? (a.graceUntil && a.graceUntil.getTime() > Date.now() ? <Badge tone="amber">grace to {when(a.graceUntil).slice(0, 10)}</Badge> : <Badge tone="red">writes paused</Badge>) : <Badge tone="slate">ok</Badge>}</td></tr>
            ); })}</tbody></table></TableWrap>
        ) : <Empty waitsFor="CYRUS_STORAGE=1 (the sweep measures accounts)">No accounts measured yet.</Empty>}
      </Section>

      <Section title="Quota breaches" sub="over quota now; nothing is ever deleted automatically">
        {p.breaches.length ? (
          <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Account</th><th>Used</th><th>Quota</th><th>Over since</th><th>Grace until</th></tr></thead>
            <tbody>{p.breaches.map((b) => <tr key={b.userId} className={tdRow}><td><UserLink id={b.userId} email={b.email} /></td><td>{fmtBytes(b.usedBytes)}</td><td>{fmtBytes(b.quotaBytes)}</td><td>{when(b.overSince)}</td><td>{b.graceUntil ? when(b.graceUntil) : <span className="text-red-300">none: writes paused</span>}</td></tr>)}</tbody></table></TableWrap>
        ) : <Empty>No account is over its quota.</Empty>}
      </Section>

      <Section title="Cost input" sub="the estimate above multiplies GB used by this">
        {canSet ? (
          <form action={adminCyrusSetSetting} className="flex flex-wrap items-center gap-2">
            <Hidden name="key" value="cyrus_storage_disk_cost_usd_gb_month" /><Hidden name="back" value="/admin/cyrus/storage" />
            <label className="text-sm" htmlFor="disk-cost">Disk cost, USD per GB per month</label>
            <input id="disk-cost" name="value" type="number" min={0} step="0.001" defaultValue={cfg.diskCostUsdPerGbMonth} className="input w-28 py-1 text-xs" />
            <button className="btn-secondary px-2 py-1 text-xs">Save</button>
            <span className="text-xs text-slate-500">Quotas, price bands, rule, grace and alert levels: Audit &amp; settings, group Storage.</span>
          </form>
        ) : <p className="text-sm text-slate-400">${cfg.diskCostUsdPerGbMonth} per GB per month (platform role needed to change it).</p>}
      </Section>
    </div>
  );
}

