cd /tank/dev-worktrees/cyrus-r51 && cat > test/cyrus-storage-admin.test.ts <<'EOF'
// r51 admin storage: distribution buckets, disk/pool alerts, CSV (formula-injection safe), the tab + export permission.
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { diskAlerts, distribution, toCsv, readStorageReport } from "../lib/cyrus/admin/storage";
import { CYRUS_ADMIN_TABS, canCyrusAdmin, canSeeCyrusTab } from "../lib/cyrus/admin/perms";
import { writeFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const GB = 1024 ** 3;
describe("admin storage", () => {
  it("distribution buckets", () => {
    const d = distribution([0, 5e6, 50e6, 0.5 * GB, 2 * GB, 10 * GB, 30 * GB, 80 * GB]);
    assert.deepEqual(d.map((b) => b.count), [2, 1, 1, 1, 1, 1, 1]);
  });
  it("disk alerts at warn / crit", () => {
    const a = diskAlerts([{ host: "primary", mount: "/", size: 100, used: 85, avail: 15, pct: 85, source: "live" }, { host: "node-2", mount: "/tank", size: 100, used: 95, avail: 5, pct: 95, source: "report" }, { host: "primary", mount: "/tank", size: 100, used: 20, avail: 80, pct: 20, source: "live" }], 80, 90);
    assert.deepEqual(a.map((x) => x.level), ["warn", "crit"]);
    assert.match(a[1].text, /node-2 \/tank is 95% full/);
  });
  it("CSV quotes and neutralises formulas", () => {
    assert.equal(toCsv([["a", "b,c", '=HYPERLINK("x")', 5]]), 'a,"b,c","\'=HYPERLINK(""x"")",5\n');
  });
  it("reads the nightly report; a missing report is an honest empty state", async () => {
    const dir = mkdtempSync(path.join(tmpdir(), "stg-"));
    assert.match((await readStorageReport(path.join(dir, "none.json"))).error ?? "", /no report yet/);
    writeFileSync(path.join(dir, "r.json"), JSON.stringify({ at: "2026-10-11T00:00:00Z", rows: [{ host: "node-2", t: "disk", mount: "/tank", size: 100, used: 40, avail: 60 }, { host: "primary", t: "dir", label: "backups", path: "/tank/backup", bytes: 7 }, { host: "primary", t: "dir", label: "x", path: "/nope", missing: true }] }));
    const r = await readStorageReport(path.join(dir, "r.json"));
