export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
  if (await adminHostBlocked()) notFound();

  // The dedicated login page (app/admin/login) is the one public, unauthenticated
  // route under /admin — render it bare (no Shell, no auth requirement below) so
  // a signed-out visitor doesn't hit `redirect("/admin/login")` on the page that
  // IS /admin/login. middleware.ts injects x-pathname since a Server Component
  // has no other way to read the current path. Still honors the IP allowlist —
  // a locked-out network shouldn't see the login form either.
  const pathname = (await headers()).get("x-pathname") ?? "";
  if (pathname === "/admin/login") {
    if (await adminIpBlocked()) return <RestrictedNetwork />;
    return <>{children}</>;
  }

  const user = await realUser();
  if (!user) redirect("/admin/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  const imp = await impersonating();
  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools

  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
  if (await adminIpBlocked()) return <RestrictedNetwork />;

  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
  // using admin tools. Redirect (don't hard-fail) to their security settings so
  // they can enroll, then come back.
  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
    redirect("/dashboard/settings?require2fa=1");
  }

  // Feature-gated nav entries. The Agency (Sitewave) and Ads (Adloop)
  // consoles are internal/experimental — hidden by default and only surfaced
  // when the operator flips the flag. The pages/routes are never removed;
  // this only drops the nav entry, its sub-tabs and its ⌘K entries.
  const [showAgency, showAds] = await Promise.all([
    getSettingBool("feature_admin_agency", false),
    getSettingBool("feature_admin_ads", false),
  ]);
  const flags = { agency: showAgency, ads: showAds };
  const allowedEntry = (e: AdminNavChild, inheritedArea?: AdminNavChild["area"]) =>
    entryLive(e, flags) && canAccess(user.role, e.area ?? inheritedArea ?? areaForHref(e.href));

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
  // missing model/table can never break the admin layout.
  const soft = (p: Promise<number>) => p.catch(() => 0);
  const [chatUnread, ticketsAwaiting, dmsAwaiting, abuseOpen, feedbackNew, improvementsProposed, coldEmailUnread, jobsFailed24h] = await Promise.all([
    // Live chat: conversations flagged unread for agents (same "needs a reply"
    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
    // Support desk: tickets awaiting a staff reply (open + customer replies),
    // matching the "Awaiting staff" stat on /admin/support.
    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
    // Direct messages: DM threads with a customer reply staff hasn't seen yet.
    soft(db.staffDm.count({ where: { unreadForStaff: true } })),
    // Abuse queue: alerts still OPEN.
    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
    // Feedback: new (untriaged) reports.
    soft(db.feedback.count({ where: { status: "NEW" } })),
    // Improvements board: proposals awaiting the owner's approve/decline.
    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
    // Cold email: unread replies in the reply inbox.
    soft(db.conversation.count({ where: { unread: true } })),
    // Jobs: failures in the last 24h (same window as the command center card).
    soft(db.job.count({ where: { status: "FAILED", updatedAt: { gte: new Date(Date.now() - 24 * 3600_000) } } })),
  ]);

  // Per-route attention counts. An item's badge is the SUM of its own and its
  // children's counts, and <AdminSubTabs /> repeats each child's own count.
  const badges: Record<string, number> = {
    "/admin/chat": chatUnread,
    "/admin/support": ticketsAwaiting,
    "/admin/dms": dmsAwaiting,
    "/admin/abuse": abuseOpen,
    "/admin/feedback": feedbackNew,
    "/admin/improvements": improvementsProposed,
    "/admin/coldemail/inbox": coldEmailUnread,
    "/admin/jobs": jobsFailed24h,
  };

  // RBAC-filter the registry (lib/admin-nav.ts) into what the shell renders.
  // An item links to its first ACCESSIBLE child so no role is ever handed a
  // link that just bounces it to /admin.
  const nav: ShellNavGroup[] = ADMIN_NAV_GROUPS.map((g) => ({
    key: g.key,
    label: g.label,
    items: g.items.flatMap((it): ShellNavItem[] => {
      if (!entryLive(it, flags)) return [];
      const kids = (it.children ?? []).filter((c) => allowedEntry(c, it.area));
      if (it.children?.length ? kids.length === 0 : !allowedEntry(it)) return [];
      const members = kids.length ? kids : [it];
      const sum = members.reduce((n, c) => n + (badges[c.href] ?? 0), 0);
      return [{
        key: it.key,
        label: it.label,
        href: members[0].href,
        icon: it.icon,
        more: it.more,
        badge: sum > 0 ? sum : undefined,
        children: kids.length
          ? kids.map((c) => ({ label: c.label, href: c.href, badge: badges[c.href] > 0 ? badges[c.href] : undefined }))
          : undefined,
      }];
    }),
  })).filter((g) => g.items.length > 0);

  const allowedHrefs = nav.flatMap((g) => g.items.flatMap((i) => (i.children ?? [{ href: i.href }]).map((c) => c.href)));
  const allowedSet = new Set(allowedHrefs);

  const allowedSet = new Set(allowedHrefs);
  const routes: ShellRoute[] = flatAdminRoutes()
    .filter((r) => allowedSet.has(r.href))
    .map((r) => ({ label: r.label, href: r.href, group: r.group, parent: r.parent, keywords: r.keywords }));

  const alerts = await loadShellAlerts(user.role);
  const liveChat = await hasAreaAccess(user, "liveChat").catch(() => false);
  const ui = parseUiCookie((await cookies()).get(ADM_UI_COOKIE)?.value);

  return (
    <>
      {/* Before first paint: scope class + the admin's own theme/density
          preference, so there is no flash of the wrong theme. See
          app/admin/admin-shell.css for why these are NOT the customer
          portal's `data-theme`. */}
      <script
        dangerouslySetInnerHTML={{
          __html:
            "try{var d=document.documentElement;d.classList.add('adm-portal');d.removeAttribute('data-theme');" +
            "var t=localStorage.getItem('nxeon.admin.theme');if(t==='light'||t==='dark')d.setAttribute('data-adm-theme',t);" +
            "if(localStorage.getItem('nxeon.admin.density')==='compact')d.setAttribute('data-adm-density','compact')}catch(e){}",
        }}
      />
      <AdminShell
        nav={nav}
        routes={routes}
        user={{ name: user.name, email: user.email, role: user.role, avatarUrl: user.avatarUrl }}
        alerts={alerts}
        initialUi={ui}
        notifications={notifications.map((n) => ({
          id: n.id,
          title: n.title,
          body: n.body,
          href: n.href,
          readAt: n.readAt ? n.readAt.toISOString() : null,
          createdAt: n.createdAt.toISOString(),
        }))}
      >
        {/* Sub-navigation for items with children, mounted once here so every
            grouped page gets its tab bar without per-page wiring. */}
        <AdminSubTabs badges={badges} allowed={allowedHrefs} />
        {liveChat ? (
          /* ONE live-chat store + event stream per admin tab, mounted at the
             layout so it survives client navigation: the /admin/chat workspace
             and the persistent dock (every other /admin page) share it, and
             ChatNotifier plays the sound / desktop alert from the same stream
             (it replaced the old 10 s unread-count poll). */
          <StaffChatProvider>
            <ChatNotifier />
            {children}
            <ChatDock />
          </StaffChatProvider>
        ) : (
          children
        )}
      </AdminShell>
    </>
  );
}
