// r51 secret Cyrus admin host (CYRUS_ADMIN_HOST): config validation, the routing table, the middleware (404 for the rest,
// noindex, IP allowlist fail-closed, marker never spoofable, CYRUS_ADMIN_HOST_ONLY), and the layouts re-checking it.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { NextRequest } from "next/server";
import { adminHostConfig, adminIpAllowed, isCyrusAdminHost, requestIp, CYRUS_ADMIN_HOST_HEADER } from "../lib/cyrus/bridge/config";
import { cyrusAdminHostRoute, cyrusHostRoute } from "../lib/cyrus/bridge/routing";
import { bridgeConfig } from "../lib/cyrus/bridge/config";

const H = "k3v9q2m8x7w1r5t4.cyrus.my";
const ON = { CYRUS_ADMIN_HOST: H };
const route = (pathname: string, method = "GET") => cyrusAdminHostRoute({ pathname, search: "", method });

describe("admin host config", () => {
  it("off unless set; only a long random label under the Cyrus apex counts", () => {
    assert.deepEqual(adminHostConfig({}).hosts, []);
    assert.deepEqual(adminHostConfig(ON).hosts, [H]);
    for (const bad of ["admin.cyrus.my", "short1234.cyrus.my", `${"a".repeat(20)}.evil.my`, `${"a".repeat(20)}.cyrus.my.evil.test`, `x_${"a".repeat(20)}.cyrus.my`]) {
      assert.deepEqual(adminHostConfig({ CYRUS_ADMIN_HOST: bad }).hosts, [], bad);
      assert.deepEqual(adminHostConfig({ CYRUS_ADMIN_HOST: bad }).invalid, [bad]);
    }
    assert.equal(isCyrusAdminHost(`${H.toUpperCase()}:443`, adminHostConfig(ON)), true);
    assert.equal(isCyrusAdminHost("cyrus.my", adminHostConfig(ON)), false);
  });
  it("rotation overlap: a comma list is accepted", () => assert.equal(adminHostConfig({ CYRUS_ADMIN_HOST: `${H},zz9q2m8x7w1r5t4kk.cyrus.my` }).hosts.length, 2));
  it("HOST_ONLY needs a valid host", () => {
    assert.equal(adminHostConfig({ CYRUS_ADMIN_HOST_ONLY: "1" }).only, false);
    assert.equal(adminHostConfig({ ...ON, CYRUS_ADMIN_HOST_ONLY: "1" }).only, true);
  });
  it("IP allowlist: none = open, set = exact match, unknown IP refused", () => {
    const c = adminHostConfig({ ...ON, CYRUS_ADMIN_IPS: "198.51.100.7, bogus" });
    assert.deepEqual(c.ips, ["198.51.100.7"]);
    assert.equal(adminIpAllowed("198.51.100.7", c), true);
    assert.equal(adminIpAllowed("198.51.100.8", c), false);
    assert.equal(adminIpAllowed("", c), false);
    assert.equal(adminIpAllowed("", adminHostConfig(ON)), true);
    assert.equal(requestIp(new Headers({ "x-forwarded-for": "6.6.6.6, 198.51.100.7" })), "198.51.100.7");
    assert.equal(requestIp(new Headers({ "x-real-ip": "198.51.100.9", "x-forwarded-for": "6.6.6.6" })), "198.51.100.9");
  });
});

describe("admin host routing", () => {
  it("only the Cyrus admin exists", () => {
    for (const p of ["/admin/cyrus", "/admin/cyrus/storage", "/admin/login", "/api/admin/cyrus/storage", "/_next/static/x.js", "/favicon.ico", "/dashboard/settings"]) assert.equal(route(p).kind, "pass", p);
    for (const p of ["/admin/servers", "/admin/cyrus-tokens", "/dashboard", "/dashboard/cyrus", "/pricing", "/staff", "/cyrus-host/sign-in", "/admin/cyrusx"]) assert.equal(route(p).kind, "notfound", p);
    assert.deepEqual(route("/"), { kind: "redirect", url: "/admin/cyrus", status: 302 });
    assert.deepEqual(route("/admin"), { kind: "redirect", url: "/admin/cyrus", status: 302 });
    assert.equal(route("/", "POST").kind, "notfound");
  });
  it("the public Cyrus host never serves /admin", () => {
    const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1" });
    for (const p of ["/admin", "/admin/cyrus", "/admin/login"]) assert.equal(cyrusHostRoute({ pathname: p, search: "", method: "GET", cfg }).kind, "notfound", p);
  });
});

describe("admin host middleware", () => {
  const run = async (url: string, host: string, env: Record<string, string | undefined>, hdrs: Record<string, string> = {}) => {
    const saved = { ...process.env };
    Object.assign(process.env, env);
    try {
      const { middleware } = await import("../middleware");
      return middleware(new NextRequest(url, { headers: { host, ...hdrs } }));
    } finally {
      for (const k of Object.keys(env)) if (saved[k] === undefined) delete process.env[k]; else process.env[k] = saved[k];
    }
  };
  const fwd = (res: Response, name: string) => res.headers.get(`x-middleware-request-${name}`);
  it("serves the Cyrus admin with the marker and noindex; 404 (noindex) for the rest", async () => {
    const ok = await run(`https://${H}/admin/cyrus/storage`, H, ON);
    assert.equal(ok.status, 200);
    assert.equal(fwd(ok, CYRUS_ADMIN_HOST_HEADER), "1");
    assert.match(ok.headers.get("x-robots-tag") ?? "", /noindex/);
    const no = await run(`https://${H}/admin/servers`, H, ON);
    assert.equal(no.status, 404);
    assert.match(no.headers.get("x-robots-tag") ?? "", /noindex/);
    const root = await run(`https://${H}/`, H, ON);
    assert.equal(root.status, 302);
    assert.equal(new URL(root.headers.get("location")!).pathname, "/admin/cyrus");
  });
  it("IP allowlist: other IPs get a 404 before routing", async () => {
    const env = { ...ON, CYRUS_ADMIN_IPS: "198.51.100.7" };
    assert.equal((await run(`https://${H}/admin/cyrus`, H, env, { "x-real-ip": "198.51.100.8" })).status, 404);
    assert.equal((await run(`https://${H}/admin/cyrus`, H, env, { "x-real-ip": "198.51.100.7" })).status, 200);
  });
  it("the marker is stripped on every other host (never spoofable)", async () => {
    const r1 = await run("https://nxeon.cloud/admin/cyrus", "nxeon.cloud", ON, { [CYRUS_ADMIN_HOST_HEADER]: "1" });
    assert.equal(fwd(r1, CYRUS_ADMIN_HOST_HEADER), null);
    const r2 = await run("https://cyrus.my/studio", "cyrus.my", { ...ON, CYRUS_DOMAIN_MODE: "1" }, { [CYRUS_ADMIN_HOST_HEADER]: "1" });
    assert.equal(fwd(r2, CYRUS_ADMIN_HOST_HEADER), null);
  });
  it("CYRUS_ADMIN_HOST_ONLY: /admin/cyrus is gone from every other host", async () => {
    const env = { ...ON, CYRUS_ADMIN_HOST_ONLY: "1", NXEON_ADMIN_HOSTS: "adminhost.nxeon.cloud" };
    assert.equal((await run("https://adminhost.nxeon.cloud/admin/cyrus", "adminhost.nxeon.cloud", env)).status, 404);
    assert.equal((await run("https://adminhost.nxeon.cloud/api/admin/cyrus/storage", "adminhost.nxeon.cloud", env)).status, 404);
    assert.equal((await run("https://adminhost.nxeon.cloud/admin/servers", "adminhost.nxeon.cloud", env)).status, 200);
    assert.equal((await run("https://adminhost.nxeon.cloud/admin/cyrus", "adminhost.nxeon.cloud", { ...ON, NXEON_ADMIN_HOSTS: "adminhost.nxeon.cloud" })).status, 200);
  });
  it("off = unchanged", async () => {
    assert.equal((await run(`https://${H}/admin/servers`, H, { CYRUS_ADMIN_HOST: undefined })).status, 200);
  });
});

describe("layouts re-check the admin host", () => {
  const rd = (p: string) => readFileSync(path.join(__dirname, "..", p), "utf8");
  it("app/admin/layout.tsx allows only /admin/cyrus + /admin/login there and uses the slim chrome", () => {
    const t = rd("app/admin/layout.tsx");
    assert.match(t, /isCyrusAdminHost\(host\)[\s\S]{0,200}p === "\/admin\/login" \|\| p === "\/admin\/cyrus" \|\| p\.startsWith\("\/admin\/cyrus\/"\)/);
    assert.match(t, /CyrusAdminChrome/);
  });
  it("the nginx template and the plan exist, with no real hostname in them", () => {
    const n = rd("deploy/cyrus/nginx-cyrus-admin.conf.template");
    assert.match(n, /server_name __CYRUS_ADMIN_HOST__;/);
    assert.match(n, /X-Robots-Tag "noindex/);
    const doc = rd("deploy/cyrus/CYRUS-ADMIN-HOST.md");
    for (const s of ["## DNS record plan", "## Rotation", "Cloudflare Access", "Certificate Transparency"]) assert.ok(doc.includes(s), s);
    assert.doesNotMatch(n + doc, /\b[a-z0-9]{16,63}\.cyrus\.my\b/);
  });
});

